def test_model_id_aliases_and_passthrough(agentctl):
    assert agentctl.model_id("opus") == "claude-opus-5-5"
    assert agentctl.model_id("sonnet") == "claude-sonnet-5"
    assert agentctl.model_id("haiku") == "claude-haiku-4-5"
    # model trial 2's third arm (CQ·525) — haiku itself stays on claude-haiku-4-5
    assert agentctl.model_id("haiku-5-5") == "claude-haiku-5-5"
    # Phase C gateway aliases (ARCH-102)
    assert agentctl.model_id("gpt5") == "openai/gpt-5"
    assert agentctl.model_id("deepseek") == "deepseek/deepseek-flash"
    assert agentctl.model_id("deepseek-pro") == "deepseek/deepseek-v4-pro"
    assert agentctl.model_id("kimi") == "moonshot/kimi-k2.6"
    # unknown value passes through unchanged (lets a raw model id be used)
    assert agentctl.model_id("claude-future-9") == "claude-future-9"
    # None → the default
    assert agentctl.model_id(None) == agentctl.DEFAULT_MODEL
    # ARCH-134: fable is resolvable so an operator can invoke it by explicit
    # --model. The rule is that we do not pin an agent on fable or let one
    # default to it — a convention about how rosters are written, which
    # nothing here enforces.
    assert agentctl.model_id("fable") == "claude-fable-5-1"
    # never the silent inherited default an unpinned dispatch falls back to
    assert agentctl.DEFAULT_MODEL != agentctl.MODEL_ALIASES["fable"]


def test_claude_model_arg_uses_gateway_group_names(agentctl):
    """ARCH-130: gateway models spawn with the gateway group name so the
    proxy's router fallbacks (deepseek → kimi) fire; a provider string routes
    but LiteLLM treats it as an ad-hoc group with no fallbacks attached."""
    assert agentctl.claude_model_arg("deepseek/deepseek-v4-flash") == "deepseek"
    assert agentctl.claude_model_arg("deepseek/deepseek-v4-pro") == "deepseek-pro"
    assert agentctl.claude_model_arg("moonshot/kimi-k2.6") == "kimi"
    assert agentctl.claude_model_arg("openai/gpt-5") == "gpt5"
    # Anthropic models pass through unchanged
    assert agentctl.claude_model_arg("claude-sonnet-4-6") == "claude-sonnet-4-6"
    # gateway-prefixed literal with no known group: unchanged (still routes,
    # just without fallbacks)
    assert agentctl.claude_model_arg("deepseek/deepseek-reasoner") == (
        "deepseek/deepseek-reasoner"
    )


def test_model_display_name(agentctl):
    """ARCH-138: gateway models attribute under their gateway group name (the
    name the operator/PR readers recognize); Anthropic-direct models attribute as the
    'Claude' brand the agent prompts hardcode as default. Pinned unchanged
    from before the Codex-reviewer PR (819bc824): that change only added the
    `is_codex_model` branch below, so these assertions hold on origin/main too."""
    assert agentctl.model_display_name("deepseek/deepseek-v4-flash") == "deepseek"
    assert agentctl.model_display_name("deepseek/deepseek-v4-pro") == "deepseek-pro"
    assert agentctl.model_display_name("moonshot/kimi-k2.6") == "kimi"
    assert agentctl.model_display_name("openai/gpt-5") == "gpt5"
    assert agentctl.model_display_name("claude-sonnet-4-6") == "Claude"
    assert agentctl.model_display_name("claude-opus-4-8") == "Claude"
    # gateway-prefixed literal with no known group: the raw provider string
    assert agentctl.model_display_name("deepseek/deepseek-reasoner") == (
        "deepseek/deepseek-reasoner"
    )


def test_model_display_name_codex(agentctl):
    """819bc824: a Codex slug has no gateway group, and it is not "Claude" —
    `model_display_name` returns the slug itself, unchanged, so a Codex
    reviewer's posted review and commit trailer name its own model."""
    assert agentctl.model_display_name("gpt-5.6-terra") == "gpt-5.6-terra"


def test_attribution_directive_only_fires_for_gateway(agentctl):
    """ARCH-138: the spawn-injected attribution override fires for gateway
    models (naming the real model in the mandated prefix) and is empty for
    Anthropic — where the prompt's 'Claude' default is already correct and the
    Task-dispatched path, which never reaches this injection, depends on it.
    Pinned unchanged from before the Codex-reviewer PR (819bc824): that change
    only added the `is_codex_model` branch covered by the test below, so these
    assertions hold on origin/main too."""
    # Anthropic → no injection; the prompt's "Claude" default stands
    assert agentctl.attribution_directive("claude-sonnet-4-6", "reviewer") == ""
    assert agentctl.attribution_directive("claude-opus-4-8", "security-reviewer") == ""
    # gateway → names the real model on both attribution surfaces: the mandated
    # PR-comment prefix AND the commit trailer (ARCH-138), and instructs the
    # model to substitute it wherever the prompt/harness would write "Claude"
    d = agentctl.attribution_directive("deepseek/deepseek-v4-flash", "reviewer")
    assert "Comment by deepseek (reviewer):" in d
    assert "Co-Authored-By: deepseek <noreply@convivy.com>" in d
    assert "Claude" in d
    # additive: appends cleanly onto agent["body"] with a separating blank line
    assert d.startswith("\n\n")


def test_attribution_directive_fires_for_codex(agentctl):
    """819bc824: a Codex reviewer has no Claude Code harness to inject a
    `Co-Authored-By: Claude ...` trailer, but it inherits the same hardcoded
    `Comment by Claude (<agent>):` prompt text a gateway model does — so the
    override must fire for it too, naming the slug and routing via the Codex
    CLI rather than the gateway."""
    d = agentctl.attribution_directive("gpt-5.6-terra", "reviewer")
    assert d == (
        "\n\n## Attribution override (authoritative — supersedes the prompt above)\n\n"
        "You are running on the `gpt-5.6-terra` model, dispatched via the Codex CLI. "
        "Attribute your output to `gpt-5.6-terra`, never to Claude:\n"
        "- **PR comments / posted review findings:** prefix with "
        "`**Comment by gpt-5.6-terra (reviewer):**` — substitute `gpt-5.6-terra` wherever "
        'the prompt above tells you to write "Claude".\n'
        "- **Git commit trailers:** end commit messages with "
        "`Co-Authored-By: gpt-5.6-terra <noreply@convivy.com>`, replacing any "
        "`Co-Authored-By: Claude ...` line you would otherwise add.\n"
        "This keeps the git history and PR audit trail honest about which model "
        "actually produced the work."
    )


def test_trial_attribution_directive_names_no_model(agentctl):
    """The blind directive `--trial` substitutes for `attribution_directive`
    must not itself contain the model's name, its provider, or the gateway's
    name — the one thing it is forbidden from doing is the thing
    `attribution_directive` exists to do. Takes no `model` argument at all, so
    there is nothing for a caller to pass through by accident."""
    d = agentctl.trial_attribution_directive()
    for name in ("Claude", "Anthropic", "deepseek", "DeepSeek", "kimi", "Kimi",
                "Moonshot", "glm", "GLM", "zai", "Zai", "sonnet", "opus"):
        assert name not in d, f"{name!r} must not appear in the blind directive"
    assert "Co-Authored-By" in d
    assert d.startswith("\n\n")


def test_spawn_trial_arg_accepts_the_documented_shape(agentctl):
    """`^[a-z0-9][a-z0-9-]{0,39}$` — lowercase/digits/hyphens, starting with a
    letter or digit, 40 characters max."""
    assert agentctl._spawn_trial_arg("glm-arm-1") == "glm-arm-1"
    assert agentctl._spawn_trial_arg("a" * 40) == "a" * 40


@pytest.mark.parametrize("value", [
    "Trial-A",       # uppercase
    "-leading-hyphen",
    "has a space",
    "under_score",
    "a" * 41,        # over the 40-char cap
    "",              # empty
])
def test_spawn_trial_arg_refuses_outside_the_pattern(agentctl, value):
    with pytest.raises(argparse.ArgumentTypeError):
        agentctl._spawn_trial_arg(value)


def test_fallback_model_for(agentctl):
    """ARCH-131: Anthropic-direct models fail over to deepseek. ARCH-186: deepseek
    fails over to SONNET (subscription-billed harness respawn — kimi is cut, and
    the gateway can't reach Anthropic). Other gateway models keep no harness hop."""
    assert agentctl.fallback_model_for("claude-opus-4-7") == "deepseek/deepseek-flash"
    assert agentctl.fallback_model_for("claude-sonnet-4-6") == "deepseek/deepseek-flash"
    assert agentctl.fallback_model_for("claude-haiku-4-5") == "deepseek/deepseek-flash"
    # fable is Anthropic-direct like opus/sonnet/haiku, so an operator-invoked
    # fable run that dies abnormally hops to deepseek the same as any other
    # Anthropic-direct model — the targets are hardcoded, so fable is never
    # itself a hop TARGET (ARCH-134 concerns the roster/default path, not this).
    assert agentctl.fallback_model_for("claude-fable-5") == "deepseek/deepseek-flash"
    assert agentctl.fallback_model_for("deepseek/deepseek-flash") == "claude-sonnet-5"
    assert agentctl.fallback_model_for("moonshot/kimi-k2.6") is None
    assert agentctl.fallback_model_for("moonshot/kimi-k2.7-code") is None
    assert agentctl.fallback_model_for("openai/gpt-5") is None
    # ARCH-201 trial models: no harness hop, so a failure surfaces in the scorecard
    # instead of respawning on deepseek and contaminating the trial's attribution.
    assert agentctl.fallback_model_for("openai/mimo-v2.5-pro") is None
    assert agentctl.fallback_model_for("zai/glm-5.2") is None


def test_run_session_wires_arch131_fallback(agentctl):
    """The run loop must consult fallback_model_for and honor the no-fallback
    marker (written by `kill --final`); kill must expose --final. Source-level
    guard in the style of the billing_source check below."""
    import inspect
    src = inspect.getsource(agentctl._run_session)
    assert "fallback_model_for(model)" in src
    assert '"no-fallback"' in src
    assert "interrupted" in src  # Ctrl-C must not trigger the fail-over
    # The no-fallback marker write lives in _terminate_run (the per-run kill
    # extracted from cmd_kill so `kill --tree` can reap descendants too); cmd_kill
    # must still expose --final and route through it.
    kill_src = inspect.getsource(agentctl._terminate_run)
    assert "no-fallback" in kill_src
    assert "final" in kill_src
    cmd_src = inspect.getsource(agentctl.cmd_kill)
    assert "_terminate_run" in cmd_src
    assert "final" in cmd_src


def _run_fallback_session(agentctl, tmp_path, monkeypatch, *, marker: bool,
                          origin: str = "scheduled", floor: str | None = "deepseek",
                          argv_log: Path | None = None, agent_name: str = "bug-investigator",
                          pr: int | None = None):
    """Drive _run_session with a stub claude: the Anthropic attempt exits 1
    (rate-limit death); only `--model deepseek` succeeds. Heavy collaborators
    (finalize, Slack notice, registry, gateway key lookup) are stubbed. With `argv_log`,
    the stub appends each spawn's argv to that file, separated by `---` lines."""
    import json as _json
    import types

    run_dir = tmp_path / "run-fbtest"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    stub = tmp_path / "claude-stub"
    log_line = (f"{{ echo ---; printf '%s\\n' \"$@\"; }} >> '{argv_log}'\n"
                if argv_log is not None else "")
    stub.write_text(
        "#!/bin/sh\n"
        + log_line +
        'model=""; prev=""\n'
        'for a in "$@"; do if [ "$prev" = "--model" ]; then model="$a"; fi; prev="$a"; done\n'
        'if [ "$model" = "deepseek" ]; then\n'
        "  printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"deepseek\"}'\n"
        "  exit 0\n"
        "fi\n"
        "exit 1\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    # `_respawn_in_place`'s own `R.add_run` call was the one registry write this
    # helper left live (CQ·523): with every OTHER registry call stubbed to a
    # no-op, a real `add_run` wrote a literal "run-fbtest" entry into the
    # session-wide registry every caller of this helper shares (none passes
    # `runs_root`), and a dead-child-but-corroborated-dispatcher entry one test
    # leaves behind now survives `_reap_in_place` for the rest of the session —
    # the next caller's `add_run` for the same literal run_id then raises
    # "run_id already registered" instead of exercising the fail-over this
    # helper exists to drive.
    monkeypatch.setattr(agentctl.R, "add_run", lambda entry: None)
    if marker:
        (run_dir / "no-fallback").touch()
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: origin)
    args = types.SimpleNamespace(agent=agent_name, task="t",
                                 parent=None, dry_run=False, label=None)
    agent_def = {"body": "sys", "model_alias": "opus",
                 "frontmatter": {"model": "opus"}}
    if floor is not None:
        agent_def["frontmatter"]["model_floor"] = floor
    rc = agentctl._run_session(
        args=args, agent=agent_def,
        run_id="run-fbtest", run_dir=run_dir, worktree=worktree,
        profile="p", repo="agent-platform", pr=pr,
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    meta = _json.loads((run_dir / "meta.json").read_text())
    return rc, meta, run_dir


def test_run_session_holds_for_usage_then_dispatches_end_to_end(agentctl, tmp_path, monkeypatch):
    """Drives the REAL `_run_session`, end to end, through a usage hold: a
    seeded run's transcript reports five-hour overage, so the run must wait
    (fake clock, no real sleeping) before ever reaching the stub `claude`, and
    meta.json must carry the hold once it does. Verified against the unfixed
    code: before this change, `_run_session` had no usage-hold call at all, so
    `meta["held_until"]` was always absent and this assertion failed."""
    import json as _json
    import types
    import telemetry as T

    runs_root = tmp_path / "agent-runs"
