def test_run_session_below_threshold_never_holds(agentctl, tmp_path, monkeypatch):
    import json as _json
    import types
    import telemetry as T

    runs_root = tmp_path / "agent-runs"
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)
    monkeypatch.setattr(T, "RUNS_ROOT", runs_root)

    run_dir = tmp_path / "run-nohold-e2e"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    stub = tmp_path / "claude-stub"
    stub.write_text(
        "#!/bin/sh\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"opus\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")

    _seed_five_hour_reading(T, "run-seed", utilization=0.5, resets_at=1_000_000.0)
    slept = []
    # `_hold_sleep`, not `time.sleep`: this test drives the REAL spawn path,
    # which calls `_pid_start_time` (its `ps -p <pid>` probe passes
    # `timeout=5` to `subprocess.run`) even though `R.attach_pid` is a mocked
    # no-op above — the mock doesn't stop Python from evaluating its
    # arguments. On a loaded CI runner, `ps` being slow to reap trips
    # CPython's own `Popen.wait(timeout=...)` busy-poll loop, which sleeps
    # through the very `time.sleep` a global patch would be watching — that
    # was CI's "must never have slept" failure on PR #716's head, unrelated
    # to any hold ever firing. Watching `_hold_sleep` isolates this
    # assertion to the hold alone.
    monkeypatch.setattr(agentctl, "_hold_sleep", lambda s: slept.append(s))

    args = types.SimpleNamespace(agent="coder", task="t", parent=None,
                                 dry_run=False, label=None)
    agent_def = {"body": "sys", "model_alias": "opus", "frontmatter": {"model": "opus"}}
    rc = agentctl._run_session(
        args=args, agent=agent_def, run_id="run-nohold-e2e", run_dir=run_dir,
        worktree=worktree, profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    meta = _json.loads((run_dir / "meta.json").read_text())
    assert rc == 0
    assert meta["held_until"] is None and meta["hold_reason"] is None
    assert slept == [], "must never have slept"


