def test_run_session_dry_run_reports_the_hold_and_does_not_wait(agentctl, runs_root, tmp_path, monkeypatch):
    """`--dry-run` reports what it would do and does not wait, per its contract."""
    import json as _json
    import types
    import telemetry as T

    # Dry-run registers its run with `R.add_run`, which writes the registry at
    # `R.ACTIVE_PATH`. The `runs_root` fixture points that at this test's tmp dir;
    # without it the entry lands in the session's registry and counts against
    # every later test that reads the same file.
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)
    monkeypatch.setattr(T, "RUNS_ROOT", runs_root)
    # `R.add_run` reads the concurrency limits through `R.limits()`, which runs
    # `git show-ref` with a `timeout=`. CPython's `Popen.wait(timeout=)` polls with
    # `time.sleep` whenever git has closed its pipes but not yet exited, and the
    # spy below records every one of those sleeps. Pinning the limits to the
    # fallback keeps git out of this test, so the outcome no longer depends on how
    # quickly git exits on the host.
    monkeypatch.setattr(agentctl.R, "_LIMITS", AP.Fallback("pinned by this test"))

    run_dir = tmp_path / "run-dryhold"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    # A real near-future instant, not a fake clock: dry-run makes one
    # synchronous decision off the real wall clock and never sleeps, so there
    # is no clock to fake here — unlike the waiting paths above. Within
    # read_five_hour_window's own future bound (round 2, PR #716): a resets_at
    # a five-hour window's own mechanics could never produce is no longer
    # usable at all, however far in the future it is, but 3600s is well
    # inside it.
    from datetime import datetime as _datetime, timezone as _timezone
    resets_at = _datetime.now(_timezone.utc).timestamp() + 3600
    held_until = _datetime.fromtimestamp(resets_at, tz=_timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    _seed_five_hour_reading(T, "run-seed", utilization=0.1, resets_at=resets_at,
                            is_using_overage=True)
    slept = []
    monkeypatch.setattr(agentctl.time, "sleep", lambda s: slept.append(s))

    args = types.SimpleNamespace(agent="coder", task="t", parent=None,
                                 dry_run=True, label=None)
    agent_def = {"body": "sys", "model_alias": "opus", "frontmatter": {"model": "opus"}}
    rc = agentctl._run_session(
        args=args, agent=agent_def, run_id="run-dryhold", run_dir=run_dir,
        worktree=worktree, profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    meta = _json.loads((run_dir / "meta.json").read_text())
    assert rc == 0
    assert meta["held_until"] == held_until
    assert "overage" in meta["hold_reason"]
    assert slept == [], "dry-run must not wait"


def _run_api_death_session(agentctl, tmp_path, monkeypatch, *, result_event):
    """Drive the REAL _run_session against a stub that dies with `result_event`.

    The point is the wiring, not the rule. The classifier is covered by its own
    parametrized table; what nothing covered was the extraction between the two —
    the dict key, the parse, and the branch that consumes them. A wrong key or an
    exception type the parse does not catch would sail through every test above.

    Counts attempts in a file so a retry is observed rather than inferred.
    """
    import json as _json
    import types

    run_dir = tmp_path / "run-apideath"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    counter = tmp_path / "attempts"
    stub = tmp_path / "claude-stub"
    stub.write_text(
        "#!/bin/sh\n"
        f"printf 'x' >> {counter}\n"
        f"printf '%s\\n' '{_json.dumps(result_event)}'\n"
        "exit 1\n"
    )
    stub.chmod(0o755)
    # A single quote in the payload breaks the /bin/sh quoting and emits
    # something that is not JSON: the event never parses, the api_error branch
    # never runs, and the test passes for the wrong reason. Caught the hard way.
    assert "'" not in _json.dumps(result_event), (
        "keep the fixture quote-free — the stub emits it through printf in sh")
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    # The side-effect gate would otherwise refuse for its own reasons and mask
    # whether the STATUS gate fired. Neutralised so this test measures one thing.
    monkeypatch.setattr(agentctl, "_api_retry_refusal", lambda **kw: None)
    # And the ARCH-131 fail-over respawns too, which would be counted alongside
    # the retry and make the number mean two things. Disabled so the count
    # measures exactly one: did the SAME-MODEL retry run.
    monkeypatch.setattr(agentctl, "fallback_model_for", lambda m: None)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")
    args = types.SimpleNamespace(agent="bug-investigator", task="t",
                                 parent=None, dry_run=False, label=None)
    agent_def = {"body": "sys", "model_alias": "opus",
                 "frontmatter": {"model": "opus", "model_floor": "deepseek"}}
    agentctl._run_session(
        args=args, agent=agent_def, run_id="run-apideath", run_dir=run_dir,
        worktree=worktree, profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    meta = _json.loads((run_dir / "meta.json").read_text())
    attempts = len(counter.read_text()) if counter.exists() else 0
    return meta, attempts


def test_an_invalid_model_death_does_not_spend_the_retry_end_to_end(
        agentctl, tmp_path, monkeypatch):
    """The whole point of step 2, driven through the real code path.

    Built from `run-faef2e84` / `run-12898f6b`: both spent the retry on a model
    that could never run. The side-effect gate is stubbed to PERMIT, so if the
    status gate did not fire this would attempt twice — which is exactly what
    those two runs did.
    """
    meta, attempts = _run_api_death_session(agentctl, tmp_path, monkeypatch, result_event={
        "type": "result", "subtype": "success", "is_error": True,
        "terminal_reason": "api_error", "api_error_status": 400,
        # Quote-free on purpose: the stub emits this through `printf` in /bin/sh,
        # and an apostrophe breaks the shell quoting so the line never parses as
        # JSON — which silently skips the whole api_error branch and makes the
        # test pass for the wrong reason. The STATUS is what is under test.
        "result": "API Error: 400 400: anthropic_messages: Invalid model name "
                  "passed in model=claude-sonnet-4-6.",
    })
    assert "api_retry_of" not in meta, "the retry ran against an unusable model"
    assert "400" in (meta.get("api_retry_declined_reason") or "")
    assert attempts == 1, f"expected one attempt, the stub was run {attempts} times"


def test_the_refusal_reason_scrubs_credentials_before_it_reaches_meta(
        agentctl, tmp_path, monkeypatch):
    """The refusal names the provider's error text, and that text lands in meta.json.

    `meta.json` is a structured record with downstream readers, not a private
    scratch file. `_scrub_api_error_message` is already applied to this same value
    before it reaches `outcome.json`; this path is the first to put raw upstream
    text into `api_retry_declined_reason`, and the sibling `_api_retry_refusal`
    never needed scrubbing because everything it returns is synthesized locally.

    The payload is the shape `_CRED_RE` was built against — a gateway echoing a
    request header back on a malformed-auth diagnostic.
    """
    meta, _ = _run_api_death_session(agentctl, tmp_path, monkeypatch, result_event={
        "type": "result", "subtype": "success", "is_error": True,
        "terminal_reason": "api_error", "api_error_status": 401,
        "result": "API Error: 401 unauthorized; sent Authorization: Bearer "
                  "sk-ant-api03-REDACTMEplsAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    })
    reason = meta.get("api_retry_declined_reason") or ""
    assert reason, "the refusal must still be recorded"
    assert "sk-ant-api03-REDACTMEplsAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" not in reason
    assert "[redacted]" in reason
    assert "401" in reason, "the status must survive — it is why the retry was refused"


def test_an_unreadable_status_is_also_scrubbed_before_it_reaches_meta(
        agentctl, tmp_path, monkeypatch):
    """The SECOND provider-supplied value on the same path, which the first fix missed.

    `api_error_status` is the same untyped JSON field as `result`, read off the same
    event stream — which is why it is int()-guarded rather than trusted. Anything
    non-numeric there is guaranteed to route through the unparseable branch, so a
    gateway stuffing a header into that field lands in `meta.json` verbatim unless
    it is scrubbed too.

    The companion test above only drives a PARSEABLE status, so it never reaches
    this branch. That is precisely how the gap survived the first fix.
    """
    meta, _ = _run_api_death_session(agentctl, tmp_path, monkeypatch, result_event={
        "type": "result", "subtype": "success", "is_error": True,
        "terminal_reason": "api_error",
        "api_error_status": "Authorization: Bearer "
                            "sk-ant-api03-LEAKMEplsAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
        "result": "API Error: malformed auth",
    })
    reason = meta.get("api_retry_declined_reason") or ""
    assert reason, "the refusal must still be recorded"
    assert "sk-ant-api03-LEAKMEplsAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" not in reason
    assert "[redacted]" in reason
    assert "unreadable status" in reason, "the reason must still say what happened"


def test_a_wire_death_still_spends_the_retry_end_to_end(
        agentctl, tmp_path, monkeypatch):
    """The case the retry was built for must still work, through the same wiring.

    No `api_error_status` at all — the n=10 shape from 2026-08-02. If the
    extraction mis-read an absent field as unparseable, this would silently stop
    retrying and nothing else in the suite would notice.
    """
    meta, attempts = _run_api_death_session(agentctl, tmp_path, monkeypatch, result_event={
        "type": "result", "subtype": "error", "is_error": True,
        "terminal_reason": "api_error",
        "result": "API Error: Connection closed mid-response.",
    })
    assert meta.get("api_retry_of") == "api_error"
    assert attempts == 2, f"expected one retry (2 attempts), got {attempts}"


