def test_activate_profile_dry_run_never_passes_force(agentctl, tmp_path, monkeypatch):
    """`cmd_spawn` calls `activate_profile` unconditionally, before
    `_run_session` ever inspects `args.dry_run` (that check only decides whether
    to launch the claude subprocess) — so `activate_profile` has to make its own
    dry-run decision or a `spawn --dry-run` force-individuates for real.

    That is exactly what happened dispatching a writer agent against a
    workspace (the Library's issue_01M1RYSP06C98MN55ZAC47NVNA evidence): the
    dry run ran a real `knowledge-ctx use daytime --force` inside the live
    workspace, saved only by the profile failing to resolve first. Pinned by
    inspecting the actual subprocess command built, not just the exit code.
    """
    seen = {}

    def fake_run(cmd, **kwargs):
        seen["cmd"] = cmd
        class _R:
            returncode = 0
            stdout = ""
            stderr = ""
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [111])

    agentctl.activate_profile(tmp_path, "company/commercial", dry_run=True)
    assert "--dry-run" in seen["cmd"]
    assert "--force" not in seen["cmd"]

    agentctl.activate_profile(tmp_path, "company/commercial", dry_run=False)
    assert "--force" in seen["cmd"]
    assert "--dry-run" not in seen["cmd"]


def test_activate_profile_passes_the_agent_through_to_knowledge_ctx(
        agentctl, tmp_path, monkeypatch):
    """A dispatched render must name its agent, because knowledge-ctx reads the
    flag's presence as `binds_sessions: dispatched` and its value as the
    `binds_agents` subject (issue_01M2PXHKZ3SE1AQPS8MWWT691X).

    Dropping it inverts the delivery rather than merely narrowing it: against
    the seven blocks serving today, an unflagged spawn resolves as `interactive`
    and hands a dispatched worker `open-a-pull-request` and
    `working-with-the-operator` while withholding `review-a-pull-request` from
    every reviewer. Pinned on the subprocess command built, since the exit code
    is identical either way."""
    seen = {}

    def fake_run(cmd, **kwargs):
        seen["cmd"] = cmd
        class _R:
            returncode = 0
            stdout = ""
            stderr = ""
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [111])

    agentctl.activate_profile(tmp_path, "company/commercial", agent="reviewer")
    assert "--agent" in seen["cmd"]
    assert seen["cmd"][seen["cmd"].index("--agent") + 1] == "reviewer"

    # A crew session names no agent, and must stay an `interactive` render.
    agentctl.activate_profile(tmp_path, "company/commercial")
    assert "--agent" not in seen["cmd"]


def test_activate_profile_forwards_the_issue_only_with_an_agent(
        agentctl, tmp_path, monkeypatch):
    """`--issue` scopes the agent's Library bundle to agent+item
    (issue_01M2MAP3X0Q1BQW06AV8204CFW). knowledge-ctx refuses `--issue` without
    `--agent`, so forwarding it alone would fail a crew-session render."""
    seen = {}

    def fake_run(cmd, **kwargs):
        seen["cmd"] = cmd
        class _R:
            returncode = 0
            stdout = ""
            stderr = ""
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [])

    agentctl.activate_profile(tmp_path, "company/commercial", agent="reviewer",
                              issue="issue_X")
    assert seen["cmd"][seen["cmd"].index("--issue") + 1] == "issue_X"

    agentctl.activate_profile(tmp_path, "company/commercial", agent="reviewer")
    assert "--issue" not in seen["cmd"]

    agentctl.activate_profile(tmp_path, "company/commercial", issue="issue_X")
    assert "--issue" not in seen["cmd"]


def test_activate_profile_surfaces_a_blocked_claude_md_write(
        agentctl, tmp_path, monkeypatch, capsys):
    """knowledge-ctx can exit 0 while reporting, on the marker line it emits
    for exactly this, that a `.claude/CLAUDE.md` it did not write blocked
    delivery of the composed session instructions. Before this fix,
    `activate_profile` only ever inspected captured output on a non-zero
    exit, so this outcome reached nobody on a dispatch (security-reviewer,
    PR #635 round 3). Stubs knowledge-ctx directly, rather than running the
    real binary, to pin `activate_profile`'s own detection independent of
    knowledge-ctx's wording.
    """
    blocked_path = str(tmp_path / ".claude" / "CLAUDE.md")

    def fake_run(cmd, **kwargs):
        class _R:
            returncode = 0
            stdout = (
                "profile: company/commercial\n"
                "  ! composed session instructions were NOT delivered — "
                f"{blocked_path} left in place (not listed in the previous "
                "individuation manifest).\n"
                "wrote 3 files.\n"
            )
            stderr = (
                "  ! composed session instructions were NOT delivered — "
                f"{blocked_path} left in place (not listed in the previous "
                "individuation manifest).\n"
                f"KNOWLEDGE_CTX_CLAUDE_MD_NOT_DELIVERED path={blocked_path} "
                "reason=not listed in the previous individuation manifest\n"
            )
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [])

    result = agentctl.activate_profile(tmp_path, "company/commercial")

    assert result == (blocked_path, "not listed in the previous individuation manifest")
    err = capsys.readouterr().err
    assert "NOT delivered" in err
    assert blocked_path in err


def test_activate_profile_surfaces_an_unreadable_topics_lookup(
        agentctl, tmp_path, monkeypatch, capsys):
    """Reviewer, run-a0b4152c: knowledge-ctx writes its "could not read
    <issue>'s topics" warning to stderr, but `activate_profile` only
    re-emitted the three markers it already knew about — a real
    `agentctl spawn --issue` swallowed this one along with `cp.stderr` once
    the subprocess finished, so a failed topics lookup reached nobody on a
    dispatch. Stubs knowledge-ctx directly, matching
    `test_activate_profile_surfaces_a_blocked_claude_md_write`'s pattern, to
    pin `activate_profile`'s own detection independent of knowledge-ctx's
    wording."""
    def fake_run(cmd, **kwargs):
        class _R:
            returncode = 0
            stdout = "profile: company/commercial\nwrote 3 files.\n"
            stderr = (
                "KNOWLEDGE_CTX_TOPICS_UNREADABLE issue=issue_X reason=error:404\n"
                "knowledge-ctx: could not read issue_X's topics (error:404); "
                "this session's binds_topics selectors will not match anything\n"
            )
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [])

    result = agentctl.activate_profile(tmp_path, "company/commercial",
                                       agent="reviewer", issue="issue_X")

    assert result is None
    err = capsys.readouterr().err
    assert "issue_X" in err and "error:404" in err


