def test_origin_is_known_non_github_false_for_a_github_origin(agentctl, tmp_path):
    repo = tmp_path / "r"
    repo.mkdir()
    _git_ok(repo, "init", "-q")
    _git_ok(repo, "remote", "add", "origin", "git@github.com:convivy/agent-platform.git")
