def test_refuse_open_pr_reuse_failed_mint_fails_closed(agentctl, monkeypatch, tmp_path):
    """platform/decisions/0051: the open-PR collision lookup mints its own
    `read` token through `_gh_run_env` rather than running `gh` under the
    operator's ambient login. A failed mint refuses the same way a failed
    gh lookup already does, naming the reason, and `_gh_open_pr_for_branch`
    is never reached."""
    _stub_branch_reachable_on_github(agentctl, monkeypatch)
    _s3_stub_gh_app_mint(monkeypatch, agentctl, tmp_path)

    def _boom(jwt, owner, *, label=None, opener=None):
        raise agentctl.GA.Unreadable("the installation could not be read (503)")
    monkeypatch.setattr(agentctl.GA, "installation_for_owner", _boom)

    def _refuse(*a, **kw):
        raise AssertionError("a failed mint must never reach _gh_open_pr_for_branch")
    monkeypatch.setattr(agentctl, "_gh_open_pr_for_branch", _refuse)

    msg = agentctl._refuse_open_pr_reuse("coder", "demo", "coder-fix-x-abcd1234")
    assert msg is not None and "cannot verify" in msg
    assert _s3_mint_log_entries(tmp_path) == [], "a failed mint logs nothing to grant"


# --- the review worktree must be scoped to its PR ---------------------------
#
# THE COLLISION THIS CLOSES. `purpose` is slugged from the TASK TEXT, truncated to
# 32 chars. Two reviews of DIFFERENT PRs whose task strings share a lead —
# "Review the changes on this PR for correctness…" is the obvious one — slug to the
# same purpose, so both resolve to one worktree. Concurrently that is a WorktreeBusy
# refusal of the second dispatch; serially it is one tree force-reset between two
# unrelated reviews. Demonstrated against the live function before the fix: both
# tasks below produced `reviewer-review-the-changes-on-this-pr-fo`.
#
# Scoped to REVIEW agents on purpose. Their trees are detached, commit-pinned
# (ARCH-184) and reaped (ARCH-344), so the branch name derived from the purpose is
# irrelevant to them. A coder's is not: its branch IS the purpose, and ARCH-347's
# round-fix reuse resolves a tree by that branch.

def test_two_prs_with_the_same_task_lead_get_different_review_worktrees(agentctl):
    generic = "Review the changes on this PR for correctness, tests, and style."
    a = agentctl.derive_purpose("reviewer", generic, pr="209")
    b = agentctl.derive_purpose("reviewer", generic, pr="210")
    assert a != b, f"distinct PRs must not share a review worktree (both got {a})"
    assert "209" in a and "210" in b


@pytest.mark.rich_registry
def test_the_pr_scope_applies_to_every_review_agent(agentctl):
    for agent in ("reviewer", "security-reviewer"):
        p = agentctl.derive_purpose(agent, "Review it", pr="7")
        assert "pr7" in p, (agent, p)
    # An app-prefixed review agent resolves through _strip_app_prefix too.
    assert "pr7" in agentctl.derive_purpose("atlas-reviewer", "Review it", pr="7")


def test_a_coders_purpose_is_unchanged_by_a_pr_number(agentctl):
    """Deliberately NOT scoped: a coder's branch is derived from its purpose, and
    ARCH-347 resolves a round-fix's tree by that branch. Changing it would fork a
    round-fix away from the branch the PR points at — the cartographer #923 footgun."""
    assert agentctl.derive_purpose("coder", "Add pagination", pr="42") == \
        agentctl.derive_purpose("coder", "Add pagination")
    # bug-fixer is NOT a review agent, so its purpose is unchanged by pr= — but
    # it still gets the task-hash discriminator (issue 01KYRC81H…).
    assert agentctl.derive_purpose("bug-fixer", "Fix login", pr="42") == \
        "bug-fix-login-8f53ef2b"


def test_the_pr_scope_survives_a_long_task_that_would_truncate_it(agentctl):
    """The whole bug is truncation, so the PR marker must not itself be truncated
    away. Two long, identical-prefix tasks must still separate."""
    long_task = "Review the changes on this pull request for correctness, " * 3
    a = agentctl.derive_purpose("reviewer", long_task, pr="1001")
    b = agentctl.derive_purpose("reviewer", long_task, pr="1002")
    assert a != b, f"truncation must not eat the PR scope (both got {a})"
    assert "1001" in a and "1002" in b


def test_a_malformed_pr_value_cannot_escape_the_worktree_directory(agentctl):
    """`purpose` is interpolated into a filesystem path (`desired_path` builds
    `<extras>/<repo>.<purpose>`) and into a branch name, and `_slug` sanitizes only
    the TASK — the prefix is concatenated raw. So the PR value has to be sanitized
    here or it is a path-traversal primitive. Verified before the fix:
    pr='../../../../tmp/evil' produced 'reviewer-pr../../../../tmp/evil-review-it'."""
    for bad in ["../../../../tmp/evil", "a/b", "9 9", "#209", "2;rm -rf /", ""]:
        p = agentctl.derive_purpose("reviewer", "Review it", pr=bad)
        assert "/" not in p, (bad, p)
        assert ".." not in p, (bad, p)
        assert " " not in p, (bad, p)
        assert ";" not in p, (bad, p)
    # A digits-bearing value still scopes, using just its digits.
    assert "pr209" in agentctl.derive_purpose("reviewer", "Review it", pr="#209")
    # A value with no digits at all cannot scope, so it falls back to the plain
    # purpose rather than inventing one.
    assert agentctl.derive_purpose("reviewer", "Review it", pr="abc") == \
        agentctl.derive_purpose("reviewer", "Review it")


# --- the bug worktree must be scoped to its task ----------------------------
#
# THE COLLISION THIS CLOSES (issue 01KYRC81H34WCC6FVV9JZAWQGW). Every in-box
# drain dispatch opens as "Fix mode for in-box issue issue_<id>" — the task
# slug alone truncates the issue-id tail to the same 32-char prefix, so every
# drain on a product resolves to the same purpose. The task-hash discriminator
# keeps the purpose stable per task (same text → same hash) while ensuring
# different tasks never collide.

def test_two_different_bug_tasks_get_different_purposes(agentctl):
    """Two in-box issues with the standard task prefix must not collide."""
    a = "Fix mode for in-box issue issue_01KYRAX03PDR437J2TP4XZCBFP"
    b = "Fix mode for in-box issue issue_01KYRC81H34WCC6FVV9JZAWQGW"
    pa = agentctl.derive_purpose("bug-fixer", a)
    pb = agentctl.derive_purpose("bug-fixer", b)
    assert pa != pb, f"distinct issues must not share a purpose (both got {pa})"
    assert pa.startswith("bug-fix-mode-for-in-box-issue-issue")
    assert pb.startswith("bug-fix-mode-for-in-box-issue-issue")
    assert pa.endswith("8e21f52e")
    assert pb.endswith("c2ffce94")


def test_only_ascii_digits_count_as_a_pr_number(agentctl):
    """Python's `\\d` is Unicode-aware by default, so Arabic-Indic (٩١٢) and
    fullwidth (１２３) digits survive the strip and would land in a path and a git
    ref. A GitHub PR number is always an ASCII integer, so anything else must not
    scope (security review, #213)."""
    for exotic in ["٩١٢", "１２３", "٩1٢"]:
        p = agentctl.derive_purpose("reviewer", "Review it", pr=exotic)
        assert p.isascii(), (exotic, p)
    # Wholly non-ASCII digits leave nothing to scope with → plain purpose.
    assert agentctl.derive_purpose("reviewer", "Review it", pr="٩١٢") == \
        agentctl.derive_purpose("reviewer", "Review it")
    # A mixed value keeps only its ASCII digits rather than the exotic ones.
    assert "pr1" in agentctl.derive_purpose("reviewer", "Review it", pr="٩1٢")


def test_an_absurdly_long_pr_number_cannot_blow_the_path_limit(agentctl):
    """`purpose` becomes `<extras>/<repo>.<purpose>`, and NAME_MAX is 255 on every
    common filesystem, so an unbounded digit run turns a spawn into ENAMETOOLONG.
    Real PR numbers are ≤5 digits (security review, #213)."""
    p = agentctl.derive_purpose("reviewer", "Review it", pr="9" * 10_000)
    assert len(p) < 255, len(p)
    # A realistic number is untouched by the bound.
    assert "pr20913" in agentctl.derive_purpose("reviewer", "Review it", pr="20913")


def test_no_pr_number_keeps_the_old_purpose(agentctl):
    """Not every review dispatch carries --pr (it is optional on spawn). Those must
    behave exactly as before rather than acquire a placeholder."""
    assert agentctl.derive_purpose("reviewer", "PR 42") == "reviewer-pr-42"
    assert agentctl.derive_purpose("reviewer", "PR 42", pr=None) == "reviewer-pr-42"
    # internal-app (synthpa-) agents get their role's worktree treatment (ARCH-177):
    # synthcrew-coder writes → dedicated worktree; synthpa-planner needs none.
    # synthcrew-coder is write-class (not review), so it carries the task-hash
    # discriminator too.
    assert agentctl.derive_purpose("synthcrew-coder", "Add reminders") == \
        "synthcrew-coder-add-reminders-0d3739c0"
    assert agentctl.derive_purpose("synthcrew-reviewer", "PR 12") == "synthcrew-reviewer-pr-12"
    assert agentctl.derive_purpose("synthpa-planner", "shape the slice") is None
    # `architect` became worktree-class on 2026-07-29
    # (issue_01KYQ9N00Q7HJYSETBV8TPY3D9), so the prefixed variant follows its role
    # the same way synthcrew-coder does — which is the ARCH-177 property this test pins.
    assert agentctl.derive_purpose("synthpa-architect", "design events") == \
        "synthpa-architect-design-events-fd4a6224"


def test_log_model_override_appends_record(agentctl, monkeypatch, tmp_path):
    # ARCH-188: each --model override is logged for the abuse monitor. The
    # model-lane epic (issue_01KZH2GYGTVHFXZ055GEZVH2ZJ) adds run_id + reason so
    # the row is accountable, not just counted.
    import json
    log = tmp_path / "model-overrides.jsonl"
    monkeypatch.setattr(agentctl, "MODEL_OVERRIDES_LOG", log)
    agentctl._log_model_override(agent="reviewer", repo="cartographer",
                                 model="claude-opus-4-7", origin="interactive",
                                 run_id="run-1", reason="testing the alert path")
    agentctl._log_model_override(agent="coder", repo="outfitter",
                                 model="claude-sonnet-4-6", origin="interactive",
                                 run_id="run-2", reason="deepseek was flaky")
    rows = [json.loads(line) for line in log.read_text().splitlines()]
    assert len(rows) == 2
    assert rows[0]["agent"] == "reviewer" and rows[0]["model"] == "claude-opus-4-7"
    assert rows[0]["origin"] == "interactive" and "ts" in rows[0]
    assert rows[0]["run_id"] == "run-1" and rows[0]["reason"] == "testing the alert path"


def test_log_model_override_sanitises_reason(agentctl, monkeypatch, tmp_path):
    """`reason` is free text typed at the CLI, not platform-authored, and this
    row is later interpolated straight into a Slack-rendered alert
    (metric-alerts' model_override_alerts) — security review on this epic's
    first PR (#416) found it logged verbatim with no pass through
    signal_client's shared `sanitise`, so a --reason that happened to contain
    a credential-shaped string would be logged in cleartext and re-quoted in
    the alert. Redaction now happens at the log-write site."""
    import json
    log = tmp_path / "model-overrides.jsonl"
    monkeypatch.setattr(agentctl, "MODEL_OVERRIDES_LOG", log)
    agentctl._log_model_override(
        agent="reviewer", repo="cartographer", model="claude-opus-4-7", origin="interactive",
        run_id="run-1", reason="needed it, Bearer sk-abcdefghijklmnop for the incident")
    row = json.loads(log.read_text().splitlines()[0])
    assert "sk-abcdefghijklmnop" not in row["reason"]
    assert "[redacted]" in row["reason"]


def _run_override_session(agentctl, tmp_path, monkeypatch, *, model_alias, override,
                          reason="testing", origin="interactive", extra_args=None,
                          rc_out=None):
    """Drive _run_session with a success stub and a `--model <override>` on an
    agent whose roster default is <model_alias>. Returns the override-log path so
    a test can assert whether the override was recorded (ARCH-188).

    `origin` stubs the stamped origin this spawn would resolve to (`_run_origin`)
    — default `interactive` so every pre-existing caller of this helper keeps
    testing the human-in-the-loop path unless it opts into a capped one."""
    import types

    run_dir = tmp_path / "run-ovtest"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    stub = tmp_path / "claude-stub"
    stub.write_text(
        "#!/bin/sh\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    log = tmp_path / "model-overrides.jsonl"
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "MODEL_OVERRIDES_LOG", log)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: origin)
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    args = types.SimpleNamespace(agent="reviewer", task="t", parent=None,
                                 dry_run=False, label=None, model=override,
                                 reason=reason, **(extra_args or {}))
    rc = agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": model_alias},
        run_id="run-ovtest", run_dir=run_dir, worktree=worktree,
        profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    if rc_out is not None:
        rc_out.append(rc)
    return log


def test_run_session_writes_the_passed_review_sha_not_args(agentctl, tmp_path, monkeypatch):
    """ARCH-347: for a `--pr N` reviewer, the pin is the SELF-RESOLVED live head, held in
    the `review_sha` parameter — `args.review_sha` is None on that path. A regression here
    (re-reading args.review_sha, as an earlier cut did) silently drops the head from
    meta.json, breaking the ARCH-193 authenticity bind. Assert the PARAM wins."""
    import json
    import types
    run_dir = tmp_path / "run-pin"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    stub = tmp_path / "claude-stub"
    stub.write_text("#!/bin/sh\nprintf '%s\\n' "
                    "'{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\nexit 0\n")
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    pinned = "a" * 40
    args = types.SimpleNamespace(agent="reviewer", task="t", parent=None,
                                 dry_run=False, label=None, model=None,
                                 review_sha=None)   # the --pr path: args carries no sha
    agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": "sonnet"},
        run_id="run-pin", run_dir=run_dir, worktree=worktree, profile="p",
        repo="agent-platform", started_at="2026-07-15T00:00:00Z", user_prompt="u",
        review_sha=pinned)
    meta = json.loads((run_dir / "meta.json").read_text())
    assert meta.get("review_sha") == pinned


