def _disallowed_in(spawn_argv: list[str]) -> list[str]:
    """The `--disallowedTools` values of one spawn: every token up to the next flag."""
    i = spawn_argv.index("--disallowedTools")
    out = []
    for tok in spawn_argv[i + 1:]:
        if tok.startswith("--"):
            break
        out.append(tok)
    return out


def _spawns_from_log(argv_log: Path) -> list[list[str]]:
    """Split the stub's argv log into one list of argv lines per spawn."""
    blocks = argv_log.read_text().split("---\n")
    return [block.splitlines() for block in blocks if block.strip()]


def test_a_fail_over_respawn_is_denied_the_model_it_runs_not_the_roster_model(
        agentctl, tmp_path, monkeypatch):
    """ARCH-131 fail-over. The roster model (`claude-opus-5-5`) holds an explicit WebFetch
    allow, and the fail-over model (deepseek) holds none. The respawn runs deepseek, so
    WebFetch must be denied on the second spawn and in its policy.json. Before the
    change, the respawn built its deny list from the roster model and kept WebFetch."""
    import json as _json
    import policy_client
    argv_log = tmp_path / "argv.log"

    def _resolve(agent, crew, model):
        grants = {"WebFetch": "allow"} if model == "claude-opus-5-5" else {}
        return dict(_PUBLIC_CREW_RECORD, explicit=grants)

    monkeypatch.setattr(policy_client, "resolve", _resolve)
    # The session-scoped module is not in sys.modules, so conftest's memo clear misses
    # it. An earlier test's offline answer would otherwise be served from the memo.
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    rc, meta, run_dir = _run_fallback_session(agentctl, tmp_path, monkeypatch, marker=False,
                                              argv_log=argv_log)
    assert rc == 0 and meta["fallback_from"] == "claude-opus-5-5"
    first, second = _spawns_from_log(argv_log)
    assert "WebFetch" not in _disallowed_in(first), (
        "the roster model's grant holds on its own spawn")
    assert "WebFetch" in _disallowed_in(second), "the fail-over model holds no grant"
    policy = _json.loads((run_dir / "policy.json").read_text())
    assert "WebFetch" in policy["denied"], "policy.json records the policy the run executed under"


def test_policy_json_says_when_this_path_applied_no_denials(agentctl, tmp_path):
    """A review-class run routed through review-launch gets no `--disallowedTools` from
    agentctl, so the denials it resolved must not read as applied. A direct run says so."""
    import json as _json
    import tool_policy as TP
    run_dir = tmp_path / "run-review-route"
    run_dir.mkdir()
    policy = TP.resolve("reviewer", TP.AUTONOMOUS, "agent-platform",
                        denied=["WebFetch"])
    agentctl._write_policy(run_dir, policy, agent_name="reviewer", denials_applied=False)
    rec = _json.loads((run_dir / "policy.json").read_text())
    assert rec["disallowed_tools_applied"] is False
    assert "not applied by agentctl" in rec["disallowed_tools_note"]
    assert rec["denied"] == ["WebFetch"], "the resolved denials are still recorded"
    # reviewer is a review-class agent, so enforcement_active is unconditional
    # (`_enforcement_active`) regardless of AGENTCTL_ENFORCE_TOOL_POLICY.
    assert rec["enforcement_active"] is True
    agentctl._write_policy(run_dir, policy, agent_name="reviewer")
    rec = _json.loads((run_dir / "policy.json").read_text())
    assert rec["disallowed_tools_applied"] is True
    assert "disallowed_tools_note" not in rec


def test_enforcement_active_holds_for_web_researcher_regardless_of_the_switch(
        agentctl, monkeypatch):
    """Sibling of the `reviewer` case above, for `_enforcement_active` itself rather
    than through `_write_policy`: `web-researcher`'s `ALWAYS_ENFORCED_AGENTS`
    membership, not `AGENTCTL_ENFORCE_TOOL_POLICY`, is what the field reports, both
    with the switch unset and with it explicitly off. `platform/decisions/
    0016-merged-but-not-in-force` names reporting a control inert while it is in
    force as misleading the operator the same way the reverse is; this is the field
    `policy.json` and `agentctl policy` both read."""
    import tool_policy as TP
    policy = TP.resolve("web-researcher", TP.AUTONOMOUS, "knowledge", denied=[])
    monkeypatch.delenv("AGENTCTL_ENFORCE_TOOL_POLICY", raising=False)
    assert agentctl._enforcement_active("web-researcher", policy) is True
    monkeypatch.setenv("AGENTCTL_ENFORCE_TOOL_POLICY", "0")
    assert agentctl._enforcement_active("web-researcher", policy) is True


def test_review_launcher_for_answers_the_route_question_for_spawn_and_record(
        agentctl, monkeypatch):
    """`_review_launcher_for` is the one question the spawn route and the policy record
    both ask. Only a review-class agent with a PR is routed, and only when the launcher
    is installed. That is the case in which the record says the denials were not
    applied here."""
    launcher = Path("/nonexistent/review-launch")
    monkeypatch.setattr(agentctl, "_review_launch_path", lambda: launcher)
    assert agentctl._review_launcher_for("reviewer", 784) == launcher
    assert agentctl._review_launcher_for("reviewer", None) is None
    assert agentctl._review_launcher_for("coder", 784) is None
    monkeypatch.setattr(agentctl, "_review_launch_path", lambda: None)
    assert agentctl._review_launcher_for("reviewer", 784) is None


