def test_cmd_spawn_model_override_to_priced_codex_slug_reaches_the_codex_gate(
        agentctl, monkeypatch):
    """--model gpt-5.6-terra on a reviewer whose roster default is a Claude
    model used to be refused twice before reaching this gate: by argparse's
    `choices` (the `main` test above), and, bypassing that, by `_model_known`
    inside `_spawn_override_preflight` (condition 1) — so the `is_codex_model`
    branch here, and the recorded probe pass `codex_dispatch_refusal` reads,
    could never be exercised from the CLI. Drives `cmd_spawn` directly, as
    production does, and stops right at that gate, cheaply, the same way the
    gateway-credential tests above do."""
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})
    reached = {}
    def _mark_gate_reached(model, home=None):
        reached["model"] = model
        return None  # the recorded probe passed
    monkeypatch.setattr(agentctl, "codex_dispatch_refusal", _mark_gate_reached)
    def _mark_can_spawn_reached(*a, **kw):
        reached["can_spawn"] = True
        return False, [], "stopped here on purpose"
    monkeypatch.setattr(agentctl.R, "can_spawn", _mark_can_spawn_reached)

    args = _cmd_spawn_args(model="gpt-5.6-terra", reason="trial on the Codex subscription")
    agentctl.cmd_spawn(args)
    assert reached.get("model") == "gpt-5.6-terra"
    assert reached.get("can_spawn"), "the review-agent check after the gate must also pass"


