def test_gateway_reachable_true_when_something_listens(agentctl, monkeypatch):
    import socket as _socket
    srv = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
    srv.bind(("127.0.0.1", 0))
    srv.listen(1)
    port = srv.getsockname()[1]
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: f"http://127.0.0.1:{port}")
    try:
        assert agentctl._gateway_reachable(timeout=1.0) is True
    finally:
        srv.close()


def test_gateway_reachable_false_when_nothing_listens(agentctl, monkeypatch):
    import socket as _socket
    # Bind an ephemeral port to learn a free one, then close it immediately —
    # nothing listens there afterward (connection refused), the common real
    # case of the LiteLLM gateway not running.
    probe = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
    probe.bind(("127.0.0.1", 0))
    port = probe.getsockname()[1]
    probe.close()
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: f"http://127.0.0.1:{port}")
    assert agentctl._gateway_reachable(timeout=1.0) is False


