    monkeypatch.setattr(agentctl, "_gateway_reachable", _unreached_reachable)
    def _unreached_origin(parent):
        raise AssertionError("condition 4 must not run once condition 2 refused")
    monkeypatch.setattr(agentctl, "_model_override_refusal", _unreached_origin)

    refusal = agentctl._spawn_override_preflight(model="openai/gpt-5", parent=None)
    assert refusal == "no credential covers it"


