def test_spawn_override_preflight_credential_refusal_leaks_nothing(agentctl, monkeypatch, tmp_path):
    """`_gateway_virtual_key`'s own exceptions carry GATEWAY_KEYS_FILE's path
    and raw keychain error text (the 2026-09-03 incident this file's
    docstring records) — the preflight must catch and discard that detail,
    never echo it into a refusal a caller might log or relay."""
    keys_file = tmp_path / "litellm-keys.json"
    def _raise():
        raise agentctl.SpawnPreflightError(
            f"{keys_file} is readable beyond its owner (mode 644); "
            f"security find-generic-password exited 36 — errSecInteractionNotAllowed"
        )
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", _raise)

    refusal = agentctl._spawn_override_preflight(model="openai/gpt-5", parent=None)
    assert refusal == "no credential covers it"
    assert str(keys_file) not in refusal
    assert "errSec" not in refusal
    assert "36" not in refusal


