def test_override_refusal_origin_catches_env_cleared_via_own_registered_worktree(agentctl, tmp_path, monkeypatch):
    """security-reviewer's blocking finding on PR #476, the exact bypass command:
    `env -u AGENTCTL_RUN_ID -u AGENT_RUN_ORIGIN agentctl spawn <agent> --model opus
    --reason "needs deeper reasoning"`. Clearing both env vars drops `_run_origin`
    to its parentless root, which resolves `interactive` — the whole hole the
    finding names. But the calling process still runs with cwd inside its OWN
    registered worktree (`registry.list_runs()`), and that entry's run-id still
    has a real recorded origin in meta.json regardless of what the process's own
    env says. `_model_override_refusal` must catch it there; `cmd_spawn`'s
    preflight must refuse before any worktree/run-dir side effect, same as every
    other capped-origin case."""
    import telemetry as T
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-worker01", origin="scheduled")
    worktree = tmp_path / "worker-wt"
    worktree.mkdir()
    monkeypatch.setattr(agentctl.R, "list_runs",
                        lambda: [{"run_id": "run-worker01", "worktree": str(worktree)}])
    monkeypatch.chdir(worktree)
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)

    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})

    def _unreached(*a, **kw):
        raise AssertionError("cmd_spawn must refuse before touching R.can_spawn")
    monkeypatch.setattr(agentctl.R, "can_spawn", _unreached)

    args = _cmd_spawn_args(model="opus", reason="needs deeper reasoning")
    assert agentctl.cmd_spawn(args) == 2


def test_override_refusal_origin_catches_env_cleared_plus_leaked_parent(agentctl, tmp_path, monkeypatch):
    """The narrower variant from the same finding's second paragraph:
    `_run_origin`'s anti-downgrade check only fires `if own_run_id and own_run_id
    != parent`, so `env -u AGENTCTL_RUN_ID agentctl spawn <agent> --model opus
    --reason "..." --parent <leaked-interactive-run-id>` makes `own_run_id`
    falsy and skips it — `_run_origin` alone resolves the named parent's
    genuinely-recorded `interactive` origin at face value. Closed the same way
    as the base bypass: the calling process's OWN registered worktree still
    carries its real (capped) origin in the registry regardless of the named
    --parent or the cleared env var, and `_model_override_refusal` checks that
    independently of what `_run_origin(parent)` answered."""
    import telemetry as T
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-worker01", origin="scheduled")
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-public-interactive", origin="interactive")
    worktree = tmp_path / "worker-wt"
    worktree.mkdir()
    monkeypatch.setattr(agentctl.R, "list_runs",
                        lambda: [{"run_id": "run-worker01", "worktree": str(worktree)}])
    monkeypatch.chdir(worktree)
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)

    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})

    def _unreached(*a, **kw):
        raise AssertionError("cmd_spawn must refuse before touching R.can_spawn")
    monkeypatch.setattr(agentctl.R, "can_spawn", _unreached)

    args = _cmd_spawn_args(model="opus", reason="needs deeper reasoning",
                           parent="run-public-interactive")
    assert agentctl.cmd_spawn(args) == 2


def test_override_refusal_origin_permits_interactive_co_outside_any_worktree(agentctl, tmp_path, monkeypatch):
    """The regression that matters most: a genuine interactive `co` session sets
    neither AGENT_RUN_ORIGIN nor AGENTCTL_RUN_ID (`bin/co` sets neither) and its
    cwd is not inside any dispatched worker's registered worktree — a fail-closed
    resolver that refused this would break every interactive override on the
    machine. Must stay PERMITTED."""
    empty_dir = tmp_path / "not-a-worktree"
    empty_dir.mkdir()
    monkeypatch.setattr(agentctl.R, "list_runs", lambda: [])
    monkeypatch.chdir(empty_dir)
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)

    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})
    reached = {}
    def _mark_reached(*a, **kw):
        reached["yes"] = True
        return False, [], "stopped here on purpose"
    monkeypatch.setattr(agentctl.R, "can_spawn", _mark_reached)

    args = _cmd_spawn_args(model="opus", reason="needs deeper reasoning")
    agentctl.cmd_spawn(args)
    assert reached.get("yes"), "fail-closed resolver wrongly refused a genuine interactive override"


def test_model_override_refusal_catches_a_removed_cwd(agentctl, tmp_path, monkeypatch):
    """reviewer's round-3 blocking finding: `_model_override_refusal` fell
    straight through to the spoofable `_run_origin(parent)` value whenever
    `Path.cwd()` raised, because the registry/cwd check was gated behind
    `if cwd is not None`. A worker can reproduce the exact round-1 bypass one
    step further by removing its own cwd first:
    `mkdir /tmp/x && cd /tmp/x && rmdir /tmp/x && env -u AGENTCTL_RUN_ID
    -u AGENT_RUN_ORIGIN agentctl spawn <agent> --model opus --reason "..."`.
    Reproduced here by actually removing a real tmp dir out from under the
    process (not monkeypatching `Path.cwd`), so this exercises what the OS
    genuinely does — `os.getcwd()` raises `FileNotFoundError` once the
    directory is gone."""
    doomed = tmp_path / "doomed-cwd"
    doomed.mkdir()
    monkeypatch.chdir(doomed)
    doomed.rmdir()
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)

    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})

    def _unreached(*a, **kw):
        raise AssertionError("cmd_spawn must refuse before touching R.can_spawn")
    monkeypatch.setattr(agentctl.R, "can_spawn", _unreached)

    args = _cmd_spawn_args(model="opus", reason="needs deeper reasoning")
    assert agentctl.cmd_spawn(args) == 2


