def test_model_override_refusal_skips_an_unrelated_unresolvable_registry_entry(agentctl, tmp_path, monkeypatch):
    """reviewer's round-4 non-blocking finding: round 3 turned a per-entry
    `Path(wt).resolve()` failure into a whole-spawn refusal, which means an
    unrelated LIVE run's unresolvable `worktree` denies every interactive
    override on the machine — and a worker that plants a garbage worktree
    value in its own registry entry can deny everyone else's rather than
    merely defeating its own check. This is safe to revert to a skip only
    because source 2 (the caller's own `AGENTCTL_RUN_ID`, checked
    independently of the registry) now covers the case that actually
    matters — see `test_model_override_refusal_catches_a_corrupted_own_meta_json`.
    A genuine interactive spawn, unrelated to the bad entry, must stay
    PERMITTED."""
    empty_dir = tmp_path / "not-a-worktree"
    empty_dir.mkdir()
    monkeypatch.chdir(empty_dir)
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)

    monkeypatch.setattr(agentctl.R, "list_runs",
                        lambda: [{"run_id": "run-some-other-run", "worktree": "/some/path"}])

    real_resolve = Path.resolve
    def _resolve(self, *a, **kw):
        if str(self) == "/some/path":
            raise OSError("simulated resolution failure")
        return real_resolve(self, *a, **kw)
    monkeypatch.setattr(Path, "resolve", _resolve)

    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})
    reached = {}
    def _mark_reached(*a, **kw):
        reached["yes"] = True
        return False, [], "stopped here on purpose"
    monkeypatch.setattr(agentctl.R, "can_spawn", _mark_reached)

    args = _cmd_spawn_args(model="opus", reason="needs deeper reasoning")
    agentctl.cmd_spawn(args)
    assert reached.get("yes"), ("an unrelated run's unresolvable registry entry wrongly "
                                "refused an unrelated interactive override")


