# --- tool surface + MCP server narrowing from policy (issue_01M4BT13RP23KRTA80VM6R7HNF) --
#
# Every dispatched turn re-sends the run's opening context, so a built-in or MCP
# server the policy never allows is a schema paid for on every turn, not once.
# `_builtin_tool_surface` narrows `--tools`; `_mcp_servers_for_policy` narrows which
# of `kb`/`ops` `--mcp-config` names. Both read ONLY the policy's own `allowed`
# rules, so they're exercised here against synthetic `TP.Policy` objects — some
# shapes (no MCP tool at all, a kb-only allow) no real roster agent resolves to
# today, and the point of a pure function taking a `Policy` is that it doesn't
# need one that does.

def _policy(agentctl, *, allowed=(), enforced=True):
    return agentctl.TP.Policy(agent="x", runtime=agentctl.TP.AUTONOMOUS, repo="agent-platform",
                              allowed=tuple(allowed), enforced=enforced)


def test_builtin_tool_surface_reviewer_shaped(agentctl):
    """A reviewer-shaped policy (ARCH-346's real allow-list): the built-ins its
    `Bash(...)`/bare-tool rules name, deduped and sorted, with the two
    `mcp__ops__` rules excluded — they name an MCP tool, not a `--tools`
    built-in."""
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list", "Bash(git diff:*)", "Bash(git log:*)",
                  "Bash(gh pr view:*)", "Bash(agentctl review-post:*)"))
    assert agentctl._builtin_tool_surface(policy) == ("Bash", "Glob", "Grep", "Read", "Write")


def test_builtin_tool_surface_unenforced_keeps_todays_behaviour(agentctl):
    """A coder-shaped policy (`enforced=False`, ARCH-346's honest "deny-list
    only" state) has no allow-list to narrow BY — `None` means "pass no --tools
    flag", the full built-in surface a build-class agent needs today."""
    policy = _policy(agentctl, allowed=(), enforced=False)
    assert agentctl._builtin_tool_surface(policy) is None


def test_builtin_tool_surface_no_policy_keeps_todays_behaviour(agentctl):
    assert agentctl._builtin_tool_surface(None) is None


def test_builtin_tool_surface_enforced_empty_allowed_keeps_todays_behaviour(agentctl):
    """An enforced policy with nothing in `allowed` is the same "no real
    allow-list" case as `enforced=False` — not "allow nothing"."""
    policy = _policy(agentctl, allowed=(), enforced=True)
    assert agentctl._builtin_tool_surface(policy) is None


def test_builtin_tool_surface_mcp_only_allow_disables_all_builtins(agentctl):
    """An enforced policy that DID answer, and named only MCP tools: the
    built-in surface is empty, and the caller must pass `--tools ""` — this
    is the one case where the function returns `()` rather than `None`."""
    policy = _policy(agentctl, allowed=("mcp__ops__issue_get", "mcp__kb__kb_search"))
    assert agentctl._builtin_tool_surface(policy) == ()


def test_mcp_servers_for_policy_ops_only(agentctl):
    policy = _policy(agentctl, allowed=("Read", "Bash(git diff:*)", "mcp__ops__issue_get",
                                        "mcp__ops__issue_list"))
    assert agentctl._mcp_servers_for_policy(policy) == {"ops"}


def test_mcp_servers_for_policy_kb_only(agentctl):
    policy = _policy(agentctl, allowed=("Read", "mcp__kb__kb_search"))
    assert agentctl._mcp_servers_for_policy(policy) == {"kb"}


def test_mcp_servers_for_policy_neither(agentctl):
    """A policy allowing no MCP tool at all gets an empty set — the caller still
    passes `--mcp-config`, with zero servers in it."""
    policy = _policy(agentctl, allowed=("Read", "Bash(ruff check --isolated .)"))
    assert agentctl._mcp_servers_for_policy(policy) == set()


def test_mcp_servers_for_policy_unenforced_keeps_todays_behaviour(agentctl):
    policy = _policy(agentctl, allowed=(), enforced=False)
    assert agentctl._mcp_servers_for_policy(policy) is None


def test_mcp_servers_for_policy_no_policy_keeps_todays_behaviour(agentctl):
    assert agentctl._mcp_servers_for_policy(None) is None


# --- no agent may lose a tool its own definition grants (round 1 of #811) ----
#
# Round 1 review (both reviewer and security-reviewer): `_READ_SURFACE` in
# `tool_policy.py` grants `reviewer`/`security-reviewer`/`planner`/
# `platform-planner`/`scout` no `mcp__kb__` rule at all, but each of their own
# roster `tools:` lines grants one — reviewer's and security-reviewer's own
# role file, and the security-review rubric, instruct calling it to check a
# diff against recorded decisions. Narrowing on `policy.allowed` ALONE cut
# every one of them off from `kb` on every dispatch, not only once live
# enforcement turns on. The fix is a union with the agent's own `tools:` grant
# (`agent_tools`, `_run_session`'s already-resolved `agent["tools"]`).

def test_mcp_servers_for_policy_agent_tools_restores_a_server_the_policy_omits(agentctl):
    """A reviewer-shaped policy with no `mcp__kb__` rule (today's real
    `_READ_SURFACE`): the server still attaches when the agent's OWN roster
    `tools:` line names a `kb` tool. This is the exact shape of the round-1
    finding — against 238eec50 this assertion fails (`{"ops"}`, no `kb`)."""
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list", "Bash(git diff:*)", "Bash(gh pr view:*)"))
    servers = agentctl._mcp_servers_for_policy(policy, ("mcp__kb__kb_search",))
    assert servers == {"kb", "ops"}


def test_mcp_servers_for_policy_agent_tools_noop_when_policy_already_grants_it(agentctl):
    """The union doesn't double-count or change anything when the policy
    already names the server the agent's roster also names."""
    policy = _policy(agentctl, allowed=("Read", "mcp__kb__kb_search"))
    assert agentctl._mcp_servers_for_policy(policy, ("mcp__kb__kb_search",)) == {"kb"}


def test_mcp_servers_for_policy_agent_tools_ignored_when_policy_does_not_narrow(agentctl):
    """`agent_tools` plays no role once the policy itself returns `None`
    (today's full both-servers behaviour already covers it) — a build-class
    agent's own `tools:` grant must not flip this function's "no narrowing"
    answer into a narrowed one."""
    policy = _policy(agentctl, allowed=(), enforced=False)
    assert agentctl._mcp_servers_for_policy(policy, ("mcp__kb__kb_search",)) is None


def test_builtin_tool_surface_agent_tools_restores_a_builtin_the_policy_omits(agentctl):
    """The same union, for `--tools`: a built-in the policy's `allowed` never
    names (here, `TodoWrite`) still reaches the surface when the agent's own
    roster grants it."""
    policy = _policy(agentctl, allowed=("Read", "Grep"))
    surface = agentctl._builtin_tool_surface(policy, ("Read", "TodoWrite"))
    assert surface == ("Grep", "Read", "TodoWrite")


@pytest.mark.parametrize("agent_name, kb_tools", [
    ("reviewer", ("mcp__kb__kb_search",)),
    ("security-reviewer", ("mcp__kb__kb_search", "mcp__kb__kb_get")),
    ("planner", ("mcp__kb__kb_search",)),
    ("platform-planner", ("mcp__kb__kb_search",)),
    ("scout", ("mcp__kb__kb_search",)),
])
def test_every_enforceable_agent_keeps_its_own_roster_kb_grant_after_narrowing(
        agentctl, agent_name, kb_tools):
    """For every `ENFORCEABLE_AGENTS` member the round-1 review named as
    carrying a `kb` grant its own roster declares (reviewer's and
    security-reviewer's `tools:` frontmatter cited directly; planner,
    platform-planner and scout named in the revise brief), resolve the REAL
    policy `tool_policy.resolve` produces today and assert the union keeps
    every one of its roster's own `mcp__kb__` tools reachable. This is the
    test the round-1 finding says would have caught the regression; it fails
    against 238eec50 (`_mcp_servers_for_policy` there takes no `agent_tools`
    and drops `kb` for all five)."""
