def test_parse_frontmatter_joins_wrapped_multiline_scalar(agentctl):
    """A `tools:` value folded across three lines — the shape every real
    SATCHEL roster file wraps a long grant to, synthetic here (PR #811 round 2,
    issue_01M4BT13RP23KRTA80VM6R7HNF). Against the unfixed parser, the
    second line's embedded `:` inside `Bash(agentctl review-post:*)` would
    split it into a spurious extra key, and the third line (no `:` at all)
    would be silently dropped, taking the kb rules with it — so `fm["tools"]`
    there is the first line alone, with no kb rule in it."""
    text = (
        "---\n"
        "model: sonnet\n"
        "tools: Read, Grep, Glob, Bash(git diff:*), Bash(git log:*),\n"
        "  Bash(agentctl review-post:*), Bash(gh pr comment:*),\n"
        "  mcp__kb__kb_search, mcp__kb__kb_get\n"
        "---\n"
        "You are a test agent.\n"
    )
    fm, body = agentctl._parse_frontmatter(text)
    assert fm["model"] == "sonnet"
    assert fm["tools"] == (
        "Read, Grep, Glob, Bash(git diff:*), Bash(git log:*), "
        "Bash(agentctl review-post:*), Bash(gh pr comment:*), "
        "mcp__kb__kb_search, mcp__kb__kb_get"
    )
    assert body.strip() == "You are a test agent."
    # the bug's spurious extra key must not appear
    assert "Bash(agentctl review-post" not in fm


def test_parse_tool_rules_splits_comma_string_outside_parens(agentctl):
    """Splits on commas OUTSIDE parentheses, so a rule like
    `Bash(agentctl review-post:*)` — whose own text has no comma but sits
    next to rules that do — stays one rule rather than being cut mid-rule by
    a comma belonging to an adjacent rule's argument. No rule in the result
    is a single character, which is what `tuple("a string")` would produce
    if this split were skipped."""
    value = ("Read, Grep, Glob, Bash(git diff:*), Bash(git log:*), "
             "Bash(agentctl review-post:*), Bash(gh pr comment:*), "
             "mcp__kb__kb_search, mcp__kb__kb_get")
    rules = agentctl._parse_tool_rules(value)
    assert rules == [
        "Read", "Grep", "Glob", "Bash(git diff:*)", "Bash(git log:*)",
        "Bash(agentctl review-post:*)", "Bash(gh pr comment:*)",
        "mcp__kb__kb_search", "mcp__kb__kb_get",
    ]
    assert all(len(r) > 1 for r in rules)


def test_parse_tool_rules_accepts_list_and_falsy_shapes_unchanged(agentctl):
    assert agentctl._parse_tool_rules(["Read", "Bash"]) == ["Read", "Bash"]
    assert agentctl._parse_tool_rules([]) == []
    assert agentctl._parse_tool_rules(None) == []
    assert agentctl._parse_tool_rules("") == []
    assert agentctl._parse_tool_rules("   ") == []


# --- PR-3: _read_gateway_spend + _elapsed_minutes + _finalize_run cost logic ---


def _mk_run_dir(tmp_path, *, started_min_ago=5):
    """Create a minimal run_dir suitable for _finalize_run tests."""
    rd = tmp_path / "run-test"
    rd.mkdir()
    (rd / "prompts").mkdir()
    (rd / "transcript.jsonl").touch()
    (rd / "tool_calls.jsonl").touch()
    started = (datetime.now(timezone.utc) - timedelta(minutes=started_min_ago)
               ).strftime("%Y-%m-%dT%H:%M:%SZ")
    (rd / "meta.json").write_text(json.dumps({
        "run_id": "run-test",
        "agent": "bug-fixer",
        "task": "fix a bug",
        "started_at": started,
        "ended_at": None,
        "parent_run": None,
        "repo": "agent-platform",
        "worktree": str(tmp_path / "wt"),
        "profile": "agent-platform/daytime",
        "model": "claude-opus-4-7",
        "pid": 99999,
        "billing_source": "unknown",
    }))
    # minimal git repo so _changed_files doesn't crash
    wt = tmp_path / "wt"
    wt.mkdir()
    subprocess.run(["git", "init", "-q"], cwd=str(wt), check=True, capture_output=True)
    (rd / "started_head.txt").write_text("unknown\n")
    (rd / "started_dirty.txt").write_text("")
    return rd, wt


def test_read_gateway_spend_handles_missing_and_empty_files(agentctl, tmp_path):
    """Returns (0.0, 0, 0, False) for both missing and empty files."""
    missing = tmp_path / "no_such.jsonl"
    usd, tin, tout, found = agentctl._read_gateway_spend(missing)
    assert (usd, tin, tout, found) == (0.0, 0, 0, False)

    empty = tmp_path / "empty.jsonl"
    empty.touch()
    usd, tin, tout, found = agentctl._read_gateway_spend(empty)
    assert (usd, tin, tout, found) == (0.0, 0, 0, False)


def test_read_gateway_spend_sums_records(agentctl, tmp_path):
    """Sums usd AND tokens across multiple JSONL rows (same source for both)."""
    log = tmp_path / "spend.jsonl"
    log.write_text(
        json.dumps({"ts": "2026-05-31T10:00:01Z", "model": "deepseek/deepseek-v4-flash",
                    "tokens_in": 100, "tokens_out": 50, "usd": 0.0012, "request_id": "r1"}) + "\n" +
        json.dumps({"ts": "2026-05-31T10:00:02Z", "model": "deepseek/deepseek-v4-flash",
                    "tokens_in": 200, "tokens_out": 80, "usd": 0.0011, "request_id": "r2"}) + "\n"
    )
    usd, tin, tout, found = agentctl._read_gateway_spend(log)
    assert found is True
    assert usd == pytest.approx(0.0023, abs=1e-9)
    assert tin == 300 and tout == 130


def test_finalize_anthropic_branch_byte_identical(agentctl, tmp_path, monkeypatch):
    """Anthropic run: cost.json sources usd from total_cost_usd, cost_source='anthropic_cli'.

    Pins the 'Anthropic path byte-identical' guarantee (ARCH-102).
    """
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)

    final_event = {
        "type": "result", "subtype": "success",
        "model": "claude-opus-4-7",
        "usage": {"input_tokens": 1000, "output_tokens": 200,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.42,
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=0, final_event=final_event,
        profile="agent-platform/daytime",
        agent={"model_alias": "opus"},
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert cost["usd"] == pytest.approx(0.42)
    assert cost["cost_source"] == "anthropic_cli"
    assert "claude-opus-4-7" in cost["by_model"]


def test_finalize_gateway_sources_from_spend_log(agentctl, tmp_path, monkeypatch):
    """Gateway run with spend log: cost.json sources usd from the log, not from total_cost_usd.

    The CLI's (wrong Anthropic-priced) total_cost_usd is explicitly NOT used.
    """
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)

    # Write a gateway_spend.jsonl with two rows summing to $0.0023
    spend_log = rd / "gateway_spend.jsonl"
    spend_log.write_text(
        json.dumps({"usd": 0.0012, "model": "deepseek/deepseek-v4-flash",
                    "tokens_in": 100, "tokens_out": 50, "ts": "x", "request_id": "r1"}) + "\n" +
        json.dumps({"usd": 0.0011, "model": "deepseek/deepseek-v4-flash",
                    "tokens_in": 200, "tokens_out": 80, "ts": "x", "request_id": "r2"}) + "\n"
    )

    # final-event usage carries only the LAST turn (5000/999) and a wrong
    # Anthropic-priced cost — neither must reach cost.json for a gateway run.
    final_event = {
        "type": "result", "subtype": "success",
        "model": "deepseek/deepseek-v4-flash",
        "usage": {"input_tokens": 5000, "output_tokens": 999,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.42,  # wrong Anthropic-priced figure — must NOT be used
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=0, final_event=final_event,
        profile="agent-platform/daytime",
        agent={"model_alias": "deepseek"},
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert cost["usd"] == pytest.approx(0.0023, abs=1e-9)
    assert cost["cost_source"] == "gateway_spend_log"
    # tokens are the CUMULATIVE spend-log sums (100+200 / 50+80), not the
    # final event's last-turn 5000/999 — usd and tokens share one source.
    bm = cost["by_model"]["deepseek/deepseek-v4-flash"]
    assert bm["tokens_in"] == 300 and bm["tokens_out"] == 130
    assert cost["tokens_in"] == 300 and cost["tokens_out"] == 130
    assert "deepseek/deepseek-v4-flash" in cost["by_model"]


def test_finalize_errored_gateway_run_records_real_spend(agentctl, tmp_path, monkeypatch):
    """ARCH-185 regression: an ERRORED gateway run (no final_event) must still record
    its REAL gateway spend from the log, sourcing the model from meta.json. The prior
    `if final_event:` gate wrote cost.json usd:0 for errored runs, so the scorecard
    AND the budget cap went blind to the 2026-06-18 $23 kimi loop."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)
    meta = json.loads((rd / "meta.json").read_text())
    meta["model"] = "moonshot/kimi-k2.7-code"   # an errored run has no final_event
    (rd / "meta.json").write_text(json.dumps(meta))
    (rd / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 23.49, "model": "kimi-k2.7-code",
                    "tokens_in": 121000000, "tokens_out": 60000, "ts": "x"}) + "\n")
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=1, final_event=None,            # errored: no terminal event
        profile="agent-platform/daytime", agent={"model_alias": "kimi-code"},
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert cost["cost_source"] == "gateway_spend_log"
    assert cost["usd"] == pytest.approx(23.49)
    assert "moonshot/kimi-k2.7-code" in cost["by_model"]


def test_finalize_run_deletes_a_stale_cost_partial(agentctl, tmp_path, monkeypatch):
    """cost.json's write at finalisation supersedes cost-partial.json — the
    checkpoint left behind from while the run was live is removed so nothing
    downstream can mistake it for current (issue_01M1D1HNMGCAKH89ZWY3XSJPGS)."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
