def test_stream_transcript_prices_a_1h_cache_write_at_the_1h_rate(
        agentctl, tmp_path, monkeypatch):
    """A turn's `usage.cache_creation` TTL breakdown must survive
    `_stream_transcript`'s per-turn accumulation into the cost-partial
    checkpoint, which prices it through `T.cost_from_usage`. Sonnet 5: input
    $2/Mtok, 1h cache write $4/Mtok — a turn with no input/output tokens and
    1M 1h-cache-write tokens prices to exactly $4 only if the breakdown
    reached the checkpoint; dropping it (falling back to the flat
    `cache_creation_input_tokens` field, which this turn leaves at 0) would
    price it at $0."""
    monkeypatch.setattr(agentctl, "_COST_PARTIAL_WRITE_INTERVAL_S", 0.0)
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    events = [_assistant_event(
        model="claude-sonnet-5", input_tokens=0, output_tokens=0,
        cache_creation={"ephemeral_1h_input_tokens": 1_000_000,
                        "ephemeral_5m_input_tokens": 0})]
    agentctl._stream_transcript(_FakeStreamProc(events), run_dir)
    partial = json.loads((run_dir / "cost-partial.json").read_text())
    assert partial["usd"] == pytest.approx(4.0)


