def test_stream_transcript_survives_a_live_import_failure(agentctl, tmp_path, monkeypatch):
    """Same resilience rule as the cost-partial checkpoint: a failure importing a
    live run's private objects (a concurrent write mid-enumeration, a full disk) must
    not unwind this loop — the end-of-run import still runs unconditionally once the
    run exits."""
    monkeypatch.setattr(agentctl, "_LIVE_IMPORT_INTERVAL_S", 0.0)

    def _raise(*a, **k):
        raise subprocess.CalledProcessError(1, ["git", "index-pack"])
    monkeypatch.setattr(agentctl.RS, "import_private_objects", _raise)
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    final_event, cost_stop_reason = agentctl._stream_transcript(
        _FakeStreamProc([_assistant_event(), {"type": "system", "subtype": "init"}]), run_dir,
        git_dir=tmp_path / "git-dir", private_objects_dir=tmp_path / "private-dir")
    assert final_event is None  # drained past the failed import on line 1, line 2 too
    assert cost_stop_reason is None  # no cap configured: never a candidate breach
    assert "live import" in (run_dir / "stderr.log").read_text()


def test_stream_transcript_survives_a_checkpoint_write_failure_and_cap_breach_still_terminates(
        agentctl, tmp_path, monkeypatch):
    """Round 2 (security-reviewer finding on agent-platform#592): a
    cost-partial.json write that raises for ANY reason (a symlink planted at
    the checkpoint's temp path, a permission error, anything else) must not
    unwind _stream_transcript's per-line drain loop — that same loop enforces
    the gateway cost-cap circuit breaker (_read_gateway_spend + proc.terminate),
    so letting the exception propagate would silently disable cap enforcement
    for the rest of the run. Confirmed to fail against 3fbd740: there the
    exception is uncaught, propagates straight out of _stream_transcript, and
    the second (cap-breaching) line is never reached at all."""
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 999.0, "tokens_in": 1, "tokens_out": 1, "ts": "x"}) + "\n")

    def _raise(*a, **k):
        raise OSError("ELOOP: symlink planted at the checkpoint's temp path")
    monkeypatch.setattr(agentctl.T, "write_cost_partial", _raise)

    cost_interval = agentctl._COST_CHECK_INTERVAL_S
    partial_interval = agentctl._COST_PARTIAL_WRITE_INTERVAL_S
    # time.monotonic() is read: twice at setup (last_cost_check,
    # last_partial_write), then per-line for the cap check (1 call, or 2 when
    # it fires and resets) and the partial-write check (same shape). Keep
    # line 1 under both intervals except the partial-write one (so the
    # checkpoint — and its injected failure — actually fires there), then
    # jump the cap-check clock past its interval for line 2 so the breach
    # fires there instead.
    calls = iter([0.0, 0.0,
                  5.0,
                  partial_interval + 5.0, partial_interval + 6.0,
                  cost_interval + 10.0, cost_interval + 11.0])
    monkeypatch.setattr(agentctl.time, "monotonic",
                        lambda: next(calls, cost_interval + 11.0))

    events = [_assistant_event(), {"type": "system", "subtype": "init"}]
    proc = _FakeStreamProc(events)
    terminated = []
    proc.terminate = lambda: terminated.append(True)

    final_event, cost_stop_reason = agentctl._stream_transcript(proc, run_dir, cost_cap=1.0)

    assert terminated == [True]          # the cap breach on line 2 still fires
    assert final_event is None           # drained past line 1's failed checkpoint
    assert cost_stop_reason is not None  # the breach that terminated it is reported back
    assert not (run_dir / "cost-partial.json").exists()  # the failed write left nothing
    assert "checkpoint" in (run_dir / "stderr.log").read_text()


def test_stream_transcript_survives_a_non_numeric_usage_field_and_cap_breach_still_terminates(
        agentctl, tmp_path, monkeypatch):
    """Round 2 (security-reviewer finding on agent-platform#592): a usage
    block with a non-numeric token field (int() raising ValueError/TypeError)
    must not unwind the same drain loop either. Unlike an OSError, that
    exception isn't caught by the call site's `except (BrokenPipeError,
    OSError)`, so an uncaught one would crash the whole spawn command, not
    just this loop. Confirmed to fail against 3fbd740: there the int() call
    raises straight out of _stream_transcript and the second (cap-breaching)
    line is never reached."""
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 999.0, "tokens_in": 1, "tokens_out": 1, "ts": "x"}) + "\n")

    bad_event = _assistant_event()
    bad_event["message"]["usage"]["input_tokens"] = "not-a-number"

    cost_interval = agentctl._COST_CHECK_INTERVAL_S
    calls = iter([0.0, 0.0,
                  5.0, 6.0,
                  cost_interval + 10.0, cost_interval + 11.0])
    monkeypatch.setattr(agentctl.time, "monotonic",
                        lambda: next(calls, cost_interval + 11.0))

    events = [bad_event, {"type": "system", "subtype": "init"}]
    proc = _FakeStreamProc(events)
    terminated = []
    proc.terminate = lambda: terminated.append(True)

    final_event, cost_stop_reason = agentctl._stream_transcript(proc, run_dir, cost_cap=1.0)

    assert terminated == [True]          # the cap breach on line 2 still fires
    assert final_event is None           # drained past line 1's malformed usage
    assert cost_stop_reason is not None  # the breach that terminated it is reported back
    assert "usage" in (run_dir / "stderr.log").read_text()


@pytest.mark.parametrize("bad_value", [
    float("inf"), float("-inf"), float("nan"), 10**400,
    {"nested": "dict"}, [1, 2, 3],
], ids=["inf", "neg_inf", "nan", "huge_int", "nested_dict", "list"])
def test_stream_transcript_survives_any_malformed_usage_field_and_cap_breach_still_terminates(
        agentctl, tmp_path, monkeypatch, bad_value):
    """Round 3 (security-reviewer finding on agent-platform#592): round 2's
    `except (TypeError, ValueError)` at the usage-accumulation site still let
    an Infinity usage field escape — `json.loads` accepts the non-standard
    `Infinity`/`-Infinity`/`NaN` literals by default, and `int(float("inf"))`
    raises `OverflowError`, not `ValueError`/`TypeError`. That unwound
    `_stream_transcript` entirely (worse than round 1: the whole drain loop
    died, not just the checkpoint), silently disabling the cost/token-cap
    circuit breaker for the rest of the run. Broadened to a bare `except
    Exception` (this file) rather than re-typing to each newly observed
    failure mode; every value here (including ones that don't actually
    raise, like a huge-but-valid int, which stays a no-op) must leave the
    cap breach on line 2 intact."""
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 999.0, "tokens_in": 1, "tokens_out": 1, "ts": "x"}) + "\n")

    bad_event = _assistant_event()
    bad_event["message"]["usage"]["input_tokens"] = bad_value

    cost_interval = agentctl._COST_CHECK_INTERVAL_S
    calls = iter([0.0, 0.0,
                  5.0, 6.0,
                  cost_interval + 10.0, cost_interval + 11.0])
    monkeypatch.setattr(agentctl.time, "monotonic",
                        lambda: next(calls, cost_interval + 11.0))

    events = [bad_event, {"type": "system", "subtype": "init"}]
    proc = _FakeStreamProc(events)
    terminated = []
    proc.terminate = lambda: terminated.append(True)

    final_event, cost_stop_reason = agentctl._stream_transcript(proc, run_dir, cost_cap=1.0)

    assert terminated == [True]          # the cap breach on line 2 still fires
    assert final_event is None           # drained past line 1's malformed usage
    assert cost_stop_reason is not None  # the breach that terminated it is reported back


def _finalize_with_final_event(agentctl, rd, wt, *, model="claude-opus-4-7",
                               model_resolved="claude-opus-4-7", model_choice=None,
                               agent_name="bug-fixer", repo="agent-platform", issue=None,
                               crew="test-crew", purpose="build",
                               started_at="2026-01-01T00:00:00Z", trial=None):
    """Drive the real `_finalize_run`, passing `model`/`model_resolved`/
    `model_choice`/`agent_name`/`repo`/`issue`/`crew`/`purpose`/`started_at`/
    `trial` explicitly — the harness-resolved values the real caller
    (`_run_session`) threads through, rather than the vulnerable
    re-read-from-meta.json path removed in PR #477 rounds 2 and 3. Defaults
    mirror `_mk_run_dir`'s meta.json (model claude-opus-4-7, repo
    agent-platform, agent bug-fixer); `crew`/`purpose`/`started_at` default to
    synthetic values distinct from anything meta.json carries, so a test that
    doesn't care about CQ·489/CQ·510 still gets a record posted (`crew=None`
    suppresses the whole post — see `_post_model_resolution_signal`)."""
    final_event = {
        "type": "result", "subtype": "success", "model": "claude-opus-4-7",
        "usage": {"input_tokens": 100, "output_tokens": 10,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.01,
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=0, final_event=final_event,
        profile="agent-platform/daytime", agent={"model_alias": "opus"},
        model=model, model_resolved=model_resolved, model_choice=model_choice,
        agent_name=agent_name, repo=repo, issue=issue,
        crew=crew, purpose=purpose, started_at=started_at, trial=trial,
    )


