def _forge_every_meta_string_field(rd):
    """Overwrite every string-valued field in meta.json with a distinguishable
    forged marker, simulating a run's own subprocess rewriting its own
    meta.json before it exits — the only window it can reach the file at all.
    Returns {field: forged_value} for every string field, so a test can assert
    none of them leaked, rather than checking an enumerated few (round 2's
    four-field forge is what let model_resolved and repo's read-from-disk gap
    through — security review, PR #477 round 3)."""
    path = rd / "meta.json"
    meta = json.loads(path.read_text())
    forged = {k: f"forged-{k}" for k, v in meta.items() if isinstance(v, str)}
    meta.update(forged)
    path.write_text(json.dumps(meta))
    return forged


def _forge_after_every_write(monkeypatch, T):
    """Simulate a detached background write the run's own subprocess scheduled
    before it exited (`(sleep 90; write cost.json) & disown`), landing right
    after `_finalize_run`'s own legitimate `write_cost`/`write_outcome` calls —
    the exact race the round-4 security review named: the harness waits on the
    `claude -p` pid only, not a process group, so a subprocess can background a
    write that outlives it and lands during `_finalize_run`'s own later work
    (the docs-consulted scan, the Archives post), well before `agentctl
    publish` would run minutes later. Wraps the real `write_cost`/
    `write_outcome` so each real write is immediately followed by a forged one
    to the same file, and returns the forged {field: value} markers so a test
    can assert none of them leaked into the posted record."""
    real_write_cost, real_write_outcome = T.write_cost, T.write_outcome
    forged = {"usd": 999.9999, "exit_status": "forged-exit-status"}

    def _write_cost_then_forge(d, **kw):
        payload = real_write_cost(d, **kw)
        (d / "cost.json").write_text(json.dumps({
            "tokens_in": 1, "tokens_out": 1, "usd": forged["usd"],
            "cost_source": "anthropic_cli", "by_model": {}}))
        return payload

    def _write_outcome_then_forge(d, **kw):
        payload = real_write_outcome(d, **kw)
        (d / "outcome.json").write_text(json.dumps({
            "exit_status": forged["exit_status"], "files_modified": [],
            "files_added": [], "files_deleted": [], "prs_opened": [],
            "tests_run": None, "tests_passed": None, "subagents_spawned": []}))
        return payload

    monkeypatch.setattr(T, "write_cost", _write_cost_then_forge)
    monkeypatch.setattr(T, "write_outcome", _write_outcome_then_forge)
    return forged


def test_finalize_ignores_meta_cost_and_outcome_json_rewritten_after_spawn(
        agentctl, tmp_path, monkeypatch):
    """A run's own subprocess can reach its run_dir and rewrite meta.json before
    _finalize_run reads it back. Round 2 fixed this for model/model_choice/
    agent/issue only, by threading exactly those four through _finalize_run's
    parameters — round 3 found model_resolved and repo still read straight off
    that same subprocess-writable file, on the very path round 2 fixed,
    because round 2's own test forged only the four fields whoever wrote it
    thought of. Round 4 found the same gap one level over: cost.json and
    outcome.json were re-read off disk immediately after being written, and a
    subprocess-backgrounded write landing in that window (the harness waits on
    the `claude -p` pid only, not a process group) could still win the race.
    `_finalize_run` now threads cost/outcome through as the in-memory values
    `write_cost`/`write_outcome` just computed, so this forges every string
    field in meta.json (the only window a subprocess can reach it) AND
    simulates a same-window forged write to cost.json/outcome.json (the round-4
    window), and checks that nothing from either survives into the posted
    record (ARCH-193 binds review_sha the same way, for the same reason —
    security review, PR #477 rounds 2-4)."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)
    forged_meta = _forge_every_meta_string_field(rd)
    forged_cost_outcome = _forge_after_every_write(monkeypatch, agentctl.T)

    posted = {}
    monkeypatch.setattr(
        agentctl.SC, "post_structured",
        lambda kind, stream, body, **kw: (posted.update(kw), "created")[1])

    _finalize_with_final_event(
        agentctl, rd, wt, model="claude-opus-4-7", model_resolved="claude-opus-4-7",
        model_choice="operator_override", agent_name="bug-fixer",
        repo="agent-platform", issue="issue_01M174CH86JBCP7291PS0TM097")

    posted_blob = json.dumps(posted)
    for key, value in forged_meta.items():
        assert value not in posted_blob, (
            f"forged meta.json field {key}={value!r} leaked into the posted record")
    for key, value in forged_cost_outcome.items():
        assert str(value) not in posted_blob, (
            f"forged {key}={value!r}, written right after the legitimate "
            f"cost.json/outcome.json write, leaked into the posted record")

    m = posted["meta"]
    assert m["model"] == "claude-opus-4-7"
    assert m["model_resolved"] == "claude-opus-4-7"
    assert m["persona"] == "bug-fixer"
    assert m["choice"] == "operator_override"
    assert m["work_item"] == "issue_01M174CH86JBCP7291PS0TM097"
    assert m["outcome"]["exit_status"] == "completed"


