# --- _run_cost_cap_for_agent: the Library's grant cap vs the ordinary default/env
# (issue_01M174CABDWSEP2EEVY6JXZ5VB, the operator's 2026-10-07 ruling, slate a-1ommg6) -------


def test_a_grant_cap_is_read_ahead_of_the_default(agentctl, monkeypatch):
    """A dispatch with a Library checkout grant takes its cap from
    `agent["grant"]["budget"]["cap_usd"]`, regardless of the model — the
    Library decided the amount, so it applies even to a model name
    `_run_cost_cap` would otherwise treat as a subscription model with no cap."""
    monkeypatch.setenv("AGENTCTL_RUN_COST_CAP", "999")  # must be ignored on the grant path
    agent = {"grant": {"budget": {"cap_usd": 2.5}, "limits": {}, "documents": []}}
    assert agentctl._run_cost_cap_for_agent("claude-opus-4-7", agent) == (2.5, "grant")
    assert agentctl._run_cost_cap_for_agent("deepseek/deepseek-v4-flash", agent) == (2.5, "grant")


def test_a_null_grant_cap_is_a_valid_grant_decision_not_a_missing_one(agentctl):
    """`cap_usd: null` means the Library decided this project gets no dollar
    kill — a real decision, reported as source "grant" with cap None, not
    treated as though no grant were present."""
    agent = {"grant": {"budget": {"cap_usd": None}, "limits": {}, "documents": []}}
    assert agentctl._run_cost_cap_for_agent("deepseek/deepseek-v4-flash", agent) == (None, "grant")


def test_an_ordinary_dispatch_keeps_the_default_and_env_cap_unchanged(agentctl, monkeypatch):
    """No `grant` key (today's roster-render dispatch, which doesn't call
    checkout yet) falls through to `_run_cost_cap`'s existing behaviour,
    unchanged, just labeled "default" / "env" / "none"."""
    monkeypatch.delenv("AGENTCTL_RUN_COST_CAP", raising=False)
    agent = {"name": "coder"}  # no "grant" key
    assert agentctl._run_cost_cap_for_agent("moonshot/kimi-k2.7-code", agent) == (
        agentctl.DEFAULT_RUN_COST_CAP_USD, "default")
    assert agentctl._run_cost_cap_for_agent("claude-opus-4-7", agent) == (None, "none")
    monkeypatch.setenv("AGENTCTL_RUN_COST_CAP", "5")
    assert agentctl._run_cost_cap_for_agent("deepseek/deepseek-v4-flash", agent) == (5.0, "env")
    monkeypatch.setenv("AGENTCTL_RUN_COST_CAP", "0")
    assert agentctl._run_cost_cap_for_agent("deepseek/deepseek-v4-flash", agent) == (None, "env")


def test_a_grant_cap_kills_the_run_once_gateway_spend_passes_it_not_before(
        agentctl, tmp_path, monkeypatch):
    """The operator's 2026-10-07 ruling, case 1: a grant with cap_usd 2.5 kills the run
    when its gateway spend passes 2.5 and not before — same `_stream_transcript`
    breaker as always, fed the grant-resolved cap."""
    monkeypatch.setattr(agentctl, "_COST_CHECK_INTERVAL_S", 0.0)
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    agent = {"grant": {"budget": {"cap_usd": 2.5}, "limits": {}, "documents": []}}
    cap, source = agentctl._run_cost_cap_for_agent("deepseek/deepseek-v4-flash", agent)
    assert (cap, source) == (2.5, "grant")

    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 2.4, "tokens_in": 1, "tokens_out": 1, "ts": "x"}) + "\n")
    agentctl._stream_transcript(_FakeStreamProc([{"type": "system", "subtype": "init"}]),
                               run_dir, cost_cap=cap, token_cap=None)
    assert not (run_dir / "cost-killed.txt").exists()  # under the cap: no kill

    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 2.6, "tokens_in": 1, "tokens_out": 1, "ts": "x"}) + "\n")
    terminated = []
    proc = _FakeStreamProc([{"type": "system", "subtype": "init"}])
    proc.terminate = lambda: terminated.append(True)
    agentctl._stream_transcript(proc, run_dir, cost_cap=cap, token_cap=None)
    assert terminated == [True]  # past the cap: kill
    assert "2.50" in (run_dir / "cost-killed.txt").read_text()


