def test_the_run_record_names_the_caps_source_in_each_case(
        agentctl, runs_root, tmp_path, monkeypatch):
    """`cost_cap_source` on meta.json tells `agentctl status` which of
    VALID_COST_CAP_SOURCES applied — driven through the real (dry-run)
    `_run_session`, not just the pure resolver, so this pins the field actually
    reaching the run record."""
    import json as _json
    import types
    import telemetry as T

    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)
    monkeypatch.setattr(T, "RUNS_ROOT", runs_root)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.delenv("AGENTCTL_RUN_COST_CAP", raising=False)

    def _dry_run_meta(tmp_path, run_id, agent_def):
        run_dir = tmp_path / run_id
        run_dir.mkdir()
        worktree = tmp_path / (run_id + "-wt")
        worktree.mkdir()
        args = types.SimpleNamespace(agent="coder", task="t", parent=None,
                                     dry_run=True, label=None)
        rc = agentctl._run_session(
            args=args, agent=agent_def, run_id=run_id, run_dir=run_dir,
            worktree=worktree, profile="p", repo="agent-platform",
            started_at="2026-06-11T00:00:00Z", user_prompt="u")
        assert rc == 0
        return _json.loads((run_dir / "meta.json").read_text())

    grant_agent = {"body": "sys", "model_alias": "opus", "frontmatter": {"model": "opus"},
                  "grant": {"budget": {"cap_usd": 2.5}, "limits": {}, "documents": []}}
    meta = _dry_run_meta(tmp_path, "run-cap-source-grant", grant_agent)
    assert meta["cost_cap_source"] == "grant"

    gateway_agent = {"body": "sys", "model_alias": "deepseek",
                     "frontmatter": {"model": "deepseek"}}
    meta = _dry_run_meta(tmp_path, "run-cap-source-default", gateway_agent)
    assert meta["cost_cap_source"] == "default"

    subscription_agent = {"body": "sys", "model_alias": "opus",
                          "frontmatter": {"model": "opus"}}
    meta = _dry_run_meta(tmp_path, "run-cap-source-none", subscription_agent)
    assert meta["cost_cap_source"] == "none"


def test_finalize_gateway_no_record_writes_estimate_fallback(agentctl, tmp_path, monkeypatch):
    """Gateway run with no spend log: usd is a positive estimate, cost_source='estimate_fallback'.

    This is the 'never write usd: 0' guarantee (ARCH-065/069, ARCH-102).
    """
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path, started_min_ago=10)

    final_event = {
        "type": "result", "subtype": "success",
        "model": "openai/gpt-5",
        "usage": {"input_tokens": 500, "output_tokens": 100,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.0,  # gateway run has no Anthropic cost
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=0, final_event=final_event,
        profile="agent-platform/daytime",
        agent={"model_alias": "gpt5"},
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert cost["cost_source"] == "estimate_fallback"
    assert cost["usd"] > 0, "estimate_fallback must write a positive usd, never 0"


def test_finalize_forced_sonnet_not_mislabeled_as_roster_gateway_model(agentctl, tmp_path, monkeypatch):
    """ARCH-211: a full-monty run forced onto sonnet (AGENT_FULL_MONTY) records
    meta.model=claude-sonnet-4-6, but its terminal event may carry no model field.
    The cost resolver must then use meta.model (the ACTUAL model), NOT the agent's
    roster alias (glm) — else the run is mislabeled zai/glm-5.2 + estimate_fallback,
    inventing phantom gateway cost on a subscription sonnet run (the 2026-06-20
    ~$11.53 phantom). Regression pin for the resolution-order fix."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)
    meta = json.loads((rd / "meta.json").read_text())
    meta["model"] = "claude-sonnet-4-6"   # AGENT_FULL_MONTY forced sonnet
    (rd / "meta.json").write_text(json.dumps(meta))
    final_event = {  # terminal event WITHOUT a model field — the old bug's trigger
        "type": "result", "subtype": "success",
        "usage": {"input_tokens": 1000, "output_tokens": 50,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.02,
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=0, final_event=final_event,
        profile="outfitter/overnight",
        agent={"model_alias": "glm"},   # bug-fixer's roster model — must NOT be used
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert "claude-sonnet-4-6" in cost["by_model"], "must label the actual (sonnet) model"
    assert "zai/glm-5.2" not in cost["by_model"], "must NOT mislabel as the roster gateway model"
    assert cost["cost_source"] == "anthropic_cli", "sonnet run → anthropic_cli, not estimate_fallback"
    assert cost["usd"] == pytest.approx(0.02), "usd from the CLI cost, not a phantom estimate"


def test_finalize_estimate_fallback_null_timestamps_writes_positive_usd(agentctl, tmp_path, monkeypatch):
    """estimate_fallback with null started_at (→ elapsed=0.0) must still write positive usd.

    Regression for the usd: 0 bug: elapsed_min=0 → 0*0.15=0 → must be floored
    to 0.0001 (ARCH-065/069, ARCH-102).
    """
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd = tmp_path / "run-no-ts"
    rd.mkdir()
    (rd / "prompts").mkdir()
    (rd / "transcript.jsonl").touch()
    (rd / "tool_calls.jsonl").touch()
    # null started_at → _elapsed_minutes returns 0.0 → elapsed * 0.15 = 0.0
    (rd / "meta.json").write_text(json.dumps({
        "run_id": "run-no-ts", "agent": "coder", "task": "test",
        "started_at": None, "ended_at": None,
        "parent_run": None, "repo": "agent-platform",
        "worktree": str(tmp_path / "wt"),
        "profile": "agent-platform/daytime",
        "model": "openai/gpt-5", "pid": 99999, "billing_source": "unknown",
    }))
    wt = tmp_path / "wt"
    wt.mkdir()
    subprocess.run(["git", "init", "-q"], cwd=str(wt), check=True, capture_output=True)
    (rd / "started_head.txt").write_text("unknown\n")
    (rd / "started_dirty.txt").write_text("")
    final_event = {
        "type": "result", "subtype": "success",
        "model": "openai/gpt-5",
        "usage": {"input_tokens": 100, "output_tokens": 20,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0},
        "total_cost_usd": 0.0,
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-no-ts",
        exit_code=0, final_event=final_event,
        profile="agent-platform/daytime",
        agent={"model_alias": "gpt5"},
    )
    cost = json.loads((rd / "cost.json").read_text())
    assert cost["cost_source"] == "estimate_fallback"
    assert cost["usd"] >= 0.0001, (
        "estimate_fallback must never write usd: 0; floor is 0.0001 "
        "(elapsed_min=0 case, ARCH-065/069)"
    )


