def test_scrub_authorization_header_captures_full_value(agentctl):
    """Authorization: Bearer <token> must scrub the token, not stop at the first word.

    The broken regex (Authorization\\s*:\\s*\\S+) matched only 'Authorization: Bearer',
    leaving the actual credential — ya29.*, Basic base64, or multi-word tokens — in
    the clear. Each assertion below checks the secret substring itself is absent, not
    merely that '[redacted]' appears somewhere (a weaker assertion that would pass
    against the old broken regex).
    """
    scrub = agentctl._scrub_api_error_message

    # Google OAuth token (ya29.*) — the platform's own auth shape
    out = scrub("Authorization: Bearer ya29.a0ABVJMMvOAuth2TokenHere12345678")
    assert "ya29.a0ABVJMMvOAuth2TokenHere12345678" not in out

    # HTTP Basic credential (base64-encoded user:pass)
    out = scrub("Authorization: Basic dXNlcjpwYXNzd29yZA==")
    assert "dXNlcjpwYXNzd29yZA==" not in out

    # Anthropic API key in an Authorization: Bearer header (was accidentally double-
    # redacted by the sk-ant- branch; now the Authorization branch catches the whole line)
    out = scrub("Authorization: Bearer sk-ant-api03-SomeRealToken12345678901234")
    assert "sk-ant-api03-SomeRealToken12345678901234" not in out

    # x-api-key header with a multi-word-style secret (whitespace-delimited suffix)
    out = scrub("x-api-key: my-super-secret-key-12345abcdef extra-part")
    assert "my-super-secret-key-12345abcdef" not in out
    assert "extra-part" not in out


def test_scrub_github_tokens(agentctl):
    """GitHub PAT shapes (classic ghp_/gho_/ghu_/ghs_/ghr_ and fine-grained github_pat_) are redacted."""
    scrub = agentctl._scrub_api_error_message

    # Classic PAT (ghp_) — 36 alphanumeric chars after the prefix
    token = "ghp_" + "A" * 32 + "1234"
    out = scrub(f"Unauthorized: token {token} is invalid")
    assert token not in out
    assert "[redacted]" in out

    # OAuth token (gho_)
    token = "gho_" + "B" * 32 + "5678"
    out = scrub(f"error: {token}")
    assert token not in out
    assert "[redacted]" in out

    # Server-to-server App token (ghs_)
    token = "ghs_" + "C" * 32 + "9012"
    out = scrub(f"bad credentials {token}")
    assert token not in out
    assert "[redacted]" in out

    # User-to-server token (ghu_)
    token = "ghu_" + "E" * 32 + "3456"
    out = scrub(f"forbidden: {token}")
    assert token not in out
    assert "[redacted]" in out

    # Refresh token (ghr_)
    token = "ghr_" + "F" * 32 + "7890"
    out = scrub(f"token expired: {token}")
    assert token not in out
    assert "[redacted]" in out

    # Fine-grained PAT (github_pat_)
    token = "github_pat_" + "D" * 36 + "_extra"
    out = scrub(f"forbidden: {token}")
    assert token not in out
    assert "[redacted]" in out

    # Short prefix alone must NOT be redacted (false-positive guard)
    out = scrub("ghp_short does not qualify")
    assert "ghp_short" in out


def test_scrub_aws_access_key_ids(agentctl):
    """AWS access key ID prefixes (AKIA permanent, ASIA STS) are redacted."""
    scrub = agentctl._scrub_api_error_message

    # Permanent key ID — AKIA + 16 uppercase alphanumeric
    key = "AKIAIOSFODNN7EXAMPLE"   # exactly AKIA + 16 chars
    out = scrub(f"InvalidClientTokenId: {key} is not valid")
    assert key not in out
    assert "[redacted]" in out

    # STS temporary key ID — ASIA + 16 chars
    key = "ASIAIOSFODNN7EXAMPL"    # ASIA + 15 chars — should NOT match (too short)
    out = scrub(f"error: {key}")
    assert key in out  # not redacted — one char short

    key = "ASIAIOSFODNN7EXAMPLE"   # ASIA + 16 chars — should match
    out = scrub(f"error: {key}")
    assert key not in out
    assert "[redacted]" in out

    # Lowercase 'asia' + 16 chars must NOT be redacted — (?-i:…) scopes the AWS branch
    # out of the outer (?i) flag so only uppercase prefixes trigger it
    text = "asiaiosfodnn7example"   # lowercase: not a real AWS key ID
    out = scrub(f"endpoint: {text}")
    assert text in out


def test_scrub_slack_tokens(agentctl):
    """Slack bot (xoxb-) and user (xoxp-) token shapes are redacted."""
    scrub = agentctl._scrub_api_error_message

    bot = "xox" + "b-1234567890-1234567890-abcdefghijklmno"
    out = scrub(f"token_revoked: {bot}")
