    base = {"ANTHROPIC_API_KEY": "real-anthropic-key", "HOME": str(tmp_path)}
    model = agentctl.model_id("sonnet")  # claude-sonnet-5
    assert not agentctl.is_gateway_model(model)
    result = base.copy()
    if agentctl.is_gateway_model(model):
        result = agentctl.gateway_env(model, result, virtual_key="vk",
                                      gateway_url="http://127.0.0.1:4000")
