def test_env_construction_gateway_custom_headers_content(agentctl, tmp_path):
    """ANTHROPIC_CUSTOM_HEADERS for a gateway spawn must carry all four
    correlation fields as newline-separated header: value pairs.

    This pins the exact format the Anthropic SDK expects so the proxy callback
    can extract run_id/agent/task/run_dir from the request metadata.
    """
    run_id = "run-corr-xyz"
    run_dir = str(tmp_path)
    result = {}
    if agentctl.is_gateway_model("deepseek/deepseek-v4-flash"):
        result = agentctl.gateway_env("deepseek/deepseek-v4-flash", {},
                                      virtual_key="vk", gateway_url="http://127.0.0.1:4000")
        task_label = "deploy fix\nwith newline"
        task_label = task_label.replace("\n", " ").replace("\r", " ")[:80]
        result["ANTHROPIC_CUSTOM_HEADERS"] = "\n".join([
            "x-agentctl-run-id: " + run_id,
            "x-agentctl-agent: coder",
            "x-agentctl-task: " + task_label,
            "x-agentctl-run-dir: " + run_dir,
        ])

    headers_raw = result["ANTHROPIC_CUSTOM_HEADERS"]
    parsed = {}
    for line in headers_raw.split("\n"):
        colon = line.find(":")
        if colon >= 0:
            parsed[line[:colon].strip()] = line[colon + 1:].strip()

    assert parsed["x-agentctl-run-id"] == run_id
    assert parsed["x-agentctl-agent"] == "coder"
    assert parsed["x-agentctl-run-dir"] == run_dir
    # Newlines in task label must be sanitized to spaces
    assert "\n" not in parsed["x-agentctl-task"]
    assert "\r" not in parsed["x-agentctl-task"]


@pytest.mark.parametrize("model_alias,expected_window", [
    ("deepseek", 1_000_000),
    ("kimi-code", 262_144),
    ("glm", 1_000_000),
])
def test_gateway_dispatch_env_carries_the_models_real_context_window(
        agentctl, tmp_path, monkeypatch, model_alias, expected_window):
    """A gateway dispatch's subprocess env carries CLAUDE_CODE_MAX_CONTEXT_TOKENS
    set to GATEWAY_MODEL_WINDOWS[model_alias], pinned to the environment the
    real launch code builds (_run_coder_session_capturing_popen, through
    _spawn_claude's own gateway_env call — not gateway_env in isolation).
    Claude Code has no declared capability entry for any gateway alias, so
    without this it assumes a 200,000-token window and refuses a longer
    prompt itself before sending it, far under every one of these models'
    real windows."""
    captured = _run_coder_session_capturing_popen(
        agentctl, tmp_path, monkeypatch, model_alias=model_alias,
        label=f"gateway-window-{model_alias}")
