def test_resolve_run_facts_reads_meta_end_to_end(agentctl, tmp_path, monkeypatch):
    # End-to-end: a real reviewer run dir with a persisted review_sha resolves; a
    # replay onto a different head is caught by the commit binding.
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    old = "a" * 40
    run_dir = T.create_run_dir("run-rev1", date="2026-06-18")
    T.write_meta(run_dir, run_id="run-rev1", agent="reviewer", task="t",
                 started_at=T.now_iso(), repo="convivy/x", worktree=str(tmp_path),
                 profile="p", model="claude-sonnet-4-6", review_sha=old)
    T.update_meta(run_dir, review_verdict="APPROVE", review_pr="7")
    facts = agentctl._resolve_run_facts("run-rev1")
    assert facts.found and facts.agent == "reviewer" and facts.review_sha == old
    # a stamp claiming the new head against this old-commit run is a stale replay
    head = "f" * 40
    s = agentctl.RP.parse(_stamp_comment(agentctl, "reviewer", head, run_id="run-rev1")["body"])
    reason = agentctl.RP.authenticate(s, facts, pr="7", review_agents=agentctl._REVIEW_AGENTS)
    assert reason and "stale replay" in reason
    # the unknown run-id resolves to nothing
    assert not agentctl._resolve_run_facts("run-ghost").found


def test_budget_gate_skips_interactive_origin_spawns(agentctl, monkeypatch):
    """ARCH-156 regression: the daily caps govern scheduled/full_monty spend
    only. An interactive co-session spawn must NOT be warned or refused against
    the SCHEDULED pool, even when that pool has crossed the hard cap (the
    2026-06-26 false soft-warn / phantom hard-trip on the operator's cartographer reviewer
    dispatch). The gate exits early on origin before reading status."""
    from types import SimpleNamespace

    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")

    def _boom(**kw):  # status() must never be consulted for an interactive spawn
        raise AssertionError("budget status read for an interactive spawn")

    monkeypatch.setattr(agentctl.B, "status", _boom)
    args = SimpleNamespace(budget_warn=None, parent=None)
    assert agentctl._budget_gate(args, {}, "convivy/x", "p") is None


def test_budget_gate_still_refuses_scheduled_over_hard_cap(agentctl, monkeypatch):
    """The flip side: a scheduled-origin spawn over the hard cap still gates."""
    from types import SimpleNamespace

    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")
    monkeypatch.setattr(agentctl.B, "status", lambda *a, **kw: {
        "pool": "overnight",
        "soft_usd": 30.0, "hard_usd": 80.0, "spent_today_usd": 184.26,
        "interactive_today_usd": 0.0, "soft_crossed": True, "hard_crossed": True,
    })
    monkeypatch.setattr(agentctl, "_budget_refuse_and_record",
                        lambda *a, **k: 3)
    args = SimpleNamespace(budget_warn=None, parent=None)
    assert agentctl._budget_gate(args, {}, "convivy/x", "p") == 3


def test_budget_gate_curation_spawn_reads_the_curation_pool(agentctl, monkeypatch):
    """ARCH-320: a curation-origin spawn gates against the curation pool, not the
    overnight pool — the whole point of the split. The gate must pass `curation`
    as the pool to status()."""
    from types import SimpleNamespace

    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "curation")
    seen = {}

    def _status(pool="overnight", **kw):
        seen["pool"] = pool
        return {"pool": pool, "soft_usd": 35.0, "hard_usd": 50.0,
                "spent_today_usd": 12.0, "interactive_today_usd": 0.0,
                "soft_crossed": False, "hard_crossed": False}

    monkeypatch.setattr(agentctl.B, "status", _status)
    args = SimpleNamespace(budget_warn=None, parent=None)
    assert agentctl._budget_gate(args, {}, "convivy/x", "p") is None
    assert seen["pool"] == "curation"


def test_budget_gate_scheduled_ignores_a_maxed_curation_pool(agentctl, monkeypatch):
    """ARCH-320 core scenario: a scheduled-origin spawn must PROCEED even when the
    curation pool is over its hard cap — the gate consults the spawn's own
    (overnight) pool only, never the curation pool. The exact 2026-07-05 stacking
    failure, inverted: the pools must not contend at the gate."""
    from types import SimpleNamespace

    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")
    seen = {}

    def _status(pool="overnight", **kw):
        seen["pool"] = pool
        crossed = pool == "curation"   # only curation is blown; overnight clean
        return {"pool": pool, "soft_usd": 30.0, "hard_usd": 80.0,
                "spent_today_usd": 99.0 if crossed else 5.0,
                "interactive_today_usd": 0.0,
                "soft_crossed": crossed, "hard_crossed": crossed}

    monkeypatch.setattr(agentctl.B, "status", _status)
    args = SimpleNamespace(budget_warn=None, parent=None)
    assert agentctl._budget_gate(args, {}, "convivy/x", "p") is None
    assert seen["pool"] == "overnight"


# --- F4: ruff format gate on publish ---------------------------------------

def _mk_wt_with_workflow(tmp_path, ci_text):
    """A worktree dir with one .github/workflows/ci.yml containing ci_text."""
    wt = tmp_path / "wt"
    (wt / ".github" / "workflows").mkdir(parents=True)
    (wt / ".github" / "workflows" / "ci.yml").write_text(ci_text)
    return wt


def test_wt_uses_ruff_format_true_when_ci_runs_it(agentctl, tmp_path):
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  test:\n    steps:\n"
                                        "      - run: ruff format --check .\n")
    assert agentctl._wt_uses_ruff_format(wt) is True


def test_wt_uses_ruff_format_false_when_ci_only_lints(agentctl, tmp_path):
    """A repo that runs `ruff check` (lint) but not `ruff format` is not gated."""
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  test:\n    steps:\n"
                                        "      - run: ruff check .\n")
    assert agentctl._wt_uses_ruff_format(wt) is False


def test_wt_uses_ruff_format_false_when_no_workflows(agentctl, tmp_path):
    wt = tmp_path / "wt"
    wt.mkdir()
    assert agentctl._wt_uses_ruff_format(wt) is False


def test_wt_uses_ruff_format_scans_yaml_extension(agentctl, tmp_path):
    """Workflow files can be .yaml as well as .yml."""
    wt = tmp_path / "wt"
    (wt / ".github" / "workflows").mkdir(parents=True)
    (wt / ".github" / "workflows" / "ci.yaml").write_text("- run: ruff format --check .\n")
    assert agentctl._wt_uses_ruff_format(wt) is True


def test_ruff_format_gate_noop_for_non_ruff_format_repo(agentctl, tmp_path, monkeypatch):
    """Gate is a no-op (returns 0) and never shells out when CI doesn't format."""
    wt = _mk_wt_with_workflow(tmp_path, "- run: ruff check .\n")

    def _boom(*a, **k):
        raise AssertionError("ruff must not be invoked for a non-format repo")

    monkeypatch.setattr(agentctl.subprocess, "run", _boom)
    assert agentctl._ruff_format_gate(wt) == 0


def test_ruff_format_gate_blocks_when_unformatted(agentctl, tmp_path, monkeypatch):
    wt = _mk_wt_with_workflow(tmp_path, "- run: ruff format --check .\n")
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: subprocess.CompletedProcess(
                            a, 1, stdout="Would reformat: x.py\n", stderr=""))
    assert agentctl._ruff_format_gate(wt) == 1


def test_ruff_format_gate_passes_when_formatted(agentctl, tmp_path, monkeypatch):
    wt = _mk_wt_with_workflow(tmp_path, "- run: ruff format --check .\n")
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: subprocess.CompletedProcess(
                            a, 0, stdout="2 files already formatted\n", stderr=""))
    assert agentctl._ruff_format_gate(wt) == 0


def test_ruff_format_gate_warns_and_proceeds_when_ruff_missing(agentctl, tmp_path,
                                                               monkeypatch, capsys):
    """A missing `ruff` must not break publish — warn, return 0, let CI enforce."""
    wt = _mk_wt_with_workflow(tmp_path, "- run: ruff format --check .\n")

    def _missing(*a, **k):
        raise FileNotFoundError("ruff")

    monkeypatch.setattr(agentctl.subprocess, "run", _missing)
    assert agentctl._ruff_format_gate(wt) == 0
    assert "not on PATH" in capsys.readouterr().err


# --- lever-C orphan-reap: kill --tree --------------------------------------

def _run(rid, parent=None, agent="bug-fixer"):
    return {"run_id": rid, "parent_run": parent, "agent": agent, "pid": 1}


def test_collect_run_descendants_finds_direct_child_and_grandchild(agentctl, monkeypatch):
    runs = [
        _run("run-root", parent=None, agent="overnight-fix-drain"),
        _run("run-child", parent="run-root"),
        _run("run-grand", parent="run-child"),
        _run("run-other", parent="run-elsewhere"),
    ]
    monkeypatch.setattr(agentctl.R, "list_runs", lambda: runs)
    got = {r["run_id"] for r in agentctl._collect_run_descendants("run-root")}
    assert got == {"run-child", "run-grand"}


