    """The canary case: root already gone from registry, child still live."""
    runs = [_run("run-bugfixer", parent="run-deadparent")]
    monkeypatch.setattr(agentctl.R, "list_runs", lambda: runs)
    got = [r["run_id"] for r in agentctl._collect_run_descendants("run-deadparent")]
    assert got == ["run-bugfixer"]


