def test_review_status_blocks_shadow_workflow_bypass_end_to_end(agentctl, monkeypatch, capsys):
    """Shadow-workflow bypass is blocked through the full cmd_review_status stack.

    All existing rollup fixtures have no detailsUrl, so _workflow_path_map is
    never exercised through the gate. This test patches _workflow_path_map and
    confirms that path-keyed collapse blocks the bypass end-to-end: both entries
    share workflowName="ci" and checkName="python", but the shadow job comes from
    a different file. Under workflowName keying the newer SUCCESS wins; with the
    path map the FAILURE survives on its own key and the gate fails.
    """
    _trust_all_stamps(agentctl, monkeypatch)
    head = "e" * 40
    real_run_id, shadow_run_id = 50001, 50002
    rollup = [
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{real_run_id}/job/1",
         "conclusion": "FAILURE", "completedAt": "2026-07-27T01:00:00Z"},
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{shadow_run_id}/job/2",
         "conclusion": "SUCCESS", "completedAt": "2026-07-27T01:00:10Z"},
    ]
    path_map = {
        real_run_id: ".github/workflows/ci.yml",
        shadow_run_id: ".github/workflows/shadow.yml",
    }
    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=rollup,
                  comments=[_stamp_comment(agentctl, "reviewer", head),
                            _stamp_comment(agentctl, "security-reviewer", head)])
    monkeypatch.setattr(agentctl, "_workflow_path_map", lambda repo, sha, env=None: path_map)
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    assert rc == 1, "shadow bypass must be blocked — path-keyed collapse keeps the real FAILURE"
    assert "CI is not green" in capsys.readouterr().out


