# --- publish is PR-aware (ARCH-347, footgun 1) -------------------------------

def _repo_on_branch(tmp_path, branch):
    """A real git repo checked out on `branch` with one commit — the worktree publish
    inspects. `.git` is a directory here (a plain repo), which publish accepts."""
    import subprocess
    wt = tmp_path / "wt"
    wt.mkdir()

    def g(*a):
        return subprocess.run(
            ["git", "-C", str(wt), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True)

    g("init", "-q", "-b", branch)
    (wt / "f.py").write_text("v = 1\n")
    g("add", ".")
    g("commit", "-qm", "c1")
    return wt


def _fake_gh(tmp_path, monkeypatch, head_ref_name):
    """A `gh` shim on PATH that answers `gh pr view … -q .headRefName` with a fixed
    branch — lets publish's PR-branch resolve run without a network or a real PR."""
    import os
    gh = tmp_path / "gh"
    gh.write_text("#!/bin/sh\necho '%s'\n" % head_ref_name)
    gh.chmod(0o755)
    monkeypatch.setenv("PATH", f"{tmp_path}:{os.environ['PATH']}")


def test_publish_refuses_when_worktree_branch_is_not_the_pr_branch(agentctl, tmp_path,
                                                                   monkeypatch, capsys):
    """The #923 footgun: a round-fix on `agent/coder-roundfix-x` while PR #923 is on
    `agent/coder-fix-y`. Publishing the former FF's a branch no PR points at and reports
    success, leaving the PR head stale. The guard must REFUSE before any push."""
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-roundfix-x")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")           # PR is on a DIFFERENT branch
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    args = types.SimpleNamespace(worktree=str(wt), run=None, repo=None, purpose=None,
                                 pr="923", dry_run=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "no PR points at" in err


def test_publish_infers_pr_from_pr_link_json_and_refuses_mismatch(agentctl, tmp_path,
                                                                  monkeypatch, capsys):
    """The REAL orchestration path: `publish --run <id>` with no explicit --pr, where the
    run was started by `spawn --pr N` (which stamps pr-link.json). publish must READ that
    link, resolve the PR branch, and refuse a divergent worktree — the explicit-`--pr`
    tests don't exercise the pr-link.json inference or the `_find_run_dir` hop."""
    import json
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-roundfix-x")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")          # PR is on a DIFFERENT branch
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    run_dir = tmp_path / "run-rf"
    run_dir.mkdir()
    (run_dir / "pr-link.json").write_text(json.dumps({"pr_number": 923,
                                                      "branch": "agent/coder-fix-y"}))
    monkeypatch.setattr(agentctl, "_find_run_dir", lambda rid: run_dir)
    monkeypatch.setattr(agentctl, "_resolve_worktree_by_run", lambda rid: wt)
    args = types.SimpleNamespace(worktree=None, run="run-rf", repo=None, purpose=None,
                                 pr=None, dry_run=False)          # PR inferred, not passed
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "923" in err


def test_publish_allows_when_worktree_branch_matches_the_pr_branch(agentctl, tmp_path,
                                                                   monkeypatch, capsys):
    """The guard must be a scalpel, not a wall: when the worktree IS on the PR branch it
    passes cleanly through to the normal push path (asserted here via --dry-run, which
    returns 0 only after the branch check has passed)."""
    import types
