def test_publish_refuses_and_pushes_nothing_when_the_refresh_fetch_fails(
        agentctl, tmp_path, monkeypatch, capsys):
    """The new refresh fetch (`git fetch --prune <push_url> ...`, right before the
    real push) must fail closed exactly like a failed mint: refuse, print why, and
    push nothing — never fall through to a push whose pre-push hook would then
    read unrefreshed, and so untrustworthy, tracking refs."""
    import contextlib
    _, wt = _publishable(tmp_path, monkeypatch, agentctl)
    nonexistent = tmp_path / "no-such-remote.git"   # deliberately never git-init'd
    push_url = f"file://{nonexistent}"
    monkeypatch.setattr(agentctl, "_publish_push_url", lambda slug: push_url)
    monkeypatch.setattr(
        agentctl.GA, "installed_app",
        lambda: agentctl.GA.InstalledApp(app_id="1234567", key_path=Path("/dev/null"),
                                         slug="test-app"))

    @contextlib.contextmanager
    def _fake_mint_token(slug, verb, **kw):
        yield "ghs_test_token_never_pushed_anywhere"
    monkeypatch.setattr(agentctl.GA, "mint_token", _fake_mint_token)

    git = _git_in(wt)
    (wt / "app.py").write_text("code\nwork\n")
    git("commit", "-aqm", "fix: work")

    real_run = subprocess.run
    calls = []

    def rec(cmd, *a, **kw):
        calls.append(cmd)
        return real_run(cmd, *a, **kw)
    monkeypatch.setattr(agentctl.subprocess, "run", rec)

    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=True, force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "refresh" in err
    push_calls = [c for c in calls if isinstance(c, list) and "push" in c]
    assert push_calls == [], "a failed refresh fetch must push nothing"


def test_publish_with_the_refresh_fetch_still_excludes_mains_history(
        agentctl, tmp_path, monkeypatch, capsys, _round3_bare):
    """Positive control. `main` is pushed to the real remote by an explicit URL,
    exactly like every `agentctl publish` since E10 S2 — which never updates any
    local tracking ref on its own (`cmd_publish`'s own comment on the post-push
    fetch it already runs for the branch it just pushed). Before this fix,
    nothing ever populates `refs/remotes/origin/main` at all: `--remotes=origin`
    has nothing to exclude, and `main`'s own base commit — which holds a marker
    the fake engine refuses — gets scanned and refused as though it were new,
    even though `feature` carries exactly one commit beyond it. The fix's
    refresh populates `refs/remotes/origin/main` for real before the hook runs,
    so the scan correctly excludes it and bounds itself to the one new commit —
    proving the fix does not OVER-correct into scanning everything either."""
    _round3_operator_config(tmp_path, monkeypatch)
    wt, push_url = _round3_setup(tmp_path, monkeypatch, agentctl, _round3_bare)

    def g(*a):
        return subprocess.run(
            ["git", "-C", str(wt), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True)

    base_sha = g("rev-parse", "main").stdout.strip()
    published = g("push", "-q", push_url, "main")
    assert published.returncode == 0, published.stderr

    (wt / "feature.py").write_text("feature\n")
    g("add", ".")
    g("commit", "-qm", "feature work")
    new_sha = g("rev-parse", "HEAD").stdout.strip()

    call_log = tmp_path / "positive-calls.log"
    monkeypatch.setenv("FAKE_ENGINE_FAIL_REF", base_sha)
    monkeypatch.setenv("FAKE_ENGINE_CALL_LOG", str(call_log))

    args = argparse.Namespace(worktree=str(wt), run=None, repo="agent-platform",
                              purpose=None, pr=None, dry_run=False, skip_checks=True,
                              force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 0, err
    lines = call_log.read_text().splitlines()
    assert lines and set(lines) == {new_sha}, lines
    remote = subprocess.run(
        ["git", "--git-dir", str(_round3_bare), "rev-parse", "feature"],
        capture_output=True, text=True)
    assert remote.returncode == 0 and remote.stdout.strip() == new_sha


def test_default_base_falls_back_to_main_when_origin_head_is_unset(agentctl):
    """`origin/HEAD` is unset on plenty of clones; abbrev-ref then yields "HEAD", which is
    not a branch. pr-open and the empty-worktree guard both read this."""
    class R:
        def __init__(self, out):
            self.stdout = out
    assert agentctl._default_base(lambda *a: R("HEAD\n")) == "main"
    assert agentctl._default_base(lambda *a: R("origin/trunk\n")) == "trunk"
    assert agentctl._default_base(lambda *a: R("\n")) == "main"


# --- session-dir (agent-platform#141) -----------------------------------------
#
# The naming bug this replaces: a cartographer co composed `co-cartographer-<HHMM>` itself,
# inferred local time by converting a UTC instant through "Mountain Time", picked
# up a DST offset Arizona does not observe, and named its handoff dir an hour
# into the future. The skill already told it to call `date`; it skipped that. So
# these pin that the NAME now comes from one code path, not from a model.


def _session_dir(agentctl, monkeypatch, tmp_path, product="cartographer", print_="path", env=None):
    monkeypatch.setattr(agentctl.T, "RUNS_ROOT", tmp_path)
    monkeypatch.delenv(agentctl.SESSION_DIR_ENV, raising=False)
    # A pytest run inside a co session inherits CLAUDE_CODE_SESSION_ID, which
    # would route these calls through the per-session pointer under the real HOME.
    monkeypatch.delenv("CLAUDE_CODE_SESSION_ID", raising=False)
    for k, v in (env or {}).items():
        monkeypatch.setenv(k, v)
    args = type("A", (), {"product": product, "print_": print_})()
    return args


def test_session_dir_creates_the_canonical_dir_and_prints_it(agentctl, monkeypatch,
                                                             tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    assert agentctl.cmd_session_dir(args) == 0
    out = capsys.readouterr().out.strip()
    d = Path(out)
    assert d.is_dir()
    assert d.parent.name == agentctl.T.platform_day()
    assert d.name.startswith("co-cartographer-")


def test_session_dir_name_uses_the_local_clock_not_a_utc_conversion(agentctl, monkeypatch,
                                                                    tmp_path, capsys):
    """The #141 regression, pinned: the HHMM in the name must match this machine's
    own local wall clock. A dir name computed from a converted UTC instant is
    exactly what produced a name an hour into the future."""
    # The clock is frozen rather than read twice: reading it again after the
    # command runs makes this fail whenever the two reads straddle a minute
    # boundary, and a spurious failure on the #141 regression pin is exactly the
    # noise that would let a real regression through.
    # NAIVE, deliberately. datetime.now() returns naive local time, and the code
    # under test calls .astimezone() on it to attach the local offset. Freezing an
    # AWARE value instead makes .astimezone() CONVERT it: on a UTC runner
    # 23:22-07:00 becomes 06:22, so the pin passed on this machine (whose zone
    # already matched the frozen offset) and failed on CI — precisely the runner
    # where it needs to catch a reintroduced regression.
    frozen = datetime(2026, 7, 18, 23, 22)

    class _Clock(datetime):
        @classmethod
        def now(cls, tz=None):
            return frozen if tz is None else frozen.astimezone(tz)

    monkeypatch.setattr(agentctl, "datetime", _Clock)
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    agentctl.cmd_session_dir(args)
    d = Path(capsys.readouterr().out.strip())
    # 23:22 MST — the exact wall-clock the #141 session rendered as 23:22 MDT
    # after converting a UTC instant through a DST-observing zone.
    assert d.name == "co-cartographer-2322"
    assert d.parent.name == "2026-07-18"


def test_session_dir_is_idempotent_when_the_env_pins_it(agentctl, monkeypatch,
                                                        tmp_path, capsys):
    """handoff-leave and a claim taken hours earlier must agree on the session's
    identity — re-deriving it from the clock would not."""
    pinned = tmp_path / "pinned-session"
    pinned.mkdir()
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={agentctl.SESSION_DIR_ENV: str(pinned)})
    assert agentctl.cmd_session_dir(args) == 0
    assert capsys.readouterr().out.strip() == str(pinned)
    # and it did NOT create a second, clock-named directory
    assert not list(tmp_path.glob("*/co-cartographer-*"))


def test_session_dir_rejects_a_pinned_path_that_is_not_a_directory(agentctl, monkeypatch,
                                                                   tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={agentctl.SESSION_DIR_ENV: str(tmp_path / "nope")})
    assert agentctl.cmd_session_dir(args) == 1


def test_two_sessions_in_the_same_minute_get_separate_dirs(agentctl, monkeypatch,
                                                           tmp_path, capsys):
    """Sharing one directory would interleave two sessions' handoffs."""
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    agentctl.cmd_session_dir(args)
    first = capsys.readouterr().out.strip()
    agentctl.cmd_session_dir(args)
    second = capsys.readouterr().out.strip()
    assert first != second
    assert Path(first).is_dir() and Path(second).is_dir()


def test_session_dir_print_id_is_date_qualified_and_unique(agentctl, monkeypatch,
                                                           tmp_path, capsys):
    """The claim owner. A bare `co-cartographer-2322` repeats daily, so it cannot identify
    a session; qualifying it with the run-dir date makes it unique and sortable."""
    args = _session_dir(agentctl, monkeypatch, tmp_path, print_="id")
    assert agentctl.cmd_session_dir(args) == 0
    sid = capsys.readouterr().out.strip()
    assert sid.startswith(f"{agentctl.T.platform_day()}/co-cartographer-")


def test_session_dir_rejects_a_product_that_is_not_a_slug(agentctl, monkeypatch,
                                                          tmp_path, capsys):
    """`product` lands in a filesystem path, so a path-traversing or shell-shaped
    value must be refused rather than sanitized into something surprising."""
    for bad in ("Bad Product", "../escape", "cartographer/../..", "", "  "):
        args = _session_dir(agentctl, monkeypatch, tmp_path, product=bad)
        assert agentctl.cmd_session_dir(args) == 2, bad


def test_one_claude_session_gets_the_same_directory_on_every_call(agentctl, monkeypatch,
                                                                  tmp_path, capsys):
    """`/handoff-leave` and `bin/co-rollover` each ask for the session's directory.
    A second call that minted another one would leave the rollover reading a
    different directory from the one the handoff was written into."""
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-agentctl-1"})
    assert agentctl.cmd_session_dir(args) == 0
    first = capsys.readouterr().out.strip()
    assert agentctl.cmd_session_dir(args) == 0
    second = capsys.readouterr().out.strip()
    assert first == second
    assert len(list(tmp_path.glob("*/co-cartographer-*"))) == 1


def test_convivy_session_dir_wins_over_a_recorded_pointer(agentctl, monkeypatch, tmp_path, capsys):
    """CONVIVY_SESSION_DIR overrides the recorded pointer in `session-dir` only. The
    ops MCP `handoff_write` tool never reads the variable, so a session that exports a
    directory other than its recorded one gets a co-rollover that looks in the exported
    directory, does not find the handoff the tool wrote, and refuses to start. This test
    pins the precedence; it does not make the two directories agree."""
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-precedence"})
    assert agentctl.cmd_session_dir(args) == 0
    recorded = capsys.readouterr().out.strip()
    explicit = tmp_path / "explicit-dir"
    explicit.mkdir()
    monkeypatch.setenv(agentctl.SESSION_DIR_ENV, str(explicit))
    assert agentctl.cmd_session_dir(args) == 0
    assert capsys.readouterr().out.strip() == str(explicit)
    assert str(explicit) != recorded


def test_a_vanished_recorded_directory_exits_1_with_the_message_on_stderr(agentctl, monkeypatch,
                                                                          tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-vanished"})
    assert agentctl.cmd_session_dir(args) == 0
    recorded = Path(capsys.readouterr().out.strip())
    recorded.rmdir()
    assert agentctl.cmd_session_dir(args) == 1
    captured = capsys.readouterr()
    assert captured.out == ""
    assert "is missing" in captured.err and str(recorded) in captured.err


@pytest.mark.parametrize("shape", ["dangling-symlink", "directory"])
def test_an_unreadable_recorded_pointer_exits_1_with_the_message_on_stderr(
        agentctl, monkeypatch, tmp_path, capsys, shape):
    """A dangling symlink used to come back as None, and a directory raised an OSError
    that nothing here caught. Both must refuse with a message on stderr."""
    home = tmp_path / "home"
    pointer = home / ".local" / "state" / "convivy" / "session-dirs" / "sess-unreadable"
    pointer.parent.mkdir(parents=True)
    if shape == "dangling-symlink":
        pointer.symlink_to(tmp_path / "nowhere")
    else:
        pointer.mkdir()
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(home), "CLAUDE_CODE_SESSION_ID": "sess-unreadable"})
    assert agentctl.cmd_session_dir(args) == 1
    captured = capsys.readouterr()
    assert captured.out == ""
    assert str(pointer) in captured.err


def test_two_claude_sessions_in_one_minute_get_separate_directories(agentctl, monkeypatch,
                                                                    tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-one"})
    assert agentctl.cmd_session_dir(args) == 0
    first = capsys.readouterr().out.strip()
    monkeypatch.setenv("CLAUDE_CODE_SESSION_ID", "sess-two")
    assert agentctl.cmd_session_dir(args) == 0
    second = capsys.readouterr().out.strip()
    assert first != second


def test_concurrent_callers_never_share_a_session_dir(agentctl, monkeypatch, tmp_path):
    """The collision loop must be atomic, not check-then-act.

    exists()-then-mkdir leaves a gap: two callers for the same product in the
    same minute both see the path free, and one dies on FileExistsError while
    the other takes a directory the first believed it owned. mkdir IS the claim.
    Single-threaded assertions cannot show this, so this drives it concurrently.
    """
    import threading

    monkeypatch.setattr(agentctl.T, "RUNS_ROOT", tmp_path)
    monkeypatch.delenv(agentctl.SESSION_DIR_ENV, raising=False)
    monkeypatch.delenv("CLAUDE_CODE_SESSION_ID", raising=False)

    # Assert on the filesystem, not on captured stdout: sys.stdout is global, so
    # redirecting it per-thread would have the threads capture each other.
    errors = []
    start = threading.Barrier(8)

    def go():
        args = type("A", (), {"product": "cartographer", "print_": "path"})()
        try:
            start.wait(timeout=5)
            agentctl.cmd_session_dir(args)
        except Exception as e:  # a raised FileExistsError is the regression
            errors.append(e)

    threads = [threading.Thread(target=go) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)

    assert not errors, errors
    made = sorted(d.name for d in (tmp_path / agentctl.T.platform_day()).iterdir())
    assert len(made) == 8, f"callers shared a directory: {made}"


# --- pr-open opens drafts by default (ARCH-364) --------------------------------

_PR_SHA = "a" * 40


def _pr_open_worktree(tmp_path):
    """A worktree shaped enough for cmd_pr_open: a .git dir and a non-empty body."""
    wt = tmp_path / "wt"
    (wt / ".git").mkdir(parents=True)
    (wt / "pr-body.md").write_text("## What\n\nA change.\n")
    return wt


def _fake_run_for_pr_open(created):
    """Stand in for every git/gh call cmd_pr_open makes, recording `gh pr create`."""
    class R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]  # strip ["git", "-C", <wt>]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return R("pr-body.md\n")
            if a[0] == "fetch":
                return R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return R(_PR_SHA + "\n")  # origin == HEAD, so ARCH-055 passes
            if a == ["remote", "get-url", "origin"]:
                return R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return R("origin/main\n")
            return R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                return R("[]\n")  # no open PR
            if cmd[1:3] == ["pr", "view"]:
                return R("", rc=1)  # no PR at all on this branch
            if cmd[1:3] == ["pr", "create"]:
                created.append(cmd)
                return R("https://github.com/convivy/agent-platform/pull/1\n")
        return R()

    return run


def test_pr_open_refuses_inside_a_dispatched_runs_own_object_redirected_env(
        agentctl, tmp_path, monkeypatch, capsys):
    """Same guard as `publish` (CQ·477): `cmd_pr_open` also calls
    `W.import_leftover_private_objects` (default `remove=True`) on the resolved
    worktree, unconditionally, with no in-use check of its own — the second
    unguarded path to the same deletion. Refuses up front, before that call or any
    git/gh subprocess, on the same signal `publish` refuses on."""
    wt = _pr_open_worktree(tmp_path)
    monkeypatch.setenv("GIT_ALTERNATE_OBJECT_DIRECTORIES", str(tmp_path / "shared"))
    calls = []
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: calls.append(("subprocess.run", a, k)))
    monkeypatch.setattr(agentctl.W, "import_leftover_private_objects",
                        lambda *a, **k: calls.append(("import_leftover_private_objects", a, k)))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err
    assert "orchestrator's step" in err
    assert calls == [], "no subprocess call and no import before the refusal"


def test_pr_open_opens_a_draft_by_default(agentctl, monkeypatch, tmp_path):
    """ARCH-364: CI runs a cheap lint lane on drafts and the full suite only on
    mark-ready. If pr-open stopped passing --draft the gating would be inert —
    every worker PR would land ready and run the full suite immediately."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"
    assert "--draft" in created[0]


def test_pr_open_ready_flag_opts_out_of_draft(agentctl, monkeypatch, tmp_path):
    """The escape hatch for a PR that needs the full suite immediately."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing", "--ready"])

    assert rc == 0
    assert "--draft" not in created[0]


def _fake_gh_only(created):
    """Like `_fake_run_for_pr_open`, but defers every `git` argv to the REAL
    `subprocess.run` — only `gh` is faked. For a test that needs pr-open's own git reads
    (fetch, rev-parse, show-ref) to run for real against a real worktree."""
    real_run = subprocess.run

    class R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            if cmd[-3:] == ["remote", "get-url", "origin"]:
                # The real `origin` in these tests is a local bare repo (so the
                # real git push/fetch plumbing has something to talk to), not a
                # GitHub remote — fake just this one lookup so pr-open's token
                # mint has a slug to scope to.
                return R("https://github.com/convivy/agent-platform.git\n")
            return real_run(cmd, **kw)
        if cmd[1:3] == ["pr", "list"]:
            return R("[]\n")
        if cmd[1:3] == ["pr", "view"]:
            return R("", rc=1)
        if cmd[1:3] == ["pr", "create"]:
            created.append(cmd)
            return R("https://github.com/convivy/agent-platform/pull/1\n")
        return R()

    return run


def test_pr_open_finds_a_commit_pushed_from_a_runs_private_object_store(
        agentctl, monkeypatch, tmp_path):
    """Caller 2 of knowledge#793 round 6's item 3: pr-open's own ARCH-055 ordering check
    (`git fetch` + comparing `origin/<branch>` against HEAD) is a real git read, run here
    for real — it must not choke on a worktree whose one commit was made through the
    run's private object store and rejoined by `import_private_objects` before this ran,
    the same way `agentctl publish`'s real push already had to."""
    import run_sandbox as RS
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/private-store-pr-open", str(wt))

    git_dir = RS.git_common_dir(wt)
    private_dir = RS.run_private_objects_dir(wt, git_dir)
    private_dir.mkdir()
    env = {**os.environ, "GIT_OBJECT_DIRECTORY": str(private_dir),
          "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git_dir / "objects")}
    (wt / "f.py").write_text("made in the private store\n")
    g("add", ".", cwd=wt, env=env)
    g("commit", "-qm", "private-store work", cwd=wt, env=env)
    RS.import_private_objects(git_dir, private_dir)
    g("push", "-q", "origin", "agent/private-store-pr-open", cwd=wt)

    # The exact path `cmd_pr_open`'s own `git rev-parse --git-path pr-body.md` resolves
    # to — a per-worktree gitdir file, same as pr-open's own docstring describes.
    body_rel = g("rev-parse", "--git-path", "pr-body.md", cwd=wt).stdout.strip()
    (wt / body_rel).resolve().write_text("## What\n\nA change.\n")

    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_gh_only(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: private store work"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"


def test_pr_open_folds_in_a_worktrees_leftover_private_store_before_reading_it(
        agentctl, monkeypatch, tmp_path):
    """Round 7 (reviewer round 6, blocking — family fix, not a reproduced defect of
    `pr-open` on its own): `pr-open`'s own checks (`rev-parse HEAD`, `show-ref
    --verify --hash` on the remote-tracking ref) are ref/string reads, never a local
    object read, so they do not independently reproduce the dead-dispatcher class the
    way `publish`'s real push does — confirmed by running this exact scenario against
    the pre-round-7 code with `gh` stubbed and a real push through the private-store
    env: it already passed. The orchestrator's brief names `pr-open` in the same
    family on the invariant this establishes regardless ("every place that reads a
    worktree a run may have used must first import its leftover private store"), so
    this pins the WIRING — `cmd_pr_open` calls `W.import_leftover_private_objects` on
    the resolved worktree before doing anything else with it — rather than a behavioral
    difference this command does not currently have."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))
    calls = []
    monkeypatch.setattr(agentctl.W, "import_leftover_private_objects",
                        lambda path: calls.append(path))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"
    assert calls == [wt.resolve()]


def test_pr_open_refuses_a_merged_pr(agentctl, monkeypatch, tmp_path):
    """A branch whose only PR is merged must be refused (issue 01KYRC81…)."""
    wt = _pr_open_worktree(tmp_path)

    # Reuse the standard git mocks from _fake_run_for_pr_open, but make gh pr
    # view return a merged PR instead of "no PR".
    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a == ["remote", "get-url", "origin"]:
                return _R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                return _R("[]\n")  # no open PR — triggers the fallback merged check
            if cmd[1:3] == ["pr", "view"]:
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/42","state":"MERGED"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 1  # refused — the branch's only PR is merged


def test_pr_open_succeeds_with_open_pr(agentctl, monkeypatch, tmp_path):
    """Idempotent: when the branch already has an open PR, return its URL (exit 0)."""
    wt = _pr_open_worktree(tmp_path)

    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a == ["remote", "get-url", "origin"]:
                return _R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                return _R('[{"url":"https://github.com/convivy/agent-platform/pr/42"}]\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0  # idempotent — found the open PR


def test_pr_open_resolves_branch_with_both_merged_and_open(agentctl, monkeypatch, tmp_path, capsys):
    """When a branch carries both a merged and an open PR, pr-open resolves to the
    open one rather than the merged one (gh pr list --state open, not gh pr view)."""
    wt = _pr_open_worktree(tmp_path)

    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a == ["remote", "get-url", "origin"]:
                return _R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                # --state open finds the open one
                return _R('[{"url":"https://github.com/convivy/agent-platform/pr/99"}]\n')
            if cmd[1:3] == ["pr", "view"]:
                # Fallback — would return the MERGED one, but is never reached
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/42","state":"MERGED"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0  # resolved to the open PR (pr/99), not the merged one (pr/42)
    out, _ = capsys.readouterr()
    assert "pr/99" in out, "stamped URL should be the open PR, not the merged one"


def test_pr_open_fallback_finds_open_pr_after_list_glitch(agentctl, monkeypatch, tmp_path, capsys):
    """When gh pr list fails transiently but an open PR exists, the gh pr view
    fallback must treat state=OPEN as idempotent (return 0), not refuse."""
    wt = _pr_open_worktree(tmp_path)

    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    called_pr_view = False

    def run(cmd, **kw):
        nonlocal called_pr_view
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a == ["remote", "get-url", "origin"]:
                return _R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                # Simulate a transient API glitch: non-zero rc and empty stdout
                return _R("", rc=1)
            if cmd[1:3] == ["pr", "view"]:
                called_pr_view = True
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/88","state":"OPEN"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert called_pr_view, "should fall back to gh pr view"
    assert rc == 0, "should idempotently return 0 for an open PR"
    out, _ = capsys.readouterr()
    assert "pr/88" in out


