# --- issue 01M3P061TZ3RDS27P0HST3QHFB: a revise round's body reaches the PR ----
# `pr-open` used to be a pure no-op when the branch already had an open PR: it
# printed the URL and returned. A worker that revises rewrites pr-body.md, but
# nothing carried that rewrite to the PR, so reviewers kept reading the first
# commit's description across every revise round.

def _pr_number_from_url(url):
    """The trailing `/pull/<n>` (or `/pr/<n>`) as an int, so a fixture call that
    only passes a URL still reports the matching `number` gh would."""
    return int(url.rsplit("/", 1)[-1]) if url else None


def _fake_run_for_pr_open_existing(edits, *, list_url=None, list_number=None,
                                    view_state=None, view_url=None, view_number=None,
                                    edit_rc=0, edit_err=""):
    """Git mocks identical to `_fake_run_for_pr_open`, but `gh pr list`/`gh pr
    view` report an already-open PR (via one or the other, matching the two
    idempotent paths in cmd_pr_open) and `gh pr edit` is recorded. `list_number`/
    `view_number` default to the URL's trailing PR number, and only need
    overriding when a test wants gh's `number` to diverge from the URL."""
    class R:
        def __init__(self, out="", err="", rc=0):
            self.stdout, self.stderr, self.returncode = out, err, rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return R("pr-body.md\n")
            if a[0] == "fetch":
                return R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return R(_PR_SHA + "\n")
            if a == ["remote", "get-url", "origin"]:
                return R("https://github.com/convivy/agent-platform.git\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return R("origin/main\n")
            return R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                if list_url:
                    n = list_number if list_number is not None else _pr_number_from_url(list_url)
                    return R(f'[{{"number":{n},"url":"{list_url}"}}]\n')
                return R("[]\n")
            if cmd[1:3] == ["pr", "view"]:
                if view_state:
                    n = view_number if view_number is not None else _pr_number_from_url(view_url)
                    return R(f'{{"number":{n},"url":"{view_url}","state":"{view_state}"}}\n')
                return R("", rc=1)
            if cmd[1:3] == ["pr", "edit"]:
                edits.append(cmd)
                return R(rc=edit_rc, err=edit_err)
        return R()

    return run


def _seed_pr_open_dispatch_run(agentctl, monkeypatch, tmp_path, wt, *, pr,
                                run_id="run-owner01"):
    """A finalized dispatch run's meta.json, wired through `RUNS_ROOT` so
    `_pr_open_edit_authorization`'s worktree reverse-lookup (no `--run` passed)
    finds it exactly as `publish`'s own worktree-only path already does.
    `pr=None` seeds a run dispatched WITHOUT `--pr`, matching a real coder's
    first (non-round-fix) dispatch."""
    import telemetry as T
    runs_root = tmp_path / "agent-runs"
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)
    monkeypatch.setattr(T, "RUNS_ROOT", runs_root)
    d = T.create_run_dir(run_id, date="2026-09-29")
    T.write_meta(d, run_id=run_id, agent="coder", task="t", started_at=T.now_iso(),
                 repo="agent-platform", worktree=str(wt), profile="p",
                 model="claude-sonnet-5", pr=pr)
    return run_id


def test_pr_open_refreshes_body_of_existing_open_pr(agentctl, monkeypatch, tmp_path, capsys):
    """A second pr-open after the worker rewrites pr-body.md runs `gh pr edit
    --body-file` with the new body and prints the URL, instead of leaving the
    first commit's stale description in place. Authorized here via the
    worktree reverse-lookup (no `--run` passed) — the run dispatched with
    `--pr 42` against this exact worktree (security review, PR #711)."""
    wt = _pr_open_worktree(tmp_path)
    (wt / "pr-body.md").write_text("## Revised\n\nThe second commit's account.\n")
    url = "https://github.com/convivy/agent-platform/pull/42"
    _seed_pr_open_dispatch_run(agentctl, monkeypatch, tmp_path, wt, pr=42)
    edits = []
    monkeypatch.setattr(agentctl.subprocess, "run",
                         _fake_run_for_pr_open_existing(edits, list_url=url))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0
    assert len(edits) == 1, "exactly one `gh pr edit`"
    assert edits[0][1:3] == ["pr", "edit"]
    assert url in edits[0]
    assert "--body-file" in edits[0]
    body_arg = edits[0][edits[0].index("--body-file") + 1]
    assert Path(body_arg).read_text() == "## Revised\n\nThe second commit's account.\n"
    out, _ = capsys.readouterr()
    assert url in out


