# --- run-dir file modes: _stamp_pr_link (PR #294 round 2) ---------------------
# PR #293 hardened most run-dir writers via T.write_owner_only. Round 2 covered
# sites that the grep-by-function inventory missed, including pr-link.json in
# _stamp_pr_link. This test proves the file lands at 0600 under umask 0000, so a
# regression back to write_text (which would produce 0666) would be caught here.


def test_stamp_pr_link_pr_link_json_at_0600(agentctl, tmp_path, monkeypatch):
    """_stamp_pr_link writes pr-link.json at mode 0600, immune to umask."""
    run_dir = tmp_path / "run-abc"
    run_dir.mkdir()
    monkeypatch.setattr(agentctl, "_find_run_dir", lambda rid: run_dir)

    class _Result:
        stdout = "42\n"

    old = os.umask(0o000)
    try:
        agentctl._stamp_pr_link(
            lambda *a, **kw: _Result(),
            "run-abc", "feat/thing", "main",
            "https://github.com/convivy/agent-platform/pull/42",
        )
    finally:
        os.umask(old)

    mode = (run_dir / "pr-link.json").stat().st_mode & 0o777
    assert mode == 0o600, f"pr-link.json: expected 0600, got {oct(mode)}"


# --- the review-post auto-ready hook itself (reviewer finding, PR #148) --------
# The five tests above drive _mark_pr_ready through `pr-ready`. The CALLING
# context in review-post was untested, so a typo in the `no_auto_ready` guard
# would silently disable the opt-out and nothing would catch it.

def _patch_review_post(agentctl, monkeypatch, tmp_path, marks):
    """Let a review-post APPROVE reach the auto-ready hook, recording whether it fires."""
    body = tmp_path / "review.md"
    body.write_text("Looks good.\n")
    _patch_view(agentctl, monkeypatch, _GREEN)          # APPROVE not blocked by CI
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda cmd, **kw: type("R", (), {
                            "returncode": 0, "stdout": "https://x/1", "stderr": ""})())
    monkeypatch.setattr(agentctl, "_mark_pr_ready",
                        lambda **kw: (marks.append(kw), (0, "marked"))[1])
    return body


def test_review_post_approve_marks_the_pr_ready(agentctl, monkeypatch, tmp_path):
    marks = []
    body = _patch_review_post(agentctl, monkeypatch, tmp_path, marks)
    rc = agentctl.main(["review-post", "--pr", "1", "--verdict", "APPROVE",
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/outfitter", "--reviewed-commit", _SHA,
                        "--run-id", "run-x"])
    assert rc == 0
    assert marks, "an APPROVE must reach the auto-ready hook"
    assert marks[0]["is_auto_ready"] is True, (
        "review-post's call must identify itself as the auto-ready path, so "
        "`_mark_pr_ready` honors a `hold` label rather than treating this like "
        "the direct `pr-ready` override")


