# --- the Library's review record: written before the PR ever sees a comment ---
# (issue_01M3830J6EKZ394Q8AVYRQGN40, ARCH-193 phase 2 continued)

def _review_post_body(tmp_path, text="Looks good. CI green.\n"):
    body = tmp_path / "review.md"
    body.write_text(text)
    return body


def _no_gh_comment(agentctl, monkeypatch, posted):
    """`gh pr comment` must never run — the caller is asserting a refused write."""
    def no_post(cmd, **kw):
        posted.append(cmd)
        raise AssertionError("gh pr comment must NOT run when the Library write fails")
    monkeypatch.setattr(agentctl.subprocess, "run", no_post)


def test_review_post_writes_the_library_record_before_the_pr_comment(
        agentctl, monkeypatch, tmp_path):
    body = _review_post_body(tmp_path)
    _patch_view(agentctl, monkeypatch, _GREEN)
    calls = []
    import issue_client

    def fake_post_record(fields, **kw):
        calls.append(("record", fields))
        return {"status": "ok", "record": {"id": "rec_1"}}
    monkeypatch.setattr(issue_client, "post_review_record", fake_post_record)

    def fake_run(cmd, **kw):
        if cmd[:3] == ["gh", "pr", "comment"]:
            calls.append(("comment", None))
        return type("R", (), {"returncode": 0, "stdout": "https://x/1", "stderr": ""})()
    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)

    rc = agentctl.main(["review-post", "--pr", "1", "--verdict", "APPROVE",
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/outfitter", "--reviewed-commit", _SHA,
                        "--run-id", "run-x", "--no-auto-ready"])
    assert rc == 0
    assert [kind for kind, _ in calls] == ["record", "comment"], (
        "the Library record must be written before the PR comment is posted")
    sent = calls[0][1]
    assert sent["repo_identity"] == "github:convivy/outfitter"
    assert sent["reviewed_ref"] == _SHA
    assert sent["role"] == "reviewer"
    assert sent["verdict"] == "APPROVE"
    assert sent["prose"] == "Looks good. CI green."
    assert sent["pr"] == 1
    assert sent["run_id"] == "run-x"
    assert sent["paths"] == [] and sent["doc_ids"] == [] and sent["item_ids"] == []


@pytest.mark.parametrize("stub_status,stub_error", [
    ("error:ConnectionRefusedError", "Connection refused"),
    ("error:422", "at most 20 paths entries"),
])
def test_review_post_library_write_failure_posts_nothing_to_the_pr(
        agentctl, monkeypatch, tmp_path, capsys, stub_status, stub_error):
    """A Library write that fails — unreachable, or a 4xx refusal — must not let
    a stamp reach the PR: a review with no durable record must not read as
    posted."""
    body = _review_post_body(tmp_path)
    _patch_view(agentctl, monkeypatch, _GREEN)
    import issue_client
    monkeypatch.setattr(
        issue_client, "post_review_record",
        lambda *a, **kw: {"status": stub_status, "error": stub_error, "record": {}})
    posted = []
    _no_gh_comment(agentctl, monkeypatch, posted)

    rc = agentctl.main(["review-post", "--pr", "1", "--verdict", "APPROVE",
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/outfitter", "--reviewed-commit", _SHA,
                        "--run-id", "run-x"])
