def test_arch397_library_refusal_rescues_the_review_and_names_the_real_cause(
        agentctl, tmp_path, monkeypatch, capsys):
    """A review-post call refused by the Library must not read as "the PR head
    moved" — the wrong cause here — and its review text must land in the
    durable rescue store (unposted-review.md + the digest index), not only in
    a re-post instruction pointing at a worktree that ARCH-344 has by then
    reaped (issue_01M3830J6EKZ394Q8AVYRQGN40 round 2)."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl, "_gh_pr_json", lambda *a, **k: {"comments": []})  # no stamp
    monkeypatch.setattr(agentctl, "RESCUE_DIGEST_INDEX", tmp_path / "rescued-review-digests")
    rd, wt = _mk_review_run_dir(tmp_path)  # pr="5", repo="agent-platform"

    # The reviewer's own transcript shows it DID call review-post.
    with (rd / "transcript.jsonl").open("a") as f:
        f.write(json.dumps({
            "type": "assistant",
            "message": {"content": [{"type": "tool_use", "id": "tu1", "name": "Bash",
                                     "input": {"command":
                                         "agentctl review-post --pr 5 --verdict "
                                         "REQUEST_CHANGES --agent reviewer "
                                         "--body-file review.md --repo agent-platform"}}]},
        }) + "\n")

    # The run's finished review, recovered the way `_rescue_unposted_review_inner`
    # recovers it — from the run's own final "result" record.
    review_text = "## Review\nFinding: the guard on line 40 is unreachable.\n"
    with (rd / "detach.out.log").open("a") as f:
        f.write(json.dumps({"type": "result", "result": review_text}) + "\n")

    # `review-post` itself already wrote this, at the moment the Library refused.
    (rd / agentctl._LIBRARY_REFUSAL_MARKER_FILENAME).write_text(
        json.dumps({"status": "error:422", "error": "at most 20 paths entries"}))

    assert _finalize(agentctl, rd, wt) == "errored"
    err = capsys.readouterr().err
    assert "the Library refused the review record" in err
    assert "error:422" in err and "at most 20 paths entries" in err
    assert "PR head moved" not in err

    rescued = rd / "unposted-review.md"
    assert rescued.exists(), "the finished review must survive the worktree reap"
    assert review_text.strip() in rescued.read_text()
    assert agentctl.RESCUED_REVIEW_MARKER in rescued.read_text()

    digest_index = agentctl.RESCUE_DIGEST_INDEX
    assert digest_index.exists()
    assert "5\t" in digest_index.read_text()


def test_finalize_run_library_refusal_message_gives_a_working_repost_command(
        agentctl, tmp_path, monkeypatch, capsys):
    """The library-refusal cause is the one case where re-posting the SAME run's
    review is correct (issue_01M3830J6EKZ394Q8AVYRQGN40 round 1, reviewer PR #722):
    `run_facts` resolves an ended run's meta.json directly, so this run's own
    `--reviewed-commit`/`--run-id` still authenticate outside its process. The
    message must give that command rather than "Re-dispatch" / "do not post it
    yourself", which is right for the OTHER three causes but wrong for this one."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl, "_gh_pr_json", lambda *a, **k: {"comments": []})
    monkeypatch.setattr(agentctl, "RESCUE_DIGEST_INDEX", tmp_path / "rescued-review-digests")
    rd, wt = _mk_review_run_dir(tmp_path)  # pr="5", repo="agent-platform", review_sha="abc123"

    with (rd / "transcript.jsonl").open("a") as f:
        f.write(json.dumps({
            "type": "assistant",
            "message": {"content": [{"type": "tool_use", "id": "tu1", "name": "Bash",
                                     "input": {"command":
                                         "agentctl review-post --pr 5 --verdict "
                                         "REQUEST_CHANGES --agent reviewer "
                                         "--body-file review.md --repo agent-platform"}}]},
        }) + "\n")
    with (rd / "detach.out.log").open("a") as f:
        f.write(json.dumps({"type": "result", "result": "## Review\nFinding.\n"}) + "\n")
    (rd / agentctl._LIBRARY_REFUSAL_MARKER_FILENAME).write_text(
        json.dumps({"status": "error:422", "error": "at most 20 paths entries"}))

    assert _finalize(agentctl, rd, wt, run_id="run-test") == "errored"
    err = capsys.readouterr().err
    assert "--reviewed-commit abc123" in err
    assert "--run-id run-test" in err
    assert "--allow-rescued" in err
    assert "unposted-review.md" in err
    assert "Re-dispatch" not in err
    assert "do not post it yourself" not in err


