def test_committed_not_pushed_gate_closes_after_reset_to_started_head(
        agentctl, tmp_path, monkeypatch):
    """A run that committed and then reset back to started_head must not be
    flagged — started_head..HEAD is empty, closing the same gate the no-commits
    case closes (reviewer suggestion, PR #568 round 1)."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_worker_run_dir(tmp_path, pre_existing_commits=1, with_commit=True,
                                with_remote_configured=True)
    started_head = (rd / "started_head.txt").read_text().strip()
    subprocess.run(["git", "reset", "--hard", started_head], cwd=str(wt), check=True,
                   capture_output=True)
    assert _finalize(agentctl, rd, wt) == "completed"


def test_dry_run_never_reaches_the_committed_not_pushed_check(
        agentctl, tmp_path, monkeypatch):
    """A `spawn --dry-run` writes a stub transcript and never touches the
    worktree — but the worktree it names is the real repo, which can carry its
    own commit history untouched by the dry run. started_head.txt here is
    stale on purpose (it points at a commit BEFORE the pre-existing history),
    so if the check ran it would count that history as "committed by this
    run" and mark committed_local_only (no remote). `dry_run=True` must skip
    the check outright and leave the run `completed`."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_worker_run_dir(tmp_path, pre_existing_commits=1)
    stale_base = (rd / "started_head.txt").read_text().strip()
    # A second pre-existing commit, landing AFTER the started_head snapshot —
    # exactly what the real dry-run stub never re-snapshots for.
    (wt / "pre1.py").write_text("# pre-existing 1\n")
    subprocess.run(["git", "add", "pre1.py"], cwd=str(wt), check=True, capture_output=True)
    subprocess.run(["git", "commit", "-m", "pre-existing 1"],
                   cwd=str(wt), check=True, capture_output=True)
    assert agentctl._commits_since(wt, stale_base) == 1, \
        "the check itself must see a nonzero count here, or this test proves nothing"
    assert _finalize(agentctl, rd, wt, dry_run=True) == "completed"


def test_committed_not_pushed_publish_promotes_to_completed(agentctl, tmp_path,
                                                             monkeypatch):
    """Production-representative: remote configured, commits present, not yet pushed.

    Every successful worker run is in this state at finalize time — the orchestrator
    has not yet called agentctl publish. _finalize_run records committed_not_pushed
    (transient, correct at that instant); agentctl publish --run <id> pushes the
    commits and promotes the outcome to completed. The signal stays alarming only for
    runs where publish is never called.

    The git setup mirrors production: a bare origin with main pushed (so origin/main
    exists as the base), the worker on a feature branch with one commit, the feature
    branch NOT on origin yet.
    """
    import types
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)

    # Build the run dir and a production-representative worktree by hand so the git
    # layout is unambiguous: base on main, worker commit on a feature branch, remote
    # configured but feature branch not pushed.
    rd = tmp_path / "run-test"
    rd.mkdir()
    (rd / "prompts").mkdir()
    (rd / "transcript.jsonl").touch()
    (rd / "tool_calls.jsonl").touch()
    (rd / "started_dirty.txt").write_text("")
    wt = tmp_path / "wt"
    wt.mkdir()
    (rd / "meta.json").write_text(json.dumps({
        "run_id": "run-test", "agent": "bug-fixer", "task": "fix",
        "started_at": "2026-07-28T00:00:00Z", "ended_at": None, "parent_run": None,
        "repo": "styleguide", "worktree": str(wt), "profile": "agent-platform/daytime",
        "model": "claude-sonnet", "pid": 99999, "billing_source": "unknown",
    }))

    cfg = ["-c", "user.email=bot@t", "-c", "user.name=Bot"]
    def g(*a):
        subprocess.run(["git", "-C", str(wt), *cfg, *a], check=True, capture_output=True)

    g("init", "-q", "-b", "main")
    (wt / "base.py").write_text("v = 1\n")
    g("add", "base.py")
    g("commit", "-qm", "base")
    # started_head.txt — the spawn-time snapshot (bin/agentctl ~line 3614) — is
    # HEAD right here, BEFORE the worker's own commit below.
    head = subprocess.run(["git", "-C", str(wt), "rev-parse", "HEAD"],
                          check=True, capture_output=True, text=True)
    (rd / "started_head.txt").write_text(head.stdout.strip() + "\n")

    g("checkout", "-qb", "agent/fix-123")
    (wt / "fix.py").write_text("# fix\n")
    g("add", "fix.py")
    g("commit", "-qm", "fix")  # worker commit — on feature branch, not yet pushed

    bare = tmp_path / "bare.git"
    subprocess.run(["git", "init", "--bare", str(bare)], check=True, capture_output=True)
    g("remote", "add", "origin", str(bare))
    g("push", "-u", "origin", "main")  # push main so origin/main is the base, not the feature branch

    # At finalize time — the exact state of every production run before publish:
    # remote configured, feature branch has a commit, not yet on origin.
    assert _finalize(agentctl, rd, wt) == "committed_not_pushed"

    # agentctl publish --run run-test pushes the feature branch and promotes the outcome.
    monkeypatch.setattr(agentctl, "_find_run_dir", lambda rid: rd)
    monkeypatch.setattr(agentctl, "_resolve_worktree_by_run", lambda rid: wt)
    _stub_publish_push(agentctl, monkeypatch, bare)
    args = types.SimpleNamespace(
        worktree=None, run="run-test", repo=None, purpose=None, pr=None, dry_run=False
    )
    rc = agentctl.cmd_publish(args)
    assert rc == 0

    # After publish, the outcome is promoted to completed — the non-alarming result
    # for a normal successful run.
    outcome = json.loads((rd / "outcome.json").read_text())
    assert outcome["exit_status"] == "completed"


def test_committed_not_pushed_publish_promotes_via_repo_purpose(agentctl, tmp_path,
                                                                  monkeypatch):
    """Canonical orchestrator path: publish via --repo/--purpose (no --run) —
    `_promote_if_committed_not_pushed`'s own docstring names this the
    canonical --repo/--purpose publish path, reached via the worktree
    reverse-lookup when run_id is absent. Before the fix, that function was a
    no-op when run_id was absent, so the outcome stayed committed_not_pushed on
    every production push through this path. The reverse worktree lookup must find
    the run and promote it.
    """
    import types
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)

    # Build a fake RUNS_ROOT with one date dir containing the run.
    runs_root = tmp_path / "agent-runs"
    date_dir = runs_root / "2026-07-28"
    date_dir.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)

    wt = tmp_path / "worktree" / "styleguide.agent--fix-123"
    wt.mkdir(parents=True)

    rd = date_dir / "run-abc123"
    rd.mkdir()
    (rd / "prompts").mkdir()
    (rd / "transcript.jsonl").touch()
    (rd / "tool_calls.jsonl").touch()
    (rd / "started_dirty.txt").write_text("")
    (rd / "meta.json").write_text(json.dumps({
        "run_id": "run-abc123", "agent": "bug-fixer", "task": "fix-123",
        "started_at": "2026-07-28T00:00:00Z", "ended_at": None, "parent_run": None,
        "repo": "styleguide", "worktree": str(wt), "profile": "agent-platform/daytime",
        "model": "claude-sonnet", "pid": 99999, "billing_source": "unknown",
    }))

    cfg = ["-c", "user.email=bot@t", "-c", "user.name=Bot"]
    def g(*a):
        subprocess.run(["git", "-C", str(wt), *cfg, *a], check=True, capture_output=True)

    g("init", "-q", "-b", "main")
    (wt / "base.py").write_text("v = 1\n")
    g("add", "base.py")
    g("commit", "-qm", "base")
    # started_head.txt — the spawn-time snapshot (bin/agentctl ~line 3614) — is
    # HEAD right here, BEFORE the worker's own commit below.
    head = subprocess.run(["git", "-C", str(wt), "rev-parse", "HEAD"],
                          check=True, capture_output=True, text=True)
    (rd / "started_head.txt").write_text(head.stdout.strip() + "\n")

    g("checkout", "-qb", "agent/fix-123")
    (wt / "fix.py").write_text("# fix\n")
    g("add", "fix.py")
    g("commit", "-qm", "fix")

    bare = tmp_path / "bare.git"
    subprocess.run(["git", "init", "--bare", str(bare)], check=True, capture_output=True)
    g("remote", "add", "origin", str(bare))
    g("push", "-u", "origin", "main")

    # Stamp committed_not_pushed — the state finalize would have written.
    assert _finalize(agentctl, rd, wt) == "committed_not_pushed"

    # Publish via --repo/--purpose: no --run argument.
    monkeypatch.setattr(agentctl.W, "desired_path", lambda repo, purpose: wt)
    _stub_publish_push(agentctl, monkeypatch, bare)
    args = types.SimpleNamespace(
        worktree=None, run=None, repo="styleguide", purpose="agent/fix-123",
        pr=None, dry_run=False,
    )
    rc = agentctl.cmd_publish(args)
    assert rc == 0

    # The worktree reverse-lookup must have found the run and promoted it.
    outcome = json.loads((rd / "outcome.json").read_text())
    assert outcome["exit_status"] == "completed"


def test_worktree_lookup_prefers_the_newer_run_not_the_higher_run_id(tmp_path,
                                                                    agentctl,
                                                                    monkeypatch):
    """Two runs, same worktree, same day — the lookup must return the NEWER one.

    A run id is `run-{8 random hex}`, so ordering run dirs by name orders them by
    random hex. Getting this wrong inverts the signal the whole mechanism exists
    to produce: every worker run is `committed_not_pushed` at finalize, so both
    candidates are in that state, and promoting the OLDER one clears the genuine
    alarm on a run whose work was never pushed while the run that actually
    published stays flagged. The alarming run is the safe one and the quiet one
    lost work — exactly backwards.

    The names here are chosen so that name-order and time-order DISAGREE:
    `run-ffffffff` is the older run but sorts last; `run-00000000` is the newer
    run but sorts first. Under the old `sorted(..., reverse=True)` this returns
    `run-ffffffff`, the wrong one. Found by security-reviewer on PR #274.
    """
    runs_root = tmp_path / "agent-runs"
    date_dir = runs_root / "2026-07-28"
    date_dir.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)

    wt = tmp_path / "worktree" / "styleguide.shared"
    wt.mkdir(parents=True)

    def _run(name: str, started: str):
        rd = date_dir / name
        rd.mkdir()
        (rd / "meta.json").write_text(json.dumps({
            "run_id": name, "agent": "coder", "worktree": str(wt),
            "started_at": started,
        }))
        return rd

    older = _run("run-ffffffff", "2026-07-28T09:00:00Z")   # sorts FIRST by name
    newer = _run("run-00000000", "2026-07-28T17:00:00Z")   # sorts LAST by name

    found = agentctl._find_run_by_worktree(wt)
    assert found == newer, (
        f"lookup returned {found.name if found else None}; ordering by run-id name "
        f"instead of started_at would return {older.name} and invert the signal")


def test_worktree_lookup_sorts_a_missing_started_at_last(tmp_path, agentctl,
                                                         monkeypatch):
    """A candidate with no readable `started_at` is still a legitimate match, so
    it is kept rather than dropped — but a run with a real timestamp is preferred.
    Its name is chosen to sort ahead, so name-order alone would pick it."""
    runs_root = tmp_path / "agent-runs"
    date_dir = runs_root / "2026-07-28"
    date_dir.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)

    wt = tmp_path / "worktree" / "styleguide.shared"
    wt.mkdir(parents=True)

    nostamp = date_dir / "run-zzzzzzzz"
    nostamp.mkdir()
    (nostamp / "meta.json").write_text(json.dumps(
        {"run_id": "run-zzzzzzzz", "worktree": str(wt)}))   # no started_at

    stamped = date_dir / "run-11111111"
    stamped.mkdir()
    (stamped / "meta.json").write_text(json.dumps(
        {"run_id": "run-11111111", "worktree": str(wt),
         "started_at": "2026-07-28T10:00:00Z"}))

    assert agentctl._find_run_by_worktree(wt) == stamped

    # And with ONLY the unstamped candidate present it is still found, not dropped.
    stamped_meta = stamped / "meta.json"
    stamped_meta.unlink()
    assert agentctl._find_run_by_worktree(wt) == nostamp


# --- PR #268: mergeability gate, SHA-match at both _approve_blocked_by_ci
# sites, and two fail-closed stamp paths in cmd_review_post.
#
# _RED, _GREEN, _SHA, _patch_view, _trust_all_stamps, _stamp_comment, and _ns
# are all defined earlier in this file and are module-level names.


# --- Fix 1: mergeability gate in cmd_review_status ---------------------------
#
# Three cases plus the important UNKNOWN case. The reason text must be distinct
# from reviewer/CI failures so a human can tell the three failure kinds apart.


def _fake_pr_view_mergeable(agentctl, monkeypatch, *, head, comments, rollup,
                            mergeable, merge_state_status, base_ref="main"):
    """Patch _gh_pr_json to return a canned PR view that includes mergeability fields."""
    def fake(pr, fields, repo=None, env=None):
        return {
            "headRefOid": head,
            "comments": comments,
            "statusCheckRollup": rollup,
            "state": "OPEN",
            "isDraft": False,
            "mergeable": mergeable,
            "mergeStateStatus": merge_state_status,
            "baseRefName": base_ref,
        }
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)


def test_review_status_fails_on_conflicting_mergeability(agentctl, monkeypatch, capsys):
    """CONFLICTING fails the gate with a reason distinct from reviewer/CI failures:
    'does not merge cleanly'. The reason must name the base branch so the developer
    knows what to merge."""
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view_mergeable(
        agentctl, monkeypatch, head=head,
        comments=[_stamp_comment(agentctl, "reviewer", head),
                  _stamp_comment(agentctl, "security-reviewer", head)],
        rollup=[{"conclusion": "SUCCESS"}],
        mergeable="CONFLICTING", merge_state_status="DIRTY", base_ref="main",
    )
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1 and "FAIL" in out
    assert "does not merge cleanly" in out
    assert "main" in out, "must name the base branch in the failure reason"


def test_review_status_fails_on_dirty_merge_state_status(agentctl, monkeypatch, capsys):
    """mergeStateStatus DIRTY also fails, even when mergeable is not CONFLICTING.
    The check covers both fields so a dirty tree cannot sneak through."""
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view_mergeable(
        agentctl, monkeypatch, head=head,
        comments=[_stamp_comment(agentctl, "reviewer", head),
                  _stamp_comment(agentctl, "security-reviewer", head)],
        rollup=[{"conclusion": "SUCCESS"}],
        mergeable="MERGEABLE", merge_state_status="DIRTY", base_ref="main",
    )
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1
    assert "does not merge cleanly" in out


def test_review_status_passes_with_mergeable_flag_approvals_and_green_ci(
        agentctl, monkeypatch, capsys):
    """MERGEABLE + two approvals at head + green CI still passes. The mergeability
    check must not make the gate unusable for the normal case."""
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view_mergeable(
        agentctl, monkeypatch, head=head,
        comments=[_stamp_comment(agentctl, "reviewer", head),
                  _stamp_comment(agentctl, "security-reviewer", head)],
        rollup=[{"conclusion": "SUCCESS"}],
        mergeable="MERGEABLE", merge_state_status="CLEAN", base_ref="main",
    )
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    assert rc == 0 and "PASS" in capsys.readouterr().out


def test_review_status_treats_unknown_mergeability_as_pending_not_pass(
        agentctl, monkeypatch, capsys):
    """UNKNOWN is treated as PENDING, not as a pass.

    GitHub returns UNKNOWN for a window after any push to the base branch —
    exactly the window after a batch of merges, when conflicts actually appear.
    A future refactor that 'simplifies' UNKNOWN to truthy would reintroduce the
    silent-conflict bug. Pinned to catch that regression at the source."""
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view_mergeable(
        agentctl, monkeypatch, head=head,
        comments=[_stamp_comment(agentctl, "reviewer", head),
                  _stamp_comment(agentctl, "security-reviewer", head)],
        rollup=[{"conclusion": "SUCCESS"}],
        mergeable="UNKNOWN", merge_state_status="UNKNOWN", base_ref="main",
    )
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1 and "FAIL" in out
    assert "mergeability is UNKNOWN" in out, "must name the UNKNOWN state explicitly"
    assert "— PASS" not in out, "UNKNOWN must never produce a passing verdict line"


def test_review_status_treats_null_mergeable_as_unknown_not_pass(
        agentctl, monkeypatch, capsys):
    """A null or absent `mergeable` field defaults to UNKNOWN and is treated as PENDING.

    The old idiom `(view.get("mergeable") or "").upper()` turns a null or missing
    field into the empty string, which matches none of the blocklist values and silently
    passes the gate — the failure class this PR exists to close. The fix defaults to
    "UNKNOWN" so the absent field routes to the existing UNKNOWN → PENDING branch."""
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view_mergeable(
        agentctl, monkeypatch, head=head,
        comments=[_stamp_comment(agentctl, "reviewer", head),
                  _stamp_comment(agentctl, "security-reviewer", head)],
        rollup=[{"conclusion": "SUCCESS"}],
        mergeable=None, merge_state_status="CLEAN", base_ref="main",
    )
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1 and "FAIL" in out
    assert "mergeability is UNKNOWN" in out
    assert "— PASS" not in out, "a null mergeable must never produce a passing verdict"


# --- Fix: MERGED / CLOSED terminal states bypass the mergeability branch ------
#
# GitHub returns mergeable: UNKNOWN and mergeStateStatus: UNKNOWN for both merged
# and closed PRs — the same values it returns during the transient post-push
# computation window. Without a state check, review-status reports "mergeability
# is UNKNOWN" and prescribes a retry that can never succeed.


def _fake_merged_pr_view(agentctl, monkeypatch, *, head, merged_at):
    """Patch _gh_pr_json to return a canned view for an already-merged PR."""
    def fake(pr, fields, repo=None, env=None):
        return {
            "headRefOid": head,
            "comments": [],
            "statusCheckRollup": [],
            "state": "MERGED",
            "isDraft": False,
            "mergedAt": merged_at,
            "mergeable": "UNKNOWN",
            "mergeStateStatus": "UNKNOWN",
            "baseRefName": "main",
        }
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)


def test_review_status_reports_merged_pr_as_terminal_not_unknown(
        agentctl, monkeypatch, capsys):
    """A merged PR exits 0 with a MERGED line and never shows 'mergeability is UNKNOWN'.

    GitHub returns mergeable/mergeStateStatus UNKNOWN for merged PRs, identical to
    the transient post-push computation state. Before this fix, review-status
    reported FAIL with a 'GitHub is still computing' message and a retry prescription
    that never resolves — it misled the steward into watching two already-merged PRs
    for fifty minutes before GitHub's refusal to close them revealed the mistake."""
    head = "a" * 40
    merged_at = "2026-07-28T20:23:52Z"
    _fake_merged_pr_view(agentctl, monkeypatch, head=head, merged_at=merged_at)
    rc = agentctl.cmd_review_status(_ns(pr="1080", repo="convivy/cartographer", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 0
    assert "MERGED" in out
    assert merged_at in out
    assert "UNKNOWN" not in out
    assert "nothing to gate" in out


def test_review_status_merged_pr_without_merged_at_falls_back_gracefully(
        agentctl, monkeypatch, capsys):
    """A merged PR whose mergedAt field is null still exits 0 with a MERGED line."""
    head = "b" * 40
    _fake_merged_pr_view(agentctl, monkeypatch, head=head, merged_at=None)
    rc = agentctl.cmd_review_status(_ns(pr="42", repo="convivy/cartographer", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 0
    assert "MERGED" in out
    assert "unknown time" in out
    assert "UNKNOWN" not in out
    assert "nothing to gate" in out


def test_review_status_reports_closed_unmerged_pr_as_terminal_fail(
        agentctl, monkeypatch, capsys):
    """A closed-without-merging PR exits 1 with a CLOSED line, no UNKNOWN message."""
    head = "c" * 40
    def fake(pr, fields, repo=None, env=None):
        return {
            "headRefOid": head,
            "comments": [],
            "statusCheckRollup": [],
            "state": "CLOSED",
            "isDraft": False,
            "mergedAt": None,
            "mergeable": "UNKNOWN",
            "mergeStateStatus": "UNKNOWN",
            "baseRefName": "main",
        }
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)
    rc = agentctl.cmd_review_status(_ns(pr="999", repo="convivy/cartographer", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1
    assert "CLOSED" in out
    assert "UNKNOWN" not in out
    assert "nothing to gate" in out


# --- Fix 2: _sha_match at both _approve_blocked_by_ci comparison sites -------
#
# Both the pre-loop check and the in-loop re-check were using `!=` instead of
# _sha_match. An abbreviated reviewed_commit (e.g. from AGENTCTL_REVIEW_SHA)
# would always compare unequal to the 40-char headRefOid and fire "head moved".
# _RED, _GREEN, _SHA, and _patch_view are defined at the top of the ARCH-345 block.


def test_approve_not_blocked_when_reviewed_commit_is_abbreviated_prefix(
        agentctl, monkeypatch):
    """Fix 2, site 1 (pre-loop check): an abbreviated reviewed_commit that is a valid
    prefix of the PR head must not produce a 'head moved' block."""
    _patch_view(agentctl, monkeypatch, _GREEN, head=_SHA)
    result = agentctl._approve_blocked_by_ci(pr="1", repo="r/r",
                                             reviewed_commit=_SHA[:9])
    assert result is None, (
        f"abbreviated prefix {_SHA[:9]!r} of the PR head must not block as 'head moved'")


def test_approve_not_blocked_in_ci_wait_loop_with_abbreviated_reviewed_commit(
        agentctl, monkeypatch):
    """Fix 2, site 2 (in-loop re-check): the live_head re-check inside the CI-wait
    loop also uses _sha_match, so an abbreviated reviewed_commit does not block
    after waiting for CI to settle."""
    views = [
        {"statusCheckRollup": [{"name": "tests", "status": "IN_PROGRESS"}],
         "headRefOid": _SHA},
        {"statusCheckRollup": [{"name": "tests", "conclusion": "SUCCESS"}],
         "headRefOid": _SHA},
    ]
    calls = []

    def fake(pr, fields, repo=None, env=None):
        calls.append(1)
        return views[min(len(calls) - 1, 1)]

    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)
    monkeypatch.setattr(agentctl.time, "sleep", lambda _: None)
    monkeypatch.setattr(agentctl, "_ci_settled_rest", lambda repo, sha, env=None: True)
    result = agentctl._approve_blocked_by_ci(pr="1", repo="r/r",
                                             reviewed_commit=_SHA[:9], wait_secs=60)
    assert result is None, (
        "abbreviated prefix must not block the 'head moved' re-check inside the CI-wait loop")


def test_approve_blocked_when_reviewed_commit_is_genuinely_different_sha(
        agentctl, monkeypatch):
    """Fix 2 guard: a reviewed_commit that is NOT a prefix of the head still blocks.
    The fix must not weaken the head-movement check — only prefix matches are allowed."""
    different_head = "9" * 40  # completely different from _SHA
    _patch_view(agentctl, monkeypatch, _GREEN, head=different_head)
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r",
                                                reviewed_commit=_SHA)
    assert code == agentctl.CI_BLOCK_RED
    assert "head moved" in why


def test_approve_blocked_in_ci_wait_loop_when_head_genuinely_moves(
        agentctl, monkeypatch):
    """Fix 2 guard, site 2 (in-loop re-check): a genuinely different live_head SHA
    still blocks during the CI-wait loop.

    Site 1 (pre-loop) is covered by the test above; this test pins site 2 by forcing
    a loop iteration — IN_PROGRESS on call 1, then SUCCESS with a different head on
    call 2. The block must fire on the second iteration so both sites are pinned in
    both directions (abbreviated-prefix allowed, genuinely-different blocked)."""
    different_head = "9" * 40  # completely different from _SHA
    views = [
        {"statusCheckRollup": [{"name": "tests", "status": "IN_PROGRESS"}],
         "headRefOid": _SHA},
        {"statusCheckRollup": [{"name": "tests", "conclusion": "SUCCESS"}],
         "headRefOid": different_head},  # head moved while CI was running
    ]
    calls = []

    def fake(pr, fields, repo=None, env=None):
        calls.append(1)
        return views[min(len(calls) - 1, 1)]

    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)
    monkeypatch.setattr(agentctl.time, "sleep", lambda _: None)
    monkeypatch.setattr(agentctl, "_ci_settled_rest", lambda repo, sha, env=None: True)
    result = agentctl._approve_blocked_by_ci(pr="1", repo="r/r",
                                             reviewed_commit=_SHA, wait_secs=60)
    assert result is not None, (
        "a genuinely different live_head SHA must block even inside the CI-wait loop")
    code, why = result
    assert code == agentctl.CI_BLOCK_RED
    assert "head moved" in why


# --- Fix 3: two fail-closed stamp paths in cmd_review_post -------------------
#
# Gap 1: empty repo_full with abbreviated SHA → fail closed before normalization.
# Gap 2: returncode 0 with non-40-char output → fail closed via the new else branch.
# Both assert the abbreviated SHA does NOT reach the stamp.


def test_review_post_abbreviated_sha_fails_closed_when_repo_unknown(
        agentctl, tmp_path, monkeypatch, capsys):
    """Fix 3, gap 1: when no repo slug is available (args.repo=None and the git remote
    is absent), an abbreviated SHA fails closed rather than falling through and stamping
    the abbreviation. An abbreviated SHA in a stamp enables collision-assisted prefix
    forgery via _sha_match's prefix comparison."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    abbrev = "abc1234de"  # 9 chars, valid hex, < 40

    monkeypatch.setattr(agentctl, "_gh_repo_slug", lambda: "")
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)

    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev, run_id="r", repo=None, dry_run=True))
    captured = capsys.readouterr()
    assert rc != 0, "must fail closed when repo is unknown and SHA is abbreviated"
    assert agentctl.RP.parse(captured.out) is None, (
        "abbreviated SHA must not reach the stamp when repo is unknown")
    assert "cannot normalize" in captured.err
    assert "no repo slug" in captured.err


def test_spawn_retry_budget_exhaustion(agentctl, tmp_path, monkeypatch):
    """Retry budget exhaustion: reserve_slot always raises ConcurrencyError.

    With _SPAWN_RETRY_BUDGET_S=0 the deadline is already past on the first
    attempt, so the loop exits immediately without sleeping.  The invariants:
    - return code 2
    - outcome.json written with exit_status=capacity_refused and an error_reason
    - no subprocess started (the run never reached _spawn_claude)
    """
    import json
    import types

    run_dir = tmp_path / "run-refused"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()

    monkeypatch.setattr(agentctl, "_SPAWN_RETRY_BUDGET_S", 0)

    def _always_refuse(entry):
        raise agentctl.R.ConcurrencyError("global concurrency ceiling (16/16)", current=[])
    monkeypatch.setattr(agentctl.R, "reserve_slot", _always_refuse)

    # Fail the test immediately if a subprocess is attempted — none should start.
    def _no_popen(*args, **kwargs):
        raise AssertionError("subprocess.Popen must not be called on capacity_refused path")
    monkeypatch.setattr(agentctl.subprocess, "Popen", _no_popen)

    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")

    args = types.SimpleNamespace(agent="bug-investigator", task="t",
                                 parent=None, dry_run=False, label=None)
    rc = agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": "opus"},
        run_id="run-refused", run_dir=run_dir, worktree=worktree,
        profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")

    assert rc == 2
    outcome = json.loads((run_dir / "outcome.json").read_text())
    assert outcome["exit_status"] == "capacity_refused"
    assert "retried for up to" in outcome["error_reason"]
    assert "16/16" in outcome["error_reason"]


def test_review_post_returncode_zero_non_40char_output_fails_closed(
        agentctl, tmp_path, monkeypatch, capsys):
    """Fix 3, gap 2: a gh api exit of 0 with non-40-char output fails closed via the
    new else branch, rather than falling through and stamping the original abbreviation.
    This covers unexpected GitHub API response formats.

    A real post (dry_run=False): --dry-run skips this lookup entirely (round 2, PR
    #936) and so never reaches this failure at all — see the dry-run tests below."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    abbrev = "abc1234de"  # 9 chars, valid hex, < 40

    import subprocess as _subprocess

    def fake_run_zero_short(cmd, **kw):
        r = _subprocess.CompletedProcess(cmd, 0)
        r.stdout = "short\n"   # 5 chars — not 40, triggers the new else branch
        r.stderr = ""
        return r

    monkeypatch.setattr("subprocess.run", fake_run_zero_short)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)

    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev, run_id="r", repo="convivy/x", dry_run=False))
    captured = capsys.readouterr()
    assert rc != 0, "must fail closed when gh api returns 0 with non-40-char output"
    assert agentctl.RP.parse(captured.out) is None, (
        "abbreviated SHA must not reach the stamp when normalization output is unexpected")
    assert "unexpected output" in captured.err


# --- publish fast-check gates ------------------------------------------------
#
# Sampling 26 coder-class PRs whose first push failed CI (2026-07-29): `Ruff lint`
# was 5 of 12 observed failures and lint-or-typecheck together were 9 of 12 — 75%.
# Only one was a real test failure. These are the cheapest checks in the suite, so
# catching one at publish costs ~20s against a full CI run plus, usually, a coder
# re-dispatch and another review round.
#
# The gate rather than the instruction, for the reason cmd_publish already gives
# about pushing: it exists "rather than relying on an LLM to remember `git push`
# each round". The dispatch briefs already say to run CI locally, and PRs still
# arrive lint-red.


def test_lint_gate_only_applies_where_ci_lints(agentctl, tmp_path):
    """Gating on a check the repo never adopted would block a publish over a rule
    that does not exist there. Same narrowness `_wt_uses_ruff_format` has."""
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  t:\n    steps:\n      - run: pytest\n")
    assert agentctl._ruff_lint_gate(wt) == 0


def test_lint_gate_blocks_when_ruff_check_fails(agentctl, tmp_path, monkeypatch):
    """Also pins the ARGV, not just the control flow.

    Review caught that mocking subprocess.run with `lambda *a, **k` discards the
    command, so a typo — `["ruff", "ckeck", "."]` — would satisfy every
    control-flow assertion while the gate ran nothing. A test that passes when the
    thing under test is broken is worse than no test.
    """
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  t:\n    steps:\n      - run: ruff check .\n")
    seen = {}

    def fake(argv, *a, **k):
        seen["argv"] = argv
        seen["cwd"] = k.get("cwd")
        return type("R", (), {"returncode": 1, "stdout": "F401 unused import",
                              "stderr": ""})()

    monkeypatch.setattr(agentctl.subprocess, "run", fake)
    assert agentctl._ruff_lint_gate(wt) == 1
    assert seen["argv"] == ["ruff", "check", "."], "must run exactly what CI runs"
    assert seen["cwd"] == str(wt)


def test_lint_gate_passes_when_ruff_check_is_clean(agentctl, tmp_path, monkeypatch):
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  t:\n    steps:\n      - run: ruff check .\n")
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: type("R", (), {"returncode": 0,
                                                       "stdout": "", "stderr": ""})())
    assert agentctl._ruff_lint_gate(wt) == 0


def test_lint_gate_proceeds_when_ruff_is_absent(agentctl, tmp_path, monkeypatch):
    """Best-effort, matching the format gate. A missing toolchain must not block a
    publish — CI stays the hard gate, and this only ever adds an earlier catch."""
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  t:\n    steps:\n      - run: ruff check .\n")

    def boom(*a, **k):
        raise FileNotFoundError("ruff")

    monkeypatch.setattr(agentctl.subprocess, "run", boom)
    assert agentctl._ruff_lint_gate(wt) == 0


def test_lint_gate_is_not_the_format_gate(agentctl, tmp_path):
    """`ruff check` and `ruff format --check` are different commands. The format
    gate is narrow to repos whose CI formats (styleguide alone as of 2026-06); lint
    is the one that actually fails, so it must fire on a lint-only repo."""
    wt = _mk_wt_with_workflow(tmp_path, "jobs:\n  t:\n    steps:\n      - run: ruff check .\n")
    assert agentctl._wt_uses_ruff_format(wt) is False   # format gate would skip…
    assert agentctl._wt_ci_runs(wt, "ruff check") is True   # …lint gate would not


