def test_publish_scans_a_commit_already_on_the_remote_and_blocks_on_a_hit(
        agentctl, tmp_path, monkeypatch, capsys):
    """THE INCIDENT: run-c36c0559 pushed its own commit (662b8452) to GitHub from
    inside the run, outside agentctl. The orchestrator's `agentctl publish` then
    found `remote_before == head` and took the early return — printing
    "already in sync" and `published-sha:` — without ever reaching
    `_content_scan_gate`, which (before this fix) sat only on the push path below
    the early return. Simulated here by pushing the feature branch with plain git
    before calling `cmd_publish`, so the worktree is already in sync when publish
    runs."""
    import argparse
    import subprocess as sp
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nnew work\n")
    git("commit", "-aqm", "fix: work")
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    def refuse(repo, worktree, shas, *, skip_unknown_repo=False, push_remote=None):
        raise agentctl.PS.PublishScanRefused("agent-platform at abc123: content scan (1):\n"
                                             "    app.py:1: a person's name")

    monkeypatch.setattr(agentctl.PS, "scan_commits", refuse)
    promoted = []
    monkeypatch.setattr(agentctl, "_promote_if_committed_not_pushed",
                        lambda *a, **k: promoted.append(a))
    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=False, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()
    assert rc == 1
    assert "BLOCKED by Builder's content scan" in out.err
    assert "published-sha:" not in out.out
    assert not promoted, "a blocked scan must not promote the run to completed"


def test_publish_scans_a_clean_commit_already_on_the_remote_and_still_publishes(
        agentctl, tmp_path, monkeypatch, capsys):
    """Control for the test above: a commit already on the remote that the scan
    PASSES must still publish normally — the scan runs, finds nothing, and
    `publish` proceeds exactly as it did before this fix."""
    import argparse
    import subprocess as sp
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nnew work\n")
    git("commit", "-aqm", "fix: work")
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    scanned = []
    monkeypatch.setattr(agentctl.PS, "scan_commits",
                        lambda repo, worktree, shas, *, skip_unknown_repo=False,
                        push_remote=None: scanned.extend(shas))
    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=False, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()
    assert rc == 0
    assert "already in sync" in out.out
    pinned = [ln.split(": ", 1)[1].strip() for ln in out.out.splitlines()
              if ln.startswith("published-sha:")]
    assert pinned, "a clean scan on the in-sync path must still print the review pin"
    head = git("rev-parse", "HEAD").stdout.strip()
    assert scanned == [head], "the scan must run on the in-sync path, against HEAD"


def test_publish_in_sync_scan_is_not_fooled_by_a_decoy_tracking_ref(
        agentctl, tmp_path, monkeypatch, capsys):
    """THE IN-SYNC CALL SITE'S OWN DECOY GAP (security review, PR #1002 round
    1): `_content_scan_gate`'s in-sync branch passes `remote_sha=None` and
    relies entirely on `commits_new_to_remote`'s `--remotes=origin` sweep
    over every OTHER tracking ref to know what is already safely scanned —
    unlike the push path below, which refreshes every one of those refs from
    the real remote (over the App token) right before its own scan runs,
    this branch never refreshed anything before this fix. A dispatched run's
    own write to some OTHER `refs/remotes/origin/<name>` ref
    (`run_sandbox.py`'s write protection only covers ref paths that existed
    when the sandbox was built) could stand in as "already scanned" for an
    ancestor of HEAD that this gate — the one thing in the whole PR flow that
    ever runs Builder's content scan — had never actually scanned at all.
    `bad_sha` reaches origin for real here (pushed directly with plain git,
    simulating the run-c36c0559 incident this call site exists to catch), so
    this is squarely the in-sync branch; the decoy must not stop the gate
    from reaching it."""
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    _round3_operator_config(tmp_path, monkeypatch)
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "marker.py").write_text("marker\n")
    git("add", ".")
    git("commit", "-aqm", "adds a marker")
    bad_sha = git("rev-parse", "HEAD").stdout.strip()
    (wt / "marker.py").write_text("clean again\n")
    git("add", ".")
    git("commit", "-aqm", "removes the marker")
    import subprocess as sp
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    # The decoy: a write to a DIFFERENT tracking ref, pointing at bad_sha as
    # though it were already known-safe.
    git("update-ref", "refs/remotes/origin/some-other-branch", bad_sha)

    call_log = tmp_path / "calls.log"
    monkeypatch.setenv("FAKE_ENGINE_FAIL_REF", bad_sha)
    monkeypatch.setenv("FAKE_ENGINE_CALL_LOG", str(call_log))

    args = argparse.Namespace(worktree=str(wt), run=None, repo="agent-platform",
                              purpose=None, pr=None, dry_run=False, skip_checks=True,
                              force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc != 0, err
    assert "BLOCKED by Builder's content scan" in err
    assert bad_sha[:9] in err
    assert call_log.exists() and bad_sha in call_log.read_text().splitlines(), (
        "the in-sync path's own scan must have actually reached the early "
        "commit a decoy tried to hide, not silently treat it as already known")


def test_publish_in_sync_refuses_and_trusts_nothing_when_the_refresh_fetch_fails(
        agentctl, tmp_path, monkeypatch, capsys):
    """ROUND 2'S OWN BLOCKING FINDING (reviewer and security-reviewer): this
    call site's refresh was still the hand-rolled `git("fetch", ...)` from
    round 2's widening, never routed through the shared
    `publish_scan.refresh_remote_tracking_refs`, and its exit code was
    discarded — unlike the push call site a few lines below, which already
    refuses on a non-zero `refresh.returncode`. A fetch here can fail for
    real: a flaky network, or a lock race from another worktree sharing
    this repo's ref store (hit for real on 2026-10-23, a publish's
    pre-push refresh failing with "bad object refs/heads/<branch>" while
    another worktree's coder was committing). `origin` is repointed at a
    path that was never `git init`'d so this fetch fails for real, no
    stub — before the fix, the failure was silently swallowed, the decoy
    below survived untouched, and the in-sync branch trusted it; after the
    fix, the call site refuses before ever reaching the scan, so the decoy
    is never consulted either way."""
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    _round3_operator_config(tmp_path, monkeypatch)
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "marker.py").write_text("marker\n")
    git("add", ".")
    git("commit", "-aqm", "adds a marker")
    bad_sha = git("rev-parse", "HEAD").stdout.strip()
    (wt / "marker.py").write_text("clean again\n")
    git("add", ".")
    git("commit", "-aqm", "removes the marker")
    import subprocess as sp
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    # The decoy: a write to a DIFFERENT tracking ref, pointing at bad_sha as
    # though it were already known-safe — must stay untrusted either way.
    git("update-ref", "refs/remotes/origin/some-other-branch", bad_sha)

    # Make the refresh fetch fail for real: `origin` now resolves nowhere.
    nonexistent = tmp_path / "no-such-remote.git"   # deliberately never git-init'd
    git("remote", "set-url", "origin", f"file://{nonexistent}")

    call_log = tmp_path / "calls.log"
    monkeypatch.setenv("FAKE_ENGINE_FAIL_REF", bad_sha)
    monkeypatch.setenv("FAKE_ENGINE_CALL_LOG", str(call_log))

    args = argparse.Namespace(worktree=str(wt), run=None, repo="agent-platform",
                              purpose=None, pr=None, dry_run=False, skip_checks=True,
                              force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1, err
    assert "REFUSED" in err and "refresh" in err
    assert not call_log.exists(), (
        "a failed refresh must refuse before the scan ever runs — nothing it "
        "left in refs/remotes/origin/* (the decoy included) may be trusted")


def test_publish_in_sync_scan_is_not_fooled_by_a_decoy_at_head(
        agentctl, tmp_path, monkeypatch, capsys):
    """THE ROUND-2 HEAD GAP (security-reviewer): `--remotes=origin` globs in
    `refs/remotes/origin/HEAD` like any other single-segment name under
    that namespace, and `git fetch --prune` — confirmed by hand against a
    real fetch — never removes a SYMBOLIC ref there, only a plain one (a
    plain decoy at this exact path is already pruned by this call site's
    own refresh, same as the `some-other-branch` decoy above; a SYMBOLIC
    one survives it untouched). The decoy here is
    `refs/remotes/origin/HEAD` symlinked at a local tag, itself outside
    the refresh's `refs/heads/*:refs/remotes/origin/*` namespace and so
    untouched by it either, holding `bad_sha`."""
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    _round3_operator_config(tmp_path, monkeypatch)
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "marker.py").write_text("marker\n")
    git("add", ".")
    git("commit", "-aqm", "adds a marker")
    bad_sha = git("rev-parse", "HEAD").stdout.strip()
    (wt / "marker.py").write_text("clean again\n")
    git("add", ".")
    git("commit", "-aqm", "removes the marker")
    import subprocess as sp
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    # The decoy: a tag holding bad_sha, with refs/remotes/origin/HEAD
    # symlinked at it — the one shape that survives the refresh's --prune.
    git("tag", "decoy-target", bad_sha)
    git("symbolic-ref", "refs/remotes/origin/HEAD", "refs/tags/decoy-target")

    call_log = tmp_path / "calls.log"
    monkeypatch.setenv("FAKE_ENGINE_FAIL_REF", bad_sha)
    monkeypatch.setenv("FAKE_ENGINE_CALL_LOG", str(call_log))

    args = argparse.Namespace(worktree=str(wt), run=None, repo="agent-platform",
                              purpose=None, pr=None, dry_run=False, skip_checks=True,
                              force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc != 0, err
    assert "BLOCKED by Builder's content scan" in err
    assert bad_sha[:9] in err
    assert call_log.exists() and bad_sha in call_log.read_text().splitlines(), (
        "a decoy at refs/remotes/origin/HEAD must not hide bad_sha from the "
        "in-sync path's own scan")


def test_publish_in_sync_scan_is_not_fooled_by_a_decoy_under_another_symbolic_name(
        agentctl, tmp_path, monkeypatch, capsys):
    """THE ROUND-3 GAP (reviewer, PR #1002 round 4), at the in-sync call
    site: round 4's own fix excluded `refs/remotes/origin/HEAD` by name,
    but a SYMBOLIC ref under `refs/remotes/origin/*` survives this call
    site's own refresh regardless of its name (confirmed by hand against a
    real fetch, same mechanism as the `HEAD` case above). The decoy here is
    `refs/remotes/origin/zzz-decoy` symlinked at a local tag holding
    `bad_sha` — a name other than `HEAD`."""
    real_gate = agentctl._content_scan_gate  # _publishable stubs this; restored below
    _round3_operator_config(tmp_path, monkeypatch)
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    monkeypatch.setattr(agentctl, "_content_scan_gate", real_gate)
    git = _git_in(wt)
    (wt / "marker.py").write_text("marker\n")
    git("add", ".")
    git("commit", "-aqm", "adds a marker")
    bad_sha = git("rev-parse", "HEAD").stdout.strip()
    (wt / "marker.py").write_text("clean again\n")
    git("add", ".")
    git("commit", "-aqm", "removes the marker")
    import subprocess as sp
    sp.run(["git", "push", "-q", "origin", "feature"], cwd=str(wt), check=True)

    # The decoy: a tag holding bad_sha, with refs/remotes/origin/zzz-decoy
    # symlinked at it — a name other than HEAD, surviving the refresh's
    # own --prune no matter what it is called.
    git("tag", "decoy-target", bad_sha)
    git("symbolic-ref", "refs/remotes/origin/zzz-decoy", "refs/tags/decoy-target")

    call_log = tmp_path / "calls.log"
    monkeypatch.setenv("FAKE_ENGINE_FAIL_REF", bad_sha)
    monkeypatch.setenv("FAKE_ENGINE_CALL_LOG", str(call_log))

    args = argparse.Namespace(worktree=str(wt), run=None, repo="agent-platform",
                              purpose=None, pr=None, dry_run=False, skip_checks=True,
                              force=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc != 0, err
    assert "BLOCKED by Builder's content scan" in err
    assert bad_sha[:9] in err
    assert call_log.exists() and bad_sha in call_log.read_text().splitlines(), (
        "a decoy at refs/remotes/origin/zzz-decoy must not hide bad_sha from "
        "the in-sync path's own scan")


def test_skip_checks_is_logged(agentctl, tmp_path, monkeypatch):
    """The gates exist because instructions did not hold. An escape hatch nobody
    can count would decay the same way, so it is logged like a model override."""
    log = tmp_path / "skipped.jsonl"
    monkeypatch.setattr(agentctl, "SKIPPED_CHECKS_LOG", log)
    agentctl._log_skipped_checks(wt=tmp_path / "wt", branch="agent/thing")
    rec = json.loads(log.read_text().strip())
    assert rec["branch"] == "agent/thing" and rec["worktree"].endswith("wt")


def test_skip_checks_flag_matches_what_publish_reads(agentctl):
    """The flag's argparse `dest` and the attribute `cmd_publish` reads must agree.

    `--skip-checks` would otherwise parse to `skip_checks` while a reader looking
    for anything else silently gets the `getattr(..., False)` default — the flag
    would appear to work and gate nothing. Review flagged the untested wiring;
    this pins the seam rather than the whole command, which needs a real worktree.
    """
    import inspect
    parser = agentctl.build_parser() if hasattr(agentctl, "build_parser") else None
    if parser is not None:
        args = parser.parse_args(["publish", ".", "--skip-checks"])
        assert getattr(args, "skip_checks", None) is True
    src = inspect.getsource(agentctl.cmd_publish)
    assert 'getattr(args, "skip_checks", False)' in src, (
        "cmd_publish must read the same attribute argparse writes")


# --- deployed-tree check at dispatch (ARCH-229/issue_01KYQ9NDT0ZEC) -----------
#
# When the deployed platform checkout is on a non-main branch or behind
# origin/main, every agentctl spawn runs stale code without anyone knowing.
# _warn_deployed_tree warns at spawn time, non-blocking, so the condition is
# surfaced at the moment it matters (dispatch) rather than buried in the
# autopull log.


def _make_deployed_repo(tmp_path) -> tuple[Path, Path]:
    """Set up a fake primary checkout + origin for testing _warn_deployed_tree.

    Returns (repo_root, origin_path) where repo_root is a git checkout on main
    with one commit, and origin_path is a bare repo pushed to (so origin/main
    resolves).  The caller adds commits to origin and pulls to create the
    "behind" scenario, or creates a non-main branch for the "off-main" check.
    """
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", str(origin)], check=True)
    subprocess.run(["git", "-C", str(origin), "symbolic-ref", "HEAD", "refs/heads/main"],
                    check=True)

    repo = tmp_path / "deployed"
    repo.mkdir()
    subprocess.run(["git", "init", "-q", "--initial-branch=main", str(repo)], check=True)
    subprocess.run(["git", "-C", str(repo), "config", "user.email", "t@t.t"], check=True)
    subprocess.run(["git", "-C", str(repo), "config", "user.name", "t"], check=True)
    (repo / "file.py").write_text("code\n")
    subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(repo), "commit", "-qm", "init"], check=True)
    subprocess.run(["git", "-C", str(repo), "remote", "add", "origin", str(origin)], check=True)
    subprocess.run(["git", "-C", str(repo), "push", "-q", "-u", "origin", "main"], check=True)
    return repo, origin


def test_warn_deployed_tree_stays_quiet_on_clean_tree(agentctl, tmp_path, monkeypatch, capsys):
    """On main, up to date with origin/main — nothing to warn about."""
    repo, _ = _make_deployed_repo(tmp_path)
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    assert capsys.readouterr().err == ""


def test_warn_deployed_tree_warns_on_off_main_branch(agentctl, tmp_path, monkeypatch, capsys):
    """Off-main branch → warn, short-circuit before the behind-count check."""
    repo, _ = _make_deployed_repo(tmp_path)
    subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "stray-branch"], check=True)
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    err = capsys.readouterr().err
    assert "not 'main'" in err
    assert "stray-branch" in err


def test_warn_deployed_tree_warns_when_behind_origin_main(agentctl, tmp_path, monkeypatch, capsys):
    """Behind origin/main → warn with the commit count."""
    repo, origin = _make_deployed_repo(tmp_path)
    # Advance origin/main past the checkout: commit directly on origin.
    origin_checkout = tmp_path / "origin-copy"
    subprocess.run(["git", "clone", "-q", str(origin), str(origin_checkout)], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "config", "user.email", "t@t.t"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "config", "user.name", "t"], check=True)
    (origin_checkout / "new.py").write_text("new\n")
    subprocess.run(["git", "-C", str(origin_checkout), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "commit", "-qm", "advance"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "push", "-q", "origin", "main"], check=True)
    # Fetch so the deployed tree's origin/main ref is updated.
    subprocess.run(["git", "-C", str(repo), "fetch", "-q", "origin"], check=True)

    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    err = capsys.readouterr().err
    assert "behind" in err and "1 commit" in err


def test_warn_deployed_tree_silent_when_state_unknown(agentctl, tmp_path, monkeypatch, capsys):
    """A missing repo (bad path, no .git) must not raise or print."""
    missing = tmp_path / "does-not-exist"
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: missing)
    agentctl._warn_deployed_tree()
    assert capsys.readouterr().err == ""
    # Also works when the path exists but has no git:
    not_a_repo = tmp_path / "not-a-repo"
    not_a_repo.mkdir()
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: not_a_repo)
    agentctl._warn_deployed_tree()
    assert capsys.readouterr().err == ""


def test_deployed_platform_path_none_when_not_symlink(agentctl, tmp_path, monkeypatch):
    """_deployed_platform_path returns None when ~/.local/bin/agentctl is not
    a symlink (e.g. in CI, or from a dev checkout)."""
    monkeypatch.setattr(Path, "home", lambda: tmp_path)
    local_bin = tmp_path / ".local" / "bin"
    local_bin.mkdir(parents=True)
    (local_bin / "agentctl").write_text("fake\n")
    assert agentctl._deployed_platform_path() is None


def test_warn_deployed_tree_skips_detached_head(agentctl, tmp_path, monkeypatch, capsys):
    """Detached HEAD must not crash or produce a misleading warning."""
    repo, _ = _make_deployed_repo(tmp_path)
    subprocess.run(["git", "-C", str(repo), "checkout", "-q", "--detach", "HEAD"], check=True)
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    # Detached HEAD skips the check without changing behaviour.
    assert capsys.readouterr().err == ""


# --- canonical-lib gate at spawn (security-reviewer, agent-platform#470) ----
#
# ARCH-229 makes agentctl resolve its own lib relative to __file__, so a
# worktree's copy of bin/agentctl now imports THAT worktree's tool_policy.py.
# _spawn_lib_gate refuses `spawn` (not other subcommands) when this process's
# own lib is not the canonical one, so a worktree can't govern what tools a
# spawned reviewer/security-reviewer is granted.


def test_spawn_lib_gate_none_when_no_canonical_reference(agentctl, monkeypatch, capsys):
    """No canonical reference resolvable on this machine (a fresh machine
    before install.sh) — the gate must fail open, but LOUDLY: silently
    disabling the gate is indistinguishable from an attacker deleting the
    one symlink it anchors to (security-reviewer, agent-platform#470 round
    3). Outside CI (see the next test for the CI-quiet case), it must warn.

    Monkeypatches `_canonical_spawn_lib_dirs` directly (the function the gate
    actually calls), not `_deployed_platform_path` (which the gate no longer
    uses — see the passwd-vs-$HOME tests below for why)."""
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: None)
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    monkeypatch.delenv("CI", raising=False)
    assert agentctl._spawn_lib_gate() is None
    err = capsys.readouterr().err
    assert "no canonical lib" in err
    assert "install.sh" in err


def test_spawn_lib_gate_no_canonical_reference_quiet_in_ci(agentctl, monkeypatch, capsys):
    """Same fail-open, but under CI (the CI=true convention every major CI
    provider sets) — this is the expected, universal shape of every job on
    every repo, not a signal of anything wrong, so the warning must not
    fire. Still must proceed (fail open), just silently."""
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: None)
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    monkeypatch.setenv("CI", "true")
    assert agentctl._spawn_lib_gate() is None
    assert capsys.readouterr().err == ""


# A bare `os.environ.get("CI")` truthy check reads *any* non-empty value as
# "in CI" -- including "false" and "0", which some tooling sets deliberately
# to mean "not CI", distinct from leaving the variable unset. That's exactly
# the AGENTCTL_ALLOW_WORKTREE_SPAWN=0 defect from two rounds ago, now on the
# CI check two lines away. Fixed to match that convention: strip, lowercase,
# and treat "", "0", and "false" as "not CI" -- the warning must still fire.
# Each assertion below is written to FAIL against the pre-fix bare-truthy
# check (`if not os.environ.get("CI")`), which reads "false" and "0" as
# truthy and wrongly suppresses the warning.


@pytest.mark.parametrize("value", ["false", "0", "False", "FALSE", "  false  "])
def test_spawn_lib_gate_no_canonical_reference_warns_on_ci_off_values(
        agentctl, monkeypatch, capsys, value):
    """CI=false / CI=0 (and case/whitespace variants) mean "not CI" -- the
    warning must fire exactly as if CI were unset."""
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: None)
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    monkeypatch.setenv("CI", value)
    assert agentctl._spawn_lib_gate() is None
    err = capsys.readouterr().err
    assert "no canonical lib" in err


@pytest.mark.parametrize("value", ["1", "true", "True", "TRUE", "yes"])
def test_spawn_lib_gate_no_canonical_reference_quiet_on_ci_on_values(
        agentctl, monkeypatch, capsys, value):
    """CI=1 and other non-"", "0", "false" values still mean "in CI" -- the
    warning must stay suppressed, same as the existing CI=true case."""
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: None)
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    monkeypatch.setenv("CI", value)
    assert agentctl._spawn_lib_gate() is None
    assert capsys.readouterr().err == ""


def test_spawn_lib_gate_passes_when_lib_matches_canonical(agentctl, monkeypatch, capsys):
    """This process's own lib IS the canonical one (invoked via the bare
    `agentctl` on PATH, or the primary checkout directly) — proceed silently."""
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: {agentctl._LIB_DIR})
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    assert agentctl._spawn_lib_gate() is None
    assert capsys.readouterr().err == ""


def test_spawn_lib_gate_refuses_when_lib_mismatches_canonical(agentctl, tmp_path, monkeypatch, capsys):
    """This process's own lib does NOT match the canonical one — the shape of
    `<worktree>/bin/agentctl spawn ...`, invoked directly rather than via the
    bare `agentctl` on PATH. Must refuse (exit code 2), naming both paths."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
    other_lib.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: {other_lib})
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)
    assert agentctl._spawn_lib_gate() == 2
    err = capsys.readouterr().err
    assert "refusing to spawn" in err
    assert str(agentctl._LIB_DIR.resolve()) in err
    assert str(other_lib.resolve()) in err


def test_spawn_lib_gate_escape_hatch_allows_and_warns(agentctl, tmp_path, monkeypatch, capsys):
    """AGENTCTL_ALLOW_WORKTREE_SPAWN bypasses the refusal, loudly."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
    other_lib.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: {other_lib})
    monkeypatch.setenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, "1")
    assert agentctl._spawn_lib_gate() is None
    err = capsys.readouterr().err
    assert agentctl._ALLOW_WORKTREE_SPAWN_ENV in err


# A bare `os.environ.get(...)` truthy check reads *any* set value -- including
# "0" -- as "on", so AGENTCTL_ALLOW_WORKTREE_SPAWN=0 (someone explicitly
# saying "no") bypassed the gate exactly like =1. Fixed to match the
# AGENTCTL_ENFORCE_TOOL_POLICY convention at _enforce_tool_policy_default:
# strip whitespace, treat "" and "0" as not set. Each assertion below is
# written to FAIL against the pre-fix bare-truthy check -- run against that
# code, test_spawn_lib_gate_escape_hatch_rejects_zero and
# test_spawn_lib_gate_escape_hatch_rejects_whitespace_only both fail, because
# the bare check treats "0" and "   " as truthy and bypasses.
#
# That first fix still left "false" out of the not-set set, so
# AGENTCTL_ALLOW_WORKTREE_SPAWN=false bypassed the gate exactly like =1 --
# the same defect class the CI check a few lines above this one was already
# fixed for. Extended to lowercase-and-check "false" too, matching CI.
# test_spawn_lib_gate_escape_hatch_rejects_false is written to FAIL against
# that intermediate code.


@pytest.mark.parametrize("value", ["1", "yes", "anything-nonempty"])
def test_spawn_lib_gate_escape_hatch_bypasses_on_nonempty_non_zero(
        agentctl, tmp_path, monkeypatch, capsys, value):
    """Any non-empty value other than "0" bypasses and warns -- the hatch
    must still work for its intended use, not just for the literal "1"."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
    other_lib.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: {other_lib})
    monkeypatch.setenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, value)
    assert agentctl._spawn_lib_gate() is None
    err = capsys.readouterr().err
    assert agentctl._ALLOW_WORKTREE_SPAWN_ENV in err


def test_spawn_lib_gate_escape_hatch_rejects_zero(agentctl, tmp_path, monkeypatch, capsys):
    """AGENTCTL_ALLOW_WORKTREE_SPAWN=0 must NOT bypass -- "0" means "no,
    don't allow this", not "set, so allow it". The gate must still refuse a
    worktree-path spawn exactly as if the variable were unset."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
    other_lib.mkdir(parents=True)
    monkeypatch.setattr(agentctl, "_canonical_spawn_lib_dirs", lambda: {other_lib})
    monkeypatch.setenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, "0")
    assert agentctl._spawn_lib_gate() == 2
    err = capsys.readouterr().err
    assert "refusing to spawn" in err


