def test_spawn_lib_gate_refuses_spoofed_lib_via_symlinked_deploy_area(
        agentctl, tmp_path, monkeypatch, capsys):
    """End-to-end: a real farm symlink exists (so there IS a canonical
    reference to compare against), and the deploy area is ALSO symlinked into
    a worktree. `_LIB_DIR` is set to that worktree's lib -- the shape of the
    attack this fix closes. Against the pre-fix code, the symlinked deploy
    area is admitted, `this_lib` matches it, and the gate wrongly passes
    (rc is None). Fixed, the symlinked member is excluded, `this_lib` matches
    neither canonical member, and the gate must refuse (rc == 2)."""
    import types

    passwd_home = tmp_path / "home"
    passwd_home.mkdir()
    farm_checkout = tmp_path / "primary-checkout"
    (farm_checkout / "bin").mkdir(parents=True)
    (farm_checkout / "bin" / "agentctl").touch()
    (farm_checkout / "lib" / "agent-platform").mkdir(parents=True)
    farm_bin_dir = passwd_home / ".local" / "bin"
    farm_bin_dir.mkdir(parents=True)
    (farm_bin_dir / "agentctl").symlink_to(farm_checkout / "bin" / "agentctl")
    monkeypatch.setattr(agentctl.pwd, "getpwuid",
                         lambda uid: types.SimpleNamespace(pw_dir=str(passwd_home)))

    worktree_lib = tmp_path / "worktree" / "lib" / "agent-platform"
    worktree_lib.mkdir(parents=True)
    deploy_dir = passwd_home / ".local" / "deploy"
    deploy_dir.mkdir(parents=True)
    (deploy_dir / "agent-platform-shared").symlink_to(tmp_path / "worktree")

    monkeypatch.setattr(agentctl, "_LIB_DIR", worktree_lib)
    monkeypatch.delenv(agentctl._ALLOW_WORKTREE_SPAWN_ENV, raising=False)

    assert agentctl._spawn_lib_gate() == 2
    err = capsys.readouterr().err
    assert "refusing to spawn" in err


def test_canonical_spawn_lib_dirs_admits_deploy_area_reached_through_symlinked_home(
        agentctl, tmp_path, monkeypatch):
    """The regression this fix could most easily cause: a machine whose
    passwd-database home is ITSELF reached through a symlink (macOS's `/tmp`
    -> `/private/tmp` is the familiar real-world case), with a perfectly real,
    non-symlinked deploy area underneath. The symlink check anchors on the
    RESOLVED passwd home and only inspects components `_DEPLOY_SHARED_LIB_RELPATH`
    adds below it, so this must still admit the deploy area -- a naive
    resolved-vs-unresolved path comparison would wrongly drop it instead."""
    import types

    real_home = tmp_path / "real_home"
    real_home.mkdir()
    symlinked_home = tmp_path / "symlinked_home"
    symlinked_home.symlink_to(real_home)

    deploy_lib = real_home / agentctl._DEPLOY_SHARED_LIB_RELPATH
    deploy_lib.mkdir(parents=True)
    monkeypatch.setattr(agentctl.pwd, "getpwuid",
                         lambda uid: types.SimpleNamespace(pw_dir=str(symlinked_home)))

    canonical = agentctl._canonical_spawn_lib_dirs()
    assert canonical is not None and len(canonical) == 1
    assert next(iter(canonical)).resolve() == deploy_lib.resolve()


# --- an OSError from the symlink walk itself must fail open, not crash
# cmd_spawn (reviewer, agent-platform#470 round 6) --------------------------
#
# Path.is_symlink() swallows ENOENT/ENOTDIR/EBADF/ELOOP itself, but not
# EACCES from an unreadable intermediate component. Unhandled, that would
# propagate out of `_path_has_symlink_component` uncaught -- the same failure
# shape as the `pwd.getpwuid` KeyError fixed two rounds earlier. Both tests
# below are written to FAIL against the pre-fix code (bare `if
# current.is_symlink(): return True`, no try/except).

def test_path_has_symlink_component_fails_open_on_os_error(agentctl, tmp_path, monkeypatch):
    """Forces `is_symlink()` to raise OSError partway through the walk and
    confirms the function treats an unverifiable component as symlinked --
    returns True -- rather than propagating."""
    anchor = tmp_path / "anchor"
    anchor.mkdir()
    monkeypatch.setattr(agentctl.Path, "is_symlink",
                         lambda self, *a, **k: (_ for _ in ()).throw(OSError(13, "Permission denied")))
    assert agentctl._path_has_symlink_component(anchor, agentctl.Path("sub/dir")) is True


def _raise_eacces_for_deploy_components(self, *a, **k):
    """`is_symlink()` stand-in that only raises for components of the
    `.local/deploy/...` walk, leaving the unrelated `.local/bin/agentctl`
    farm-symlink check (`_deployed_platform_path_under`, out of scope for
    this fix) working normally -- otherwise a blanket raiser would break
    `_canonical_spawn_lib_dirs` before it ever reaches the deploy-area check
    this fix is about."""
    if "deploy" in self.parts:
        raise OSError(13, "Permission denied")
    return False


