class _FakeClock:
    """A mutable instant, advanced by a faked `time.sleep` and read by a faked
    `datetime.now` — the pattern this file already uses (see `_Clock` in
    test_session_dir_name_uses_the_local_clock_not_a_utc_conversion), extended
    with a `sleep` hook so a wait can be observed advancing it rather than
    merely being a no-op."""
    def __init__(self, start: float):
        self.t = start

    def sleep(self, seconds):
        self.t += seconds

    def install(self, monkeypatch, agentctl):
        clock = self

        class _Now(datetime):
            @classmethod
            def now(cls, tz=None):
                base = datetime.fromtimestamp(clock.t, tz=timezone.utc)
                return base if tz is not None else base.replace(tzinfo=None)

        monkeypatch.setattr(agentctl, "datetime", _Now)
        # `_hold_sleep`, not `time.sleep`: the latter is also hit by
        # `_pid_start_time`'s `ps` probe on `_run_session`'s real spawn path,
        # whose own timeout-driven busy-poll would otherwise get recorded as
        # if it were the hold advancing the clock.
        monkeypatch.setattr(agentctl, "_hold_sleep", self.sleep)


def test_wait_for_rate_limit_hold_proceeds_immediately_when_no_state(
        agentctl, tmp_path, monkeypatch):
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    clock = _FakeClock(0.0)
    clock.install(monkeypatch, agentctl)
    held = agentctl._wait_for_rate_limit_hold()
    assert held is None
    assert clock.t == 0.0, "must not have slept at all"


