def test_wait_for_rate_limit_hold_re_checks_after_sleeping_and_holds_again_on_fresh_overage(
        agentctl, tmp_path, monkeypatch):
    """A five-hour window resetting does not by itself clear overage (the
    monthly overage cap is a separate reset). If the reading read after the
    first sleep is a FRESH one that is still held, the wait continues on the
    new resetsAt rather than dispatching into overage."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    first_reset = 1_000_000.0
    second_reset = 1_000_500.0
    d = _seed_five_hour_reading(T, "run-seed", utilization=0.95, resets_at=first_reset,
                               is_using_overage=True)
    clock = _FakeClock(first_reset - 10)

    real_sleep = clock.sleep

    def sleep_and_refresh(seconds):
        real_sleep(seconds)
        if clock.t >= first_reset:
            # Simulate another run finalizing mid-wait with a fresher, still-held
            # reading (overage, not yet cleared) — the LAST event in a
            # transcript wins, so appending onto the same run is enough to
            # make the scan see it as the freshest observation.
            _rl(d, status="rejected", isUsingOverage=True,
                unifiedWindows={"five_hour": {"utilization": 0.2, "resetsAt": second_reset}})

    # `_hold_sleep`, not `time.sleep` — see `_FakeClock.install`'s comment.
    monkeypatch.setattr(agentctl, "_hold_sleep", sleep_and_refresh)

    class _Now(datetime):
        @classmethod
        def now(cls, tz=None):
            base = datetime.fromtimestamp(clock.t, tz=timezone.utc)
            return base if tz is not None else base.replace(tzinfo=None)
    monkeypatch.setattr(agentctl, "datetime", _Now)

    held = agentctl._wait_for_rate_limit_hold()
    assert held is not None
    assert "overage" in held[1]
    assert clock.t >= second_reset


# --- the weekly (seven-day) window's hold (operator, 2026-10-04): the
# seven-day window holds at `WEEKLY_HOLD_UTILIZATION` (0.99, operator
# 2026-10-08); the five-hour window holds only on overage, never on
# utilization (issue_01M6ABPVXQM5HVWR29JQYZKWMP) — and the later reset when
# both hold ---

def _seed_both_windows(T_mod, run_id, *, five=None, seven=None, is_using_overage=False,
                       date=None):
    """A run directory whose transcript carries `unifiedWindows` for whichever
    of *five* / *seven* (each a `(utilization, resets_at)` pair) is given."""
    d = T_mod.create_run_dir(run_id, date=date or _utc_today())
    windows = {}
    if five is not None:
        windows["five_hour"] = {"utilization": five[0], "resetsAt": five[1]}
    if seven is not None:
        windows["seven_day"] = {"utilization": seven[0], "resetsAt": seven[1]}
    _rl(d, status="allowed", isUsingOverage=is_using_overage, unifiedWindows=windows)
    return d


def test_weekly_alone_at_the_99_threshold_holds_until_its_reset(agentctl):
    now = datetime(2026, 1, 1, tzinfo=timezone.utc)
    resets_at = now.timestamp() + 6 * 24 * 3600
    decision = agentctl._rate_limit_hold_decision(
        None, now=now,
        seven_day=_reading(utilization=0.99, resets_at=resets_at))
    assert decision is not None
    held_until_dt, reason = decision
    assert held_until_dt == datetime.fromtimestamp(resets_at, tz=timezone.utc)
    assert reason == "seven-day window utilization 0.99 >= 0.99"


