def test_the_newest_weekly_reading_decides_the_hold_via_the_real_scan(
        agentctl, tmp_path, monkeypatch):
    """Two unexpired candidates in the same weekly window: the newer transcript
    reads 0.10 and the older 0.99. The newest reading is the current one, so the
    dispatch proceeds. A low line in the newest transcript lifts a hold; that is
    the accepted same-account threat in `_rate_limit_hold_decision`'s Trust text."""
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    now = datetime.now(timezone.utc)
    weekly_reset = int(now.timestamp()) + 6 * 24 * 3600
    older = _seed_both_windows(T, "run-older", seven=(0.99, weekly_reset))
    newer = _seed_both_windows(T, "run-newer", seven=(0.10, weekly_reset))
    os.utime(older / "transcript.jsonl", (now.timestamp() - 60, now.timestamp() - 60))
    os.utime(newer / "transcript.jsonl", (now.timestamp(), now.timestamp()))
    assert _hold_decision_via_both_readers(agentctl, tmp_path, now=now) is None


