# --- the worktree-root directive (issue_01KZ7E0YNV84W55796CZ8ETX6X) ---------
#
# The prompt half of the leak fix. Injected at dispatch for the same reason
# attribution_directive is: the dispatcher knows the resolved path and the agent
# cannot, and appending it last supersedes any root the prompt above established.

def test_the_directive_names_the_actual_worktree_and_the_primary(agentctl, tmp_path):
    wt = tmp_path / "worktrees" / "cartographer.coder-slice-1"
    text = agentctl.worktree_directive(wt, "cartographer")
    assert str(wt) in text
    # The primary is <root>/<repo>, whatever this machine's root is (#553 round 3).
    assert str(agentctl._root() / "cartographer") in text
    assert f"-C {wt}" in text, "git must be told the tree explicitly, not via cwd"


def test_the_directive_is_empty_when_the_run_owns_the_primary(agentctl):
    """A local-agent repo, or an orchestrator dispatched into its own checkout,
    legitimately runs IN the primary. 'The primary is not yours' would be false
    and self-contradictory there, and a directive that is wrong once teaches an
    agent to discount it everywhere."""
    primary = agentctl._root() / "agent-platform"
    assert agentctl.worktree_directive(primary, "agent-platform") == ""


def test_the_directive_names_the_read_a_brief_trap_specifically(agentctl, tmp_path):
    """The measured mechanism: the brief's FIRST instruction handed the run a
    design-doc path in the primary, its first tool call read exactly that path,
    and every path it built afterwards inherited the primary as repo root. A
    generic 'stay in your worktree' does not reach that."""
    text = agentctl.worktree_directive(
        tmp_path / "worktrees" / "cartographer.x", "cartographer")
    assert "not a root to reason from" in text


def test_an_unresolvable_worktree_yields_no_directive(agentctl, monkeypatch):
    """Fail-soft: a directive is worth less than a dispatch, so anything the path
    comparison cannot settle leaves the run exactly as it is today."""
    monkeypatch.setattr(agentctl.Path, "resolve",
                        lambda self, *a, **k: (_ for _ in ()).throw(OSError("nope")))
    assert agentctl.worktree_directive(Path("/tmp/whatever"), "cartographer") == ""


def test_run_session_actually_injects_the_worktree_directive(agentctl):
    """The function being correct is worth nothing if it is never called, and the
    four tests above exercise it directly. Source-level guard in the style of
    test_run_session_wires_arch131_fallback (reviewer, PR #363)."""
    import inspect
    src = inspect.getsource(agentctl._run_session)
    assert "worktree_directive(" in src, \
        "the directive is not wired into the dispatch that appends the system prompt"
    # It must ride the same --append-system-prompt as the agent body, since that
    # is what makes it supersede the paths the prompt above established.
    assert "--append-system-prompt" in src

# --- the primary-mutation guard (issue_01KZ7E0YNV84W55796CZ8ETX6X) ----------
#
# _finalize_run's third downgrade. Unlike the two above it it sits OUTSIDE the
# `exit_status == "completed"` guard, because a run that errored and also trashed
# a checkout still has to say so.

def _mk_primary_for_guard(root, name):
    """A real git repo with one commit — a PRIMARY, since `.git` is a directory."""
    import subprocess as sp
    repo = root / name
    repo.mkdir(parents=True)
    for args in (("init", "-q", "-b", "main"), ("config", "user.email", "t@example.com"),
                 ("config", "user.name", "t")):
        sp.run(["git", "-C", str(repo), *args], check=True, capture_output=True)
    (repo / "README.md").write_text("hi\n")
    sp.run(["git", "-C", str(repo), "add", "-A"], check=True, capture_output=True)
    sp.run(["git", "-C", str(repo), "commit", "-qm", "init"], check=True, capture_output=True)
    return repo


_UNSET = object()


def _stub_guard_signals(monkeypatch, *, boom=False, result=_UNSET):
    """Stub `signal_client.post_alert` for the guard's signal, and return the list of calls.

    The suite's `_no_live_ops_writes` fixture turns an unpatched call into a hard error, so every
    guard test stubs the store. A store that has seen a dedup_key answers `duplicate`, as the real
    one does, unless `result` pins the answer. `result` takes a sentinel default rather than None:
    a test that passes None, the wrong-shape case worth pinning, must get None back, not the healthy
    answer.
    """
    import signal_client
    calls = []
    seen = set()

    def post_alert(stream, body, *, product="platform", dedup_key=None, **kw):
        if boom:
            raise RuntimeError("store down")
        if result is not _UNSET:
            status = result
        elif dedup_key in seen:
            status = "duplicate"
        else:
            seen.add(dedup_key)
            status = "created"
        calls.append({"stream": stream, "body": body, "product": product,
                      "dedup_key": dedup_key, "timeout": kw.get("timeout"),
                      "meta": kw.get("meta"), "status": status})
        return status

    monkeypatch.setattr(signal_client, "post_alert", post_alert)
    return calls


def _guard_run(agentctl, tmp_path, monkeypatch, *, leak, exit_code=0, final_event=None,
               echo_in_worktree=(), dirty=(), cost_stopped_reason=None, repo="cartographer"):
    """Baseline a fake primary root, optionally leak into it, then finalize.

    `echo_in_worktree` writes the same relative paths into the run's OWN worktree,
    which is what makes a leak attributable to this run rather than to whoever
    else shared the window — and therefore what lets it downgrade the run
    (`issue_01KZ94PCSF9HFQ9487FR4A3V5F`). A real leak is the same write landing at
    two roots, so a test asserting a downgrade has to stage both.

    `cost_stopped_reason` lets a caller stage a run that was ALSO cost-capped,
    to pin that the primary-mutation guard still wins (security review, PR #874
    round 1).

    `repo` names the mutated primary (default `cartographer`, every pre-existing
    caller). A caller asserting on the signal's resolved `product` (not just
    the raw `repo` field) needs this to resolve through the registry, which
    `cartographer` does not under the synthetic default (CQ-546) — pass a synthetic
    name like `widget-crew` for that case."""
    import primary_guard as PG
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl.W, "unpublished_commits", lambda wt: 0)
    root = tmp_path / "Convivy"
    root.mkdir()
    primary = _mk_primary_for_guard(root, repo)
    monkeypatch.setattr(PG, "CONVIVY_ROOT", root)

    rd, wt = _mk_run_dir(tmp_path)
    for rel in dirty:  # uncommitted work that exists before the run, for a leak to destroy
        (primary / rel).write_text("uncommitted work")
    agentctl._baseline_primaries(rd, wt)
    leak(primary)
    for rel in echo_in_worktree:
        p = wt / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text("# the same write, right root")
    return rd, wt, agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test", exit_code=exit_code,
        final_event=final_event if final_event is not None
        else {"type": "result", "subtype": "success"},
        profile="agent-platform/daytime", agent={"model_alias": "sonnet"},
        cost_stopped_reason=cost_stopped_reason,
    )


def _status(rd):
    return json.loads((rd / "outcome.json").read_text())["exit_status"]


def test_a_run_that_writes_into_a_primary_is_primary_mutated(agentctl, tmp_path,
                                                             monkeypatch, capsys):
    """The shape the downgrade is for: the same write landed at two roots, so the
    file exists in the run's own worktree AND in the primary. That echo is what
    names this run as the author rather than a bystander that shared the window."""
    _stub_guard_signals(monkeypatch)
    rd, _, _ = _guard_run(agentctl, tmp_path, monkeypatch,
                          leak=lambda p: (p / "leaked.py").write_text("# oops"),
                          echo_in_worktree=("leaked.py",))
    assert _status(rd) == "primary_mutated"
    err = capsys.readouterr().err
    assert "PRIMARY CHECKOUT(S) CHANGED" in err
    assert "leaked.py" in err, "the operator needs the file list, not just a verdict"
    detail = json.loads((rd / "primary_mutations.json").read_text())
    m = detail["mutations"][0]
    assert m["repo"] == "cartographer" and m["added"] == ["leaked.py"]
    assert detail["run_id"] == "run-test"
    assert "concurrent_runs" in detail, "an operator needs to know who shared the window"


def test_a_run_that_touches_nothing_finalizes_normally(agentctl, tmp_path, monkeypatch):
    """The overwhelmingly common case. A guard that fired here would be off in a day."""
    rd, _, _ = _guard_run(agentctl, tmp_path, monkeypatch, leak=lambda p: None)
    assert _status(rd) == "completed"
    assert not (rd / "primary_mutations.json").exists()


