def test_removing_uncommitted_work_from_a_primary_is_caught(agentctl, tmp_path,
                                                           monkeypatch, capsys):
    """`checkout -- .` / `reset --hard` / `git stash` REMOVE dirty entries. Eight
    runs in the irrecoverable class did this; additions-only would miss them all.

    It is caught and FILED rather than caught and failed. A removed file cannot
    echo in the author's worktree — the echo is computed from added paths — so
    this class carries no attribution signal, and before
    `issue_01KZ94PCSF9HFQ9487FR4A3V5F` it failed every run alive at the time while
    naming none of them. The removal still reaches a human; it reaches one who
    can act, instead of failing an arbitrary bystander."""
    import primary_guard as PG
    import subprocess as sp
    issues = _stub_guard_signals(monkeypatch)
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl.W, "unpublished_commits", lambda wt: 0)
    root = tmp_path / "Convivy"
    root.mkdir()
    primary = _mk_primary_for_guard(root, "cartographer")
    (primary / "README.md").write_text("the operator's uncommitted edit\n")
    monkeypatch.setattr(PG, "CONVIVY_ROOT", root)

    rd, wt = _mk_run_dir(tmp_path)
    agentctl._baseline_primaries(rd, wt)
    sp.run(["git", "-C", str(primary), "checkout", "--", "."], check=True,
           capture_output=True)
    agentctl._finalize_run(run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
                           final_event={"type": "result", "subtype": "success"},
                           profile="agent-platform/daytime",
                           agent={"model_alias": "sonnet"})
    assert _status(rd) == "completed", "nobody is attributable, so nobody is failed"
    err = capsys.readouterr().err
    assert "REMOVED entry was uncommitted work whose content is gone unless it also" in err
    assert len(issues) == 1, "and the destruction MUST reach the queue instead"
    assert "REMOVED from the dirty set" in issues[0]["body"]
    assert "README.md" in issues[0]["body"]


# --- who gets failed, and who gets filed (issue_01KZ94PCSF9HFQ9487FR4A3V5F) --
#
# The guard reads the filesystem, so one leak lands in every overlapping run's
# window. #362 chose to RANK rather than filter, reasoning that a guard which
# swallows a real leak to look tidy is worse than one that over-reports. The
# reasoning was right and the cost model was wrong: six runs were marked
# `primary_mutated` across 2026-08-04/05 and five were innocent by the guard's
# own attribution — each report saying so in writing before failing its run.

def test_a_bystanders_run_is_not_failed_for_someone_elses_leak(
        agentctl, tmp_path, monkeypatch, capsys):
    """`run-30aad26a`, verbatim: a reviewer on convivy/knowledge#172 was failed
    because three files left the dirty set in the AGENT-PLATFORM primary — a
    different PR's coder, seven hours earlier. Its own record read "possibly
    ANOTHER run or a human: none of these paths exist in this run's worktree".
    It identified the run as innocent, then failed it."""
    issues = _stub_guard_signals(monkeypatch)
    rd, _, _ = _guard_run(agentctl, tmp_path, monkeypatch,
                          leak=lambda p: (p / "someone-elses.py").write_text("# not mine"))
    assert _status(rd) == "completed", "a bystander keeps its standing"
    err = capsys.readouterr().err
    assert "PRIMARY CHECKOUT(S) CHANGED" in err, "and is still reported, loudly"
    assert "someone-elses.py" in err
    assert len(issues) == 1, "and the change still reaches a human"


def test_the_logged_signal_names_the_run_as_observer_not_author(
        agentctl, tmp_path, monkeypatch):
    """The whole point is that this run is probably innocent, so the issue must
    not re-create in prose the accusation the status change removed."""
    issues = _stub_guard_signals(monkeypatch)
    _guard_run(agentctl, tmp_path, monkeypatch, repo="widget-crew",
               leak=lambda p: (p / "mystery.py").write_text("# whose?"))
    body = issues[0]["body"]
    assert "cannot tell who changed it" in body
    assert "observer rather than the cause" in body
    assert "mystery.py" in body, "an operator needs the path, not just a verdict"
    assert issues[0]["product"] == "widget-crew", "routed to whoever owns the mutated checkout"
    assert "run-test" in issues[0]["body"]


def test_two_runs_in_one_window_log_one_signal_not_two(agentctl, tmp_path, monkeypatch):
    """Otherwise this moves the flooding it removes into a new channel. The
    once_key must be keyed on the CHANGE, so the runs that disagree about their
    own identity still agree about the key."""
    import primary_guard as PG
    keys = []
    for run in ("run-a", "run-b"):
        mp = pytest.MonkeyPatch()
        try:
            issues = _stub_guard_signals(mp)
            mp.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
            mp.setattr(agentctl.W, "unpublished_commits", lambda wt: 0)
            root = tmp_path / run
            root.mkdir()
            primary = _mk_primary_for_guard(root, "cartographer")
            mp.setattr(PG, "CONVIVY_ROOT", root)
            rd, wt = _mk_run_dir(tmp_path / run)
            agentctl._baseline_primaries(rd, wt)
            (primary / "shared-leak.py").write_text("# one cause, two witnesses")
            agentctl._finalize_run(run_dir=rd, worktree=wt, run_id=run, exit_code=0,
                                   final_event={"type": "result", "subtype": "success"},
                                   profile="agent-platform/daytime",
                                   agent={"model_alias": "sonnet"})
            keys.append(issues[0]["dedup_key"])
        finally:
            mp.undo()
    assert keys[0] == keys[1], "one mutation, one key — the queue dedupes on it"


def test_a_store_that_is_down_cannot_break_finalize(agentctl, tmp_path, monkeypatch,
                                                   capsys):
    """Logging is best-effort by design. A run's outcome must not depend on the
    store being up — but the failure has to be LOUD, because with the downgrade
    relaxed this signal is the only thing carrying the finding."""
    _stub_guard_signals(monkeypatch, boom=True)
    rd, _, _ = _guard_run(agentctl, tmp_path, monkeypatch,
                          leak=lambda p: (p / "orphan.py").write_text("# unowned"))
    assert _status(rd) == "completed", "finalize survives"
    err = capsys.readouterr().err
    assert "COULD NOT LOG" in err
    assert "primary_mutations.json" in err, "and points at the only remaining trace"


@pytest.mark.parametrize("bad_return", [None, 42, ["created"], {"status": "created"}])
def test_a_client_returning_the_wrong_shape_cannot_break_finalize(
        agentctl, tmp_path, monkeypatch, capsys, bad_return):
    """A narrower guard around the network call alone still leaves its RETURN
    unguarded: `res.get("status")` on a non-dict raises AttributeError from
    OUTSIDE the try (reviewer, PR #367). Nothing guards the
    `_detect_primary_mutations` call site or `_finalize_run`, so that would lose
    the run's whole recorded outcome — to report a mutation it probably did not
    cause. `post_alert` returns a status string today; best-effort has to be structural."""
    _stub_guard_signals(monkeypatch, result=bad_return)
    rd, _, _ = _guard_run(agentctl, tmp_path, monkeypatch,
                          leak=lambda p: (p / "shapeless.py").write_text("# hm"))
    assert _status(rd) == "completed", "the outcome is recorded whatever the client returns"
    assert "COULD NOT LOG" in capsys.readouterr().err


