def test_the_guard_overrides_committed_not_pushed(agentctl, tmp_path, monkeypatch):
    """committed_not_pushed is the normal healthy end of a worker and `publish
    --run` promotes it back to completed. A run that mutated a primary must not be
    quietly promoted and published, so the leak wins."""
    import primary_guard as PG
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    root = tmp_path / "Convivy"
    root.mkdir()
    primary = _mk_primary_for_guard(root, "cartographer")
    monkeypatch.setattr(PG, "CONVIVY_ROOT", root)

    rd, wt = _mk_run_dir(tmp_path)
    agentctl._baseline_primaries(rd, wt)

    # A genuine committed_not_pushed state: a pre-existing base commit (the
    # started_head.txt snapshot below points at it), a remote configured but not
    # pushed, then this run's own commit on top.
    subprocess.run(["git", "config", "user.email", "bot@example.com"],
                   cwd=str(wt), check=True, capture_output=True)
    subprocess.run(["git", "config", "user.name", "Bot"],
                   cwd=str(wt), check=True, capture_output=True)
    (wt / "base.py").write_text("v = 1\n")
    subprocess.run(["git", "add", "base.py"], cwd=str(wt), check=True, capture_output=True)
    subprocess.run(["git", "commit", "-m", "base"], cwd=str(wt), check=True, capture_output=True)
    head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=str(wt),
                          check=True, capture_output=True, text=True)
    (rd / "started_head.txt").write_text(head.stdout.strip() + "\n")
    bare = tmp_path / "bare.git"
    subprocess.run(["git", "init", "--bare", str(bare)], check=True, capture_output=True)
    subprocess.run(["git", "remote", "add", "origin", str(bare)],
                   cwd=str(wt), check=True, capture_output=True)
    (wt / "fix.py").write_text("# fix\n")
    subprocess.run(["git", "add", "fix.py"], cwd=str(wt), check=True, capture_output=True)
    subprocess.run(["git", "commit", "-m", "fix"], cwd=str(wt), check=True, capture_output=True)

    (primary / "leaked.py").write_text("# oops")
    (wt / "leaked.py").write_text("# oops")     # the echo that names this run
    agentctl._finalize_run(run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
                           final_event={"type": "result", "subtype": "success"},
                           profile="agent-platform/daytime",
                           agent={"model_alias": "sonnet"})
    assert _status(rd) == "primary_mutated"


