    monkeypatch.setattr(PG, "CONVIVY_ROOT", root)

    rd, wt = _mk_run_dir(tmp_path)
    agentctl._baseline_primaries(rd, wt)
    (primary / "committed.md").write_text("human work\n")
    sp.run(["git", "-C", str(primary), "add", "-A"], check=True, capture_output=True)
    sp.run(["git", "-C", str(primary), "commit", "-qm", "human"], check=True,
           capture_output=True)
