# A character that `sanitise_path` removes, placed inside a credential prefix. The name was escaped
# before redaction, so `pass\x01word=` became the text `pass\x01word=`, which `_CRED_PREFIX_RE`
# does not match, and the value reached the body. The name is now redacted before it is escaped.
# Whitespace controls and kept format characters inside a prefix are not covered; see
# `sanitise_path`.
_HIDDEN_IN_PREFIX = [
    ("pass\x01word=Zq9xLm2vTr8w.env", "password=[redacted]"),
    ("pass​word=Zq9xLm2vTr8w.env", "password=[redacted]"),
]


@pytest.mark.parametrize("name,redacted", _HIDDEN_IN_PREFIX)
def test_a_character_sanitise_path_removes_inside_a_prefix_is_redacted(
        agentctl, tmp_path, monkeypatch, name, redacted):
    signals = _stub_guard_signals(monkeypatch)
    _guard_run(agentctl, tmp_path, monkeypatch, dirty=(name,), leak=lambda p: (p / name).unlink())

    assert len(signals) == 1
    assert "Zq9xLm2vTr8w" not in signals[0]["body"]
    assert f"- `{redacted}`" in signals[0]["body"]


@pytest.mark.parametrize("name,redacted", _HIDDEN_IN_PREFIX)
def test_a_character_sanitise_path_removes_inside_a_prefix_is_redacted_in_an_added_path_too(
        agentctl, tmp_path, name, redacted):
    """The added-path bullets had the same order, so the same bypass applied to them."""
    m = _FakeMutation(added=[name])
    m.repo = "cartographer"
    body = agentctl._unattributed_signal_body(
        m, run_id="run-x", agent="coder", worktree=tmp_path / "wt", run_dir=tmp_path / "rd")

