def test_a_corrupted_meta_pid_started_at_cannot_condemn_a_run_whose_registry_entry_is_intact(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """Round 2 of this fix recorded `pid_started_at` in meta.json itself, which
    closed the pid-recycling case but opened a narrower one: meta.json lives in
    the run's own directory, which the run's own Bash tool can write, so a
    single bad write to that ONE field — with the pid left genuinely alive and
    untouched — was on its own enough to make a live run read as dead (security
    review, PR #457 round 2; the prior version of this exact test proved it by
    doing precisely this and asserting EXIT_RUN_FAILED).

    The corroboration source is now the registry, which the run has no path to
    and no reason to write. A run whose registry entry correctly records its
    own start time must not be condemned by a corrupted meta.json field, even
    though the corrupted field is the one `_run_process_gone` used to read."""
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _unfinalized_run(agentctl, T, tmp_path, "run-intact1", pid=os.getpid())
    monkeypatch.setattr(agentctl, "_pid_start_time",
                        lambda pid: "Tue Jan  2 00:00:00 2024")
    # The registry entry — never within the run's reach — records the true
    # start time correctly.
    R.add_run({"run_id": "run-intact1", "agent": "reviewer", "task": "t",
               "started_at": T.now_iso(), "repo": "convivy/x",
               "worktree": str(tmp_path), "pid": os.getpid(),
               "pid_started_at": "Tue Jan  2 00:00:00 2024"})
    # meta.json — which the run itself could have written — is corrupted with
    # a mismatching value, simulating exactly the round-2 attack.
    T.update_meta(d, pid_started_at="Mon Jan  1 00:00:00 2024")

    rc = agentctl._wait_for_runs(["run-intact1"], timeout=0.05, poll=0.01)
    err = capsys.readouterr().err
    assert rc == 2, (
        "a live, genuine pid must keep waiting even when meta.json's "
        "pid_started_at is corrupted, as long as the registry entry is intact")
    assert "DIED WITHOUT FINALIZING" not in err


def test_a_finalized_run_is_never_called_vanished(
        agentctl, tmp_path, monkeypatch, capsys):
    """The ordinary success path, with a dead pid — which is every finished run.

    `_finalize_run` writes the outcome from inside the process, so by the time a
    caller sees a completed run its pid is ALWAYS gone. A liveness check that did
    not test outcome.json first would call every successful run in the fleet a
    death."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _finished_run(agentctl, T, tmp_path, "run-ok0001", "completed")
    T.update_meta(d, pid=999999)

    rc = agentctl._wait_for_runs(["run-ok0001"], timeout=30, poll=0.01)
    out, err = capsys.readouterr()
    assert rc == 0
    assert "DIED WITHOUT FINALIZING" not in err
    assert "completed" in out


def test_one_vanished_run_does_not_crash_the_report_for_the_batch(
        agentctl, tmp_path, monkeypatch, capsys):
    """`failed` is empty when the only bad news is a vanished run, and the final
    line used to index `failed[0][0]` unconditionally.

    A waiter that raises here reports nothing at all about any run in the batch —
    strictly worse than the silence it was fixing."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    _unfinalized_run(agentctl, T, tmp_path, "run-gone002", pid=999999)
    _finished_run(agentctl, T, tmp_path, "run-fine01", "completed")

    rc = agentctl._wait_for_runs(["run-gone002", "run-fine01"], timeout=30, poll=0.01)
    out, err = capsys.readouterr()
    assert rc == agentctl.EXIT_RUN_FAILED
    assert "run-gone002" in err
    assert "run-fine01" in out, "the healthy run in the batch must still report"
    assert "agentctl status run-gone002" in err, "and the detail line must name one"


def test_wait_sweeps_a_vanished_runs_tool_session_holders_and_removes_its_scratch_dir(
        agentctl, tmp_path, monkeypatch):
    """CQ·138: the vanished-run branch `_wait_for_runs`
    added (right where it prints `died-unfinalized`) is the only termination
    path in this PR with no test of its own — `test_the_tool_session_scratch_dir_is_removed_once_the_run_is_finalized`
    covers the in-process finalize, and
    `test_terminate_run_signals_tool_session_holders_and_removes_the_scratch_dir`
    covers `agentctl kill`'s own path; this is the third and last. Same real
    zsh holder shell as both of those, on a run `_unfinalized_run` leaves with
    no `outcome.json` and a dead pid, so `_wait_for_runs` confirms it vanished
    and takes the `elif rid in vanished:` branch. Passes against 8b45d29a,
    where the branch already sweeps and removes; it would fail with the
    holder left alive and the scratch directory still present against any
    version of that branch missing either call."""
    assert _ZSH, "no zsh on PATH; the CI runner must install it"
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    run_dir = _unfinalized_run(agentctl, T, tmp_path, "run-vanish-ts1", pid=999999)
    scratch_dir = tmp_path / "vanish-toolsession-scratch"
    scratch_dir.mkdir()
    marker = agentctl.RS.create_tool_session_marker(scratch_dir)
    agentctl._record_tool_session_marker(run_dir, marker)

    cmd = f'exec 9>>{marker}; sleep 30 & disown'
    holder_shell = subprocess.Popen([_ZSH, "-c", cmd], start_new_session=True)
    holder_shell.wait(timeout=5)
    holders = _wait_for_holder(agentctl, marker)
    assert holders, "no process held this run's own marker open"
    holder_pid = holders[0]

    try:
        rc = agentctl._wait_for_runs(["run-vanish-ts1"], timeout=30, poll=0.01)

        assert rc == agentctl.EXIT_RUN_FAILED
        assert not _alive(holder_pid), (
            "agentctl wait's vanished-run path left the tool-session holder alive")
        assert not scratch_dir.exists(), (
            "agentctl wait's vanished-run path never removed the scratch directory")
    finally:
        if _alive(holder_pid):
            os.kill(holder_pid, signal.SIGKILL)


def test_wait_survives_a_slow_finalize_when_the_dispatcher_is_still_alive(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """The false-death race issue_01M1A3B1GQ54207ZYT1NMSVKPY exists to close.

    The claude CHILD's pid can go away well before `_finalize_run` — running in
    the DISPATCHER process — gets around to writing outcome.json. Ten runs on
    2026-09-22 alone took longer than `_DEAD_POLLS_TO_CONFIRM` (2 polls) to
    finalize and were reported `died-unfinalized` even though every one of them
    had genuinely completed.

    Simulated here: the child pid is dead from the very first poll, this test's
    own pid is recorded as the REGISTRY's `dispatcher_pid` (alive by
    construction — `_died_without_finalizing` no longer reads meta.json's copy
    for liveness, see PR #641 round 1), and outcome.json is written only after
    five polls have already passed — more than enough to have condemned this
    run under the old child-pid-only check. As long as the dispatcher is
    alive, the wait must keep waiting, however many polls that takes, and must
    pick up the real result once it lands.
    """
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _unfinalized_run(agentctl, T, tmp_path, "run-slowfin1", pid=999999)
    R.add_run({"run_id": "run-slowfin1", "agent": "reviewer", "task": "t",
               "started_at": T.now_iso(), "repo": "convivy/x",
               "worktree": str(tmp_path), "pid": 999999,
               "dispatcher_pid": os.getpid(),
               "dispatcher_pid_started_at": agentctl._pid_start_time(os.getpid())})

    polls = []

    def _finalize_after_five_polls(_s):
        polls.append(1)
        if len(polls) == 5:
            T.write_outcome(d, exit_status="completed")

    # Patches the loop's own per-poll seam, not plain `time.sleep` — see
    # `_wait_poll_sleep`'s docstring (CQ·523, PR #955 round 2).
    monkeypatch.setattr(agentctl, "_wait_poll_sleep", _finalize_after_five_polls)

    rc = agentctl._wait_for_runs(["run-slowfin1"], timeout=5, poll=0.01)
    out, err = capsys.readouterr()
    assert rc == 0, (
        "the dispatcher stayed alive the whole time; a slow finalize is not a "
        "death")
    assert "DIED WITHOUT FINALIZING" not in err
    assert "completed" in out


def test_wait_survives_another_process_reaping_the_registry_mid_finalize(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """CQ·523, the actual occurrence: deck-security-reviewer run-db823743 had
    its registry entry reaped at 14:35:11Z while its dispatcher (pid 43475)
    was still finalizing and wrote outcome.json two seconds later —
    `agentctl wait` exited 4 with DIED WITHOUT FINALIZING anyway, because the
    reap dropped the only place `_died_without_finalizing` could read
    `dispatcher_pid` from.

    Simulated here: the child pid is dead from the first poll, and mid-wait
    something else running on the machine calls `registry.reap_stale()`
    directly — exactly what `add_run`, `can_spawn` and `list_runs` also do
    internally, any of which could run from an unrelated `agentctl spawn` on
    the same box. As long as the dispatcher (this test's own pid) is alive
    and corroborated, that reap must leave the entry in place, and the wait
    must keep polling until the real outcome.json lands rather than reading
    the now-missing entry as a dead run.

    The fake sleep below patches `agentctl._wait_poll_sleep`, not plain
    `time.sleep`. Round 1 of this PR patched `agentctl.time.sleep` instead —
    the same global `time` module every `subprocess.run(..., timeout=...)`
    wait loop polls through — so `R.reap_stale()`'s own `_pid_start_time` probe
    (a `ps` subprocess) re-entered this very function on each of its internal
    sleeps, which called `R.reap_stale()` again, which blocked forever trying
    to retake the `flock` its own outer call already held. That hung CI for
    close to an hour (CQ·523, PR #955 round 2, CI run 39547181988) before the
    600s faulthandler dump named the deadlock. `_wait_poll_sleep` is a seam
    only `_wait_for_runs`'s own poll loop reads, so patching it does not touch
    the subprocess wait loops `_pid_start_time` runs through."""
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _unfinalized_run(agentctl, T, tmp_path, "run-reapedmid1", pid=999999)
    R.add_run({"run_id": "run-reapedmid1", "agent": "reviewer", "task": "t",
               "started_at": T.now_iso(), "repo": "convivy/x",
               "worktree": str(tmp_path), "pid": 999999,
               "dispatcher_pid": os.getpid(),
               "dispatcher_pid_started_at": agentctl._pid_start_time(os.getpid())})

    polls = []

    def _reap_then_finalize_after_three_polls(_s):
        polls.append(1)
        R.reap_stale()  # another process's registry write, mid-finalize
        if len(polls) == 3:
            T.write_outcome(d, exit_status="completed")

    monkeypatch.setattr(agentctl, "_wait_poll_sleep", _reap_then_finalize_after_three_polls)

    rc = agentctl._wait_for_runs(["run-reapedmid1"], timeout=5, poll=0.01)
    out, err = capsys.readouterr()

    assert rc == 0, (
        "a reap_stale by another process must not make a dispatcher-alive "
        "run read as dead")
    assert "DIED WITHOUT FINALIZING" not in err
    assert "completed" in out
    assert R.get_run("run-reapedmid1") is not None, (
        "the registry entry itself must have survived every reap_stale call "
        "made while the dispatcher was still alive")


def test_wait_still_detects_a_true_death_when_both_pids_are_gone(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """Requiring the dispatcher pid too must not quietly disable death detection.

    A run whose claude child AND whose dispatcher are both gone, with no
    outcome.json ever appearing, is exactly the case `_died_without_finalizing`
    exists to catch — twenty such runs over July-August 2026, ten of them
    reviewers, went unnoticed before this check existed at all. Requiring a
    second pid to also be gone must still report a genuine double-death as
    vanished; it must not turn into a second way for a real death to hide.

    (This scenario was never the false-death bug — a dead child pid with no
    outcome.json already read as dead before this fix, and still does. It is
    recorded here as the fix's own DoD, not as a regression case.)
    """
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    _unfinalized_run(agentctl, T, tmp_path, "run-bothgone1", pid=999999)
    R.add_run({"run_id": "run-bothgone1", "agent": "reviewer", "task": "t",
               "started_at": T.now_iso(), "repo": "convivy/x",
               "worktree": str(tmp_path), "pid": 999999,
               "dispatcher_pid": 999998})  # a pid nothing owns either

    rc = agentctl._wait_for_runs(["run-bothgone1"], timeout=30, poll=0.01)
    err = capsys.readouterr().err
    assert rc == agentctl.EXIT_RUN_FAILED
    assert "DIED WITHOUT FINALIZING" in err


def test_dispatcher_pid_tampering_in_meta_json_cannot_hide_a_real_death(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """meta.json's `dispatcher_pid` is same-UID writable by the run's own Bash
    tool — `AGENTCTL_RUN_DIR` hands the run its own directory's path directly —
    so trusting a value read back from there for liveness reopens exactly the
    gap PR #457 closed for the child pid: a decoy long-lived pid written there
    would keep `_died_without_finalizing` from ever confirming a real death
    (security review, PR #641 round 1).

    The REGISTRY — flock-protected, never exported into a run's environment —
    holds the real dispatcher pid, already dead. meta.json is then tampered
    with a live, unrelated pid (this test process's own, alive by
    construction) the way a run's own Bash tool could tamper it. The registry
    entry must be what `_died_without_finalizing` trusts, not the tampered
    meta.json copy.
    """
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _unfinalized_run(agentctl, T, tmp_path, "run-tamper01", pid=999999)
    R.add_run({"run_id": "run-tamper01", "agent": "reviewer", "task": "t",
               "started_at": T.now_iso(), "repo": "convivy/x",
               "worktree": str(tmp_path), "pid": 999999,
               "dispatcher_pid": 999998})  # the real dispatcher: a pid nothing owns
    # Same-UID tampering: meta.json's dispatcher_pid is overwritten with a
    # live, unrelated pid — a decoy the run itself could start and record.
    T.update_meta(d, dispatcher_pid=os.getpid())

    rc = agentctl._wait_for_runs(["run-tamper01"], timeout=30, poll=0.01)
    err = capsys.readouterr().err
    assert rc == agentctl.EXIT_RUN_FAILED, (
        "a decoy live pid written into meta.json must not mask a death the "
        "registry's own dispatcher_pid entry shows as gone")
    assert "DIED WITHOUT FINALIZING" in err


# ---------------------------------------------------------------------------
# `agentctl close-orphaned-runs` — the operator-run close-out for records
# already stuck in the died-before-its-pid-was-recorded shape.
# ---------------------------------------------------------------------------

def _orphaned_run(T, tmp_path, run_id, *, date="2026-09-03"):
    """A run dir in exactly the 21 runs' shape: meta.json with `pid: null`, no
    outcome.json, no transcript content — and (the caller's job) no registry
    trace either."""
    d = T.create_run_dir(run_id, date=date)
    T.write_meta(d, run_id=run_id, agent="reviewer", task="t",
                started_at=T.now_iso(), repo="convivy/x", worktree=str(tmp_path),
                profile="p", model="claude-sonnet-5")
    return d


def test_close_orphaned_runs_dry_run_lists_without_touching_anything(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """Default dry run: nothing written, the matched run named in the listing."""
    from types import SimpleNamespace
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(agentctl, "_usage_hold_currently_live", lambda: False)
    # The scan now confirms a missing registry entry against outcome.json the
    # same way `agentctl wait`/`cmd_status` do (round 1 of #970) — faked out
    # here, as elsewhere, so this test still runs in milliseconds.
    monkeypatch.setattr(agentctl, "_confirm_poll_sleep", lambda s: None)
    d = _orphaned_run(T, tmp_path, "run-0ff51496")

    rc = agentctl.cmd_close_orphaned_runs(SimpleNamespace(apply=False))
    out = capsys.readouterr().out
    assert rc == 0
    assert "run-0ff51496" in out
    assert "dry-run" in out
    # pid=null and transcript_bytes=0 are what tell this run's shape apart, before
    # applying, from the 27 main-branch runs that recorded a pid and ran for a
    # while (agent-platform#970's dry run conflated both under one listing).
    assert "pid=null" in out
    assert "transcript_bytes=0" in out
    assert not (d / "outcome.json").exists(), "a dry run must never write outcome.json"
    assert not (d / "cost.json").exists(), "a dry run must never write cost.json"


def test_close_orphaned_runs_apply_writes_a_failed_zero_cost_outcome(
        agentctl, tmp_path, monkeypatch, capsys, runs_root):
    """`--apply` writes the shape `_finalize_run` would have for a
    died-unfinalized run: an exit_status `WAIT_FAILURE_STATUSES` already
    treats as a failure, and $0 cost — no gateway spend log and no transcript
    exist for any of the 21 runs motivating this command. The registry entry
    (if any) is cleared too."""
    from types import SimpleNamespace
    import registry as R
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(agentctl, "_usage_hold_currently_live", lambda: False)
    monkeypatch.setattr(agentctl, "_confirm_poll_sleep", lambda s: None)
    d = _orphaned_run(T, tmp_path, "run-8315add2")

    rc = agentctl.cmd_close_orphaned_runs(SimpleNamespace(apply=True))
    out = capsys.readouterr().out
    assert rc == 0
    assert "closed run-8315add2" in out

