# --- a leaked path reaches the auto-filed issue verbatim (PR #608) -----------
#
# The guard reads `git status` with `-z`, which turns git's C-quoting OFF, so a
# path now arrives exactly as it sits on disk. A Unix filename may hold a
# newline, a tab or a backtick, and these two bodies are markdown posted
# unattended to the queue, one bullet per line. Before `-z`, git quoted all of
# it away and the one-bullet-per-line assumption held by accident.

class _FakeMutation:
    """Only the fields the two formatters read."""
    def __init__(self, added=(), removed=()):
        self.repo = "victim"
        self.added = tuple(added)
        self.removed = tuple(removed)
        self.head_before = None
        self.head_after = None
        self.orphaned_head = False


@pytest.mark.parametrize("raw,escaped", [
    ("evil.py\n\n# forged heading", "evil.py\\n\\n# forged heading"),
    ("close`span.py", "close\\x60span.py"),
    ("tab\there.py", "tab\\there.py"),
    ("carriage\rreturn.py", "carriage\\rreturn.py"),
    ("bell\x07.py", "bell\\x07.py"),
    ("back\\slash.py", "back\\\\slash.py"),
])
def test_a_path_cannot_inject_markup_into_a_logged_signal(agentctl, raw, escaped):
    assert agentctl._md_path(raw) == escaped


def test_the_mutation_body_keeps_one_bullet_per_path(agentctl, tmp_path):
    """The injection this closes: a filename holding a newline would otherwise
    become two lines of an auto-posted issue, the second of them attacker-chosen
    markdown outside any code span."""
    injected = "evil.py\n\n# I am a forged heading"
    m = _FakeMutation(added=[injected], removed=["also`bad.py"])
    body = agentctl._unattributed_signal_body(
        m, run_id="run-x", agent="coder",
        worktree=tmp_path / "wt", run_dir=tmp_path / "rd")

    # The forged text survives as CONTENT, on one line inside the code span —
    # what must not survive is its own LINE, which is what markdown would render
    # as a heading. The name is cleaned before it is escaped, so its newlines
    # collapse to spaces here, not to the escaped `\n`.
    assert "- `evil.py # I am a forged heading`" in body
    assert "- `also\\x60bad.py`" in body
    assert not any(ln.lstrip().startswith("#") for ln in body.splitlines()), \
        "no line of the body may be attacker-chosen markup"
    # Every bullet this body emits holds exactly one path, and every path is on
    # exactly one bullet.
    bullets = [ln for ln in body.splitlines() if ln.startswith("- `")]
    assert len(bullets) == 2, bullets
    assert all(ln.endswith("`") for ln in bullets), bullets


def test_an_ordinary_path_is_left_alone(agentctl):
    """Escaping must not disturb the paths an operator actually sees, including
    the non-ASCII names `-z` was adopted to record exactly."""
    for p in ("app/services/client.py", "naïve.py", "with space.py", 'quo"te.py'):
        assert agentctl._md_path(p) == p


# ---------------------------------------------------------------------------
# Restoring what the DISPATCHER suppressed, before it reaches the PR.
#
# The suppression deletes CLAUDE.md/AGENTS.md from a dispatch worktree and
# leaves the deletion visible to git on purpose. `_is_platform_suppression`
# exempts that porcelain line in the status-READING paths, and nothing
# constrains what the agent's `git commit -a` stages — so the deletion rides
# into the commit and reaches the PR. Seen twice in convivy-orient on
# 2026-09-18; both caught by a reviewer reading the file list.
# ---------------------------------------------------------------------------

def _dispatch_repo(tmp_path, name="origin-repo"):
    """A base repo plus a linked worktree on its own branch, both with AGENTS.md."""
    import subprocess as sp
    primary = tmp_path / name
    primary.mkdir()
    sp.run(["git", "init", "-q", "-b", "main"], cwd=primary, check=True)
    sp.run(["git", "config", "user.email", "t@t.t"], cwd=primary, check=True)
    sp.run(["git", "config", "user.name", "t"], cwd=primary, check=True)
    (primary / "AGENTS.md").write_text("never push to main\nnever print jwt.json\n")
    (primary / "app.py").write_text("code\n")
    sp.run(["git", "add", "-A"], cwd=primary, check=True)
    sp.run(["git", "commit", "-qm", "init"], cwd=primary, check=True)
    wt = tmp_path / "wt"
    sp.run(["git", "worktree", "add", "-q", "-b", "feature", str(wt)], cwd=primary, check=True)
    sp.run(["git", "config", "user.email", "t@t.t"], cwd=wt, check=True)
    sp.run(["git", "config", "user.name", "t"], cwd=wt, check=True)
    return primary, wt


def _git_in(wt):
    import subprocess as sp
    def git(*a):
        return sp.run(["git", "-C", str(wt), *a], capture_output=True, text=True)
    return git


def _deletes_agents_md(git, base="main"):
    """True when the branch's diff against base DELETES AGENTS.md — what a PR shows."""
    cp = git("diff", "--name-only", "--diff-filter=D", f"{base}...HEAD")
    return "AGENTS.md" in cp.stdout.split()


def test_a_commit_a_sweeps_the_dispatchers_deletion_into_the_branch(agentctl, tmp_path,
                                                                    monkeypatch):
    """THE DEFECT ITSELF, pinned so the fix below is measured against it.

    Without this the other tests could pass by the deletion never happening.
    """
    _, wt = _dispatch_repo(tmp_path)
    monkeypatch.setattr(agentctl.W, "is_primary_checkout", lambda repo, path: False)
    assert agentctl.suppress_repo_instructions("demo", wt) == ["AGENTS.md"]
    git = _git_in(wt)
