# --- a model set on a work item (model-lane epic issue_01M35KQ8WTW8R3WSKXS81TV2DZ,
# slice 2): `spawn --issue` reads the item's `model_choice` (written only through
# the Library's client-gated route) and honours it. The Library vouches for the
# CLIENT; `acting_human` is a claim. ---------------------------------------------

def _item_with_model(*, client="orient", actor="operator", model="opus", reason="needs depth"):
    return {"id": "issue_X", "model_choice": {
        "model": model, "reason": reason, "set_by_client": client,
        "acting_human": actor, "set_at": "2026-09-23T00:00:00Z"}}


def _item_spawn_args(*, model=None, reason=None, issue="issue_X", parent=None):
    import types
    return types.SimpleNamespace(
        agent="reviewer", task="t", on="widget-crew", profile=None,
        agents_dir=None, parent=parent, pr=None, review_sha=None,
        model=model, reason=reason, issue=issue,
    )


def _item_dispatch_env(agentctl, monkeypatch, *, item, origin="scheduled", fetch_why=None):
    """Stub everything up to R.can_spawn; returns a dict that records whether the
    dispatch got past the model resolution (`reached`) and how many times the
    Library was read (`fetches`)."""
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: origin)
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_reachable", lambda **kw: True)
    seen = {"reached": False, "fetches": 0}

    def _fetch(issue_id):
        seen["fetches"] += 1
        return (None, fetch_why) if fetch_why else (item, None)
    # raising=False: the seam is new, and a test that names a missing attribute
    # errors at setup instead of failing on the behaviour it asserts.
    monkeypatch.setattr(agentctl, "_fetch_work_item", _fetch, raising=False)

    def _can_spawn(*a, **kw):
        seen["reached"] = True
        return False, [], "stopped here on purpose"
    monkeypatch.setattr(agentctl.R, "can_spawn", _can_spawn)
    return seen


def test_dispatch_honours_an_item_model_choice_on_an_autonomous_origin(
        agentctl, monkeypatch, tmp_path):
    seen = _item_dispatch_env(agentctl, monkeypatch, item=_item_with_model())
    args = _item_spawn_args()
    agentctl.cmd_spawn(args)
    assert seen["reached"], "a model_choice was refused on origin"
    assert agentctl.model_id(args.model) == "claude-opus-5-5"
    assert args.reason == "needs depth"


