# --- primary-routed agents get their own detached worktree at origin/main ----
# `derive_purpose` returns None for scout, planner, curator and every agent
# outside the dedicated-worktree list, and those used to run in the repo's
# PRIMARY checkout on whatever `.claude` its co had rendered: the dispatched-only
# blocks their `--agent` render selects never reached them, `docs_consulted.json`
# recorded the co's documents as theirs, and (before agent-platform#672 skipped
# the render) the co that ran `spawn scout --on <its own repo>` had its own
# instructions overwritten. They now allocate a spawn-owned detached worktree at
# `refs/remotes/origin/main` and take the ordinary render.

class _StopAfterRender(Exception):
    """Raised by the first thing `_spawn_dispatch` does after the render step."""


_KCTX_STUB = '''#!{python}
import importlib.machinery, importlib.util, json, pathlib, sys
loader = importlib.machinery.SourceFileLoader("kx", {kx!r})
spec = importlib.util.spec_from_loader("kx", loader)
kx = importlib.util.module_from_spec(spec)
loader.exec_module(kx)
cwd = pathlib.Path.cwd()
argv = sys.argv[1:]
agent = argv[argv.index("--agent") + 1] if "--agent" in argv else None
# The REAL predicate decides which render this is: an --agent render into a tree
# knowledge-ctx recognises as spawn-owned is the dispatched (bundle) render.
dispatched = bool(agent) and kx._is_spawn_owned_worktree(cwd)
with open({log!r}, "a") as fh:
    fh.write(json.dumps({{"cwd": str(cwd), "argv": argv, "dispatched": dispatched}}) + "\\n")
claude = cwd / ".claude"
(claude / "agents").mkdir(parents=True, exist_ok=True)
owned = ["CLAUDE.md", ".materialized"]
(claude / "CLAUDE.md").write_text(
    f"DISPATCHED RENDER for {{agent}}\\n" if dispatched else "WHOLE PROFILE RENDER\\n")
if dispatched:
    (claude / "agents" / f"{{agent}}.md").write_text("x")
    owned.append(f"agents/{{agent}}.md")
(claude / ".materialized").write_text("\\n".join(owned) + "\\n")
'''


def _git_ok(cwd, *args):
    return subprocess.run(["git", *args], cwd=str(cwd), check=True,
                          capture_output=True, text=True).stdout.strip()


def _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, *, agent,
                         with_origin=True, resolved=None, repo="demo", is_private=False):
    """A tmp root holding a primary `demo` with a bare remote whose main is one
    commit AHEAD of the primary's local main, and a stub knowledge-ctx that runs
    the real `_is_spawn_owned_worktree`. `with_origin=False` builds the primary
    the way a repo with no origin remote is, such as LEDGER, a commercial
    workspace, cartographer-commercial or a private crew: one local `main`,
    no remote.
    `resolved` is merged into the agent `resolve_agent` returns (for
    `local`). `repo` names the primary directory and `--on` value (default
    `demo`, every pre-existing caller). `is_private` is the fixed answer
    `_is_private_dispatch` is monkeypatched to return; pass `None` to leave the
    real one in place instead, reading `repo` against the shared default
    registry (`tests/conftest.py`'s `example-private-crew` row, for a test that
    needs the genuine privacy check rather than a fixed stand-in). Returns a
    namespace of the moving parts."""
    import types
    for k, v in {"GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@example.com",
                 "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@example.com",
                 "GIT_CONFIG_GLOBAL": os.devnull, "GIT_CONFIG_NOSYSTEM": "1"}.items():
        monkeypatch.setenv(k, v)
    root = tmp_path / "root"
    primary = root / repo
    primary.mkdir(parents=True)
    remote = tmp_path / "remote.git"
    _git_ok(tmp_path, "init", "-q", "--bare", "-b", "main", str(remote))
    _git_ok(primary, "init", "-q", "-b", "main")
    (primary / "README.md").write_text("one\n")
    _git_ok(primary, "add", "-A")
    _git_ok(primary, "commit", "-q", "-m", "one")
    if with_origin:
        _git_ok(primary, "remote", "add", "origin", str(remote))
        _git_ok(primary, "push", "-q", "-u", "origin", "main")
        other = tmp_path / "other"
        _git_ok(tmp_path, "clone", "-q", str(remote), str(other))
        (other / "README.md").write_text("two\n")
        _git_ok(other, "commit", "-qam", "two")
        _git_ok(other, "push", "-q", "origin", "main")
        _git_ok(primary, "fetch", "-q", "origin")
    local_main = _git_ok(primary, "rev-parse", "refs/heads/main")
    if with_origin:
        remote_main = _git_ok(primary, "rev-parse", "refs/remotes/origin/main")
        assert local_main != remote_main
    else:
        remote_main = None
        assert _git_ok(primary, "remote") == ""

    # The co's own interactive render, which no dispatch may touch.
    (primary / ".claude" / "agents").mkdir(parents=True)
    (primary / ".claude" / "CLAUDE.md").write_text("INTERACTIVE CO RENDER\n")
    (primary / ".claude" / ".profile-documents.json").write_text('{"interactive": true}\n')
    (primary / ".claude" / "agents" / "co-only.md").write_text("the co's agent\n")

    log = tmp_path / "kctx.log"
    stub = tmp_path / "knowledge-ctx"
    stub.write_text(_KCTX_STUB.format(
        python=sys.executable, kx=str(Path(__file__).resolve().parent.parent
                                      / "bin" / "knowledge-ctx"), log=str(log)))
    stub.chmod(0o755)

    monkeypatch.setattr(agentctl.W, "CONVIVY_ROOT", root)
    # `projects.crews_root()` (ADR-0043's fourth surface: `_private_run_root`
    # resolves a private dispatch's own home via `projects.home_path`, which
    # expands a registry `home_dir` of "<root>/..." against this) must agree
    # with `W.CONVIVY_ROOT` above, or a private-repo dispatch through this
    # fixture (`example-private-repo`, tests/conftest.py's synthetic registry
    # row) would resolve its run-corpus root under the REAL machine's home
    # directory instead of this test's own `root` — and then create it there.
    monkeypatch.setattr(agentctl.projects, "ROOT_OVERRIDE", root)
    monkeypatch.setattr(agentctl, "KNOWLEDGE_CTX", stub)
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None:
                        {"model_alias": "sonnet", "body": "sys", **(resolved or {})})
    monkeypatch.setattr(agentctl, "_budget_gate", lambda *a, **kw: None)
    # The real registry lookup reads the operator's projects index; a tmp repo is
    # not private unless a test says so. `is_private=None` leaves the real
    # `_is_private_dispatch` (and the registry read behind it) in place.
    if is_private is not None:
        monkeypatch.setattr(agentctl, "_is_private_dispatch",
                            lambda r, a: is_private)
    # No real `gh`/network here; a test exercising the open-PR refusal itself
    # overrides this back to something that returns a PR, or raises.
    monkeypatch.setattr(agentctl, "_gh_open_pr_for_branch", lambda branch, repo, env=None: None)

    def _stop(*a, **kw):
        raise _StopAfterRender()
    monkeypatch.setattr(agentctl.T, "create_run_dir", _stop)
    args = types.SimpleNamespace(
        agent=agent, task="find the thing", on=repo, profile=f"{repo}/daytime",
        agents_dir=None, parent=None, pr=None, review_sha=None, model=None,
        reason=None, issue=None, dry_run=False, force=False, reviewer=None,
        label=None, detach=False, foreground=True, wait=False)
    return types.SimpleNamespace(root=root, primary=primary, log=log, args=args,
                                 local_main=local_main, remote_main=remote_main)


def _dispatch_to_the_render(agentctl, s):
    """Run the real `_spawn_dispatch` through allocation and the render; returns
    the allocated worktree (the one `knowledge-ctx` was invoked in)."""
    with pytest.raises(_StopAfterRender):
        agentctl._spawn_dispatch(s.args)
    assert s.log.exists(), "knowledge-ctx never ran: the dispatch rendered nothing"
    calls = [json.loads(ln) for ln in s.log.read_text().splitlines()]
    assert len(calls) == 1, calls
    return Path(calls[0]["cwd"]), calls[0]


def _primary_claude_bytes(primary):
    return {str(p.relative_to(primary)): p.read_bytes()
            for p in sorted((primary / ".claude").rglob("*")) if p.is_file()}


@pytest.mark.parametrize("agent", ["scout", "planner", "curator"])
def test_a_primary_routed_agent_gets_a_detached_worktree_at_the_remote_tracking_main(
        agentctl, tmp_path, monkeypatch, runs_root, agent):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent=agent)
    before = _primary_claude_bytes(s.primary)
    wt, call = _dispatch_to_the_render(agentctl, s)
    assert wt.resolve() != s.primary.resolve()
    assert wt.resolve().parent == (s.root / "worktrees").resolve()
    # exactly the remote-tracking main, not the primary's (older) local main
    assert _git_ok(wt, "rev-parse", "HEAD") == s.remote_main != s.local_main
    # detached: no branch was created for it
    assert subprocess.run(["git", "symbolic-ref", "-q", "HEAD"], cwd=str(wt),
                          capture_output=True).returncode != 0
    assert _git_ok(s.primary, "branch", "--list", "agent/*") == ""
    # the co's render survives byte-for-byte and knowledge-ctx never ran there
    assert _primary_claude_bytes(s.primary) == before
    assert Path(call["cwd"]).resolve() != s.primary.resolve()


def test_a_primary_routed_agent_is_rendered_with_its_own_dispatched_render(
        agentctl, tmp_path, monkeypatch, runs_root):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    wt, call = _dispatch_to_the_render(agentctl, s)
    assert call["argv"][:3] == ["use", "daytime", "--force"]
    assert call["argv"][call["argv"].index("--agent") + 1] == "scout"
    assert call["dispatched"] is True, "knowledge-ctx did not see a spawn-owned worktree"
    assert (wt / ".claude" / "CLAUDE.md").read_text() == "DISPATCHED RENDER for scout\n"


def test_docs_consulted_lists_the_worktrees_own_render_not_the_cos(
        agentctl, tmp_path, monkeypatch, runs_root):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    wt, _ = _dispatch_to_the_render(agentctl, s)
    rd, _own_wt = _mk_run_dir(tmp_path)
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl.W, "unpublished_commits", lambda w: 0)
    agentctl._finalize_run(run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
                           final_event={"type": "result", "subtype": "success"},
                           profile="demo/daytime", agent={"model_alias": "sonnet"})
    consulted = json.loads((rd / "docs_consulted.json").read_text())
    assert consulted["individuated_at_activation"]["agents"] == ["scout"]
    assert "co-only" not in json.dumps(consulted)


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()


def test_finalize_run_records_the_full_document_set_after_the_worktree_is_gone(
        agentctl, knowledge_ctx, tmp_path, monkeypatch):
    """work item issue_01M3BFGE9QE8339CK5RNVP5XQC: `docs_consulted.json`'s
    `docs` key must list the agent file, a skill, an instruction block and a
    profile document the run was given — each with its id, kind and
    body_sha256 (the instruction block also with its scope) — and the run
    directory's own record must already hold it by the time `_finalize_run`
    returns, since `.profile-documents.json` lives only in the worktree,
    which ARCH-344 later reaps.

    Runs the REAL `individuate()` (not a hand-built `.profile-documents.json`)
    so the hashing formula and `_materialized_documents`'s reader are proven
    against each other, not against two independently-typed fixtures that
    could silently drift apart (reviewer, PR #740 round 1). The capture
    itself happens through `agentctl._materialized_documents(wt)` called
    right after `individuate()`, mirroring exactly where `_spawn_dispatch`
    calls it — at dispatch time, before any subprocess exists — and the
    result is threaded into `_finalize_run` as a parameter, never re-read
    from the worktree inside it."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)

    # The Library serves each row's body; the checkout is never read.
    monkeypatch.setattr(knowledge_ctx, "KNOWLEDGE", tmp_path / "no-knowledge-checkout")
    decision_body = "Memory pressure reaper is off.\n"
    served = {
        "agent-platform/agents/coder": ("agent", "Fix the bug.\n"),
        "agent-platform/skills/run": ("skill", "Run the thing.\n"),
        "platform/decisions/0082": ("decision", decision_body),
    }
    rows = [
        {"id": doc_id, "kind": kind, "project": doc_id.split("/")[0],
         "source_ref": f"{doc_id}.md", "title": doc_id.rsplit("/", 1)[-1],
         "body": body, "_bundle": {"fm": {}, "body": body, "body_sha256": _sha(body)}}
        for doc_id, (kind, body) in served.items()
    ]
    block_body = "Say it once.\n"
    ib_row = {
        "id": "platform/instruction-blocks/write-better",
        "project": "platform", "status": "current", "body": block_body,
        "body_hash": _sha(block_body),
        "frontmatter_extra": json.dumps({"scope": "fleet"}),
    }
    resolved_blocks = knowledge_ctx.resolve_instruction_blocks(
        [ib_row], crew=None, agent=None, session_kind="interactive")

    rc = knowledge_ctx.individuate(
        project="agent-platform", profile_name="daytime", profile={},
        target_repo=wt, rows=rows, force=False, force_anyway=False,
        dry_run=False, instruction_blocks=resolved_blocks,
    )
    assert rc == 0

    agent_hash = _sha((wt / ".claude" / "agents" / "coder.md").read_text())
    skill_hash = _sha((wt / ".claude" / "skills" / "run" / "SKILL.md").read_text())

    # Captured right after individuation, before the agent subprocess this
    # run would otherwise start — exactly what `_spawn_dispatch` does.
    captured = agentctl._materialized_documents(wt)

    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
        final_event={"type": "result", "subtype": "success"},
        profile="agent-platform/daytime", agent={"model_alias": "sonnet"},
        materialized_documents=captured,
    )

    shutil.rmtree(wt)

    docs = {d["id"]: d for d in
           json.loads((rd / "docs_consulted.json").read_text())["docs"]}
    assert docs["agent-platform/agents/coder"] == {
        "id": "agent-platform/agents/coder", "kind": "agent",
        "body_sha256": agent_hash}
    assert docs["agent-platform/skills/run"] == {
        "id": "agent-platform/skills/run", "kind": "skill",
        "body_sha256": skill_hash}
    assert docs["platform/decisions/0082"] == {
        "id": "platform/decisions/0082", "kind": "decision",
        "body_sha256": _sha(decision_body)}
    assert docs["platform/instruction-blocks/write-better"] == {
        "id": "platform/instruction-blocks/write-better", "kind": "instruction-block",
        "body_sha256": _sha(block_body), "scope": "fleet"}


def test_finalize_run_ignores_a_rewrite_of_profile_documents_json_made_after_capture(
        agentctl, tmp_path, monkeypatch):
    """Security review, PR #740 round 1: `_materialized_documents` must be
    called ONCE, at dispatch time, with the result threaded through to
    `_finalize_run` as a parameter — never read again, later, by
    `_finalize_run` itself. A run's own subprocess has the worktree's
    `.claude/.profile-documents.json` writable for its ENTIRE execution
    window, so a `_finalize_run` that re-read the file after the subprocess
    exited would let that run add, change or delete rows in the very
    accountability record this feature exists to build. This proves the
    threading holds: a rewrite made to the file AFTER the capture has no
    effect on what `_finalize_run` records."""
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)
    claude = wt / ".claude"
    claude.mkdir(exist_ok=True)
    real_hash = "a" * 64
    (claude / ".profile-documents.json").write_text(json.dumps({
        "documents": [{"id": "real/doc", "kind": "decision",
                       "body_sha256": real_hash}],
    }))

    # "Dispatch time": the capture _spawn_dispatch makes right after
    # individuation, before any subprocess exists.
    captured = agentctl._materialized_documents(wt)
    assert captured == [{"id": "real/doc", "kind": "decision",
                         "body_sha256": real_hash}]

    # The run's own subprocess rewrites the file before exiting: adds a
    # forged row and drops the real one.
    forged_hash = "f" * 64
    (claude / ".profile-documents.json").write_text(json.dumps({
        "documents": [{"id": "forged/doc", "kind": "decision",
                       "body_sha256": forged_hash}],
    }))

    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
        final_event={"type": "result", "subtype": "success"},
        profile="agent-platform/daytime", agent={"model_alias": "sonnet"},
        materialized_documents=captured,
    )

    docs = json.loads((rd / "docs_consulted.json").read_text())["docs"]
    assert docs == [{"id": "real/doc", "kind": "decision", "body_sha256": real_hash}]
    assert "forged/doc" not in json.dumps(docs)


def test_materialized_documents_refuses_a_symlink(agentctl, tmp_path):
    """A run that replaces `.profile-documents.json` with a symlink (to
    `/dev/zero`, or anywhere else the operator's account can read) must get
    an empty list, not a followed read — `lstat` refuses it before any
    `open()` is attempted."""
    wt = tmp_path / "wt"
    (wt / ".claude").mkdir(parents=True)
    real = tmp_path / "elsewhere.json"
    real.write_text(json.dumps({"documents": [
        {"id": "x", "kind": "decision", "body_sha256": "a" * 64}]}))
    (wt / ".claude" / ".profile-documents.json").symlink_to(real)
    assert agentctl._materialized_documents(wt) == []


def test_materialized_documents_refuses_an_oversized_file(agentctl, tmp_path, monkeypatch):
    """A file past `_MAX_PROFILE_DOCUMENTS_BYTES` is refused rather than
    accepted off a truncated read — a run could otherwise grow this file
    without bound before exiting.

    The cap is set to exactly the length of the real JSON content (plus
    trailing padding past it), so the capped `cap + 1`-byte read captures
    the COMPLETE, validly-parsing record either way — only the explicit
    length check tells "oversized" apart from "coincidentally valid once
    truncated". A cap check that used a smaller cap and relied on the read
    truncating valid JSON into a parse error would pass by accident even if
    the explicit check were removed, which is exactly what a first version
    of this test did."""
    content = json.dumps({
        "documents": [{"id": "x", "kind": "decision", "body_sha256": "a" * 64}]})
    monkeypatch.setattr(agentctl, "_MAX_PROFILE_DOCUMENTS_BYTES", len(content))
    wt = tmp_path / "wt"
    (wt / ".claude").mkdir(parents=True)
    (wt / ".claude" / ".profile-documents.json").write_text(content + " " * 50)
    assert agentctl._materialized_documents(wt) == []


def test_materialized_documents_does_not_block_on_a_fifo(agentctl, tmp_path):
    """`open(2)` on a FIFO with no writer blocks at the syscall until one
    appears. Run in a subprocess with a hard stdlib timeout: an actual
    regression here would otherwise hang this whole test run, not just this
    test (mirrors `test_frontmatter_from_disk_does_not_block_on_a_fifo` in
    `tests/test_knowledge_ctx.py`, the same failure class reproduced
    against the sibling file this guard matches)."""
    wt = tmp_path / "wt"
    (wt / ".claude").mkdir(parents=True)
    os.mkfifo(wt / ".claude" / ".profile-documents.json")
    ac_path = Path(agentctl.__file__).resolve()
    script = (
        "import sys, importlib.util, importlib.machinery, pathlib\n"
        f"loader = importlib.machinery.SourceFileLoader('ac', {str(ac_path)!r})\n"
        "spec = importlib.util.spec_from_loader('ac', loader)\n"
        "ac = importlib.util.module_from_spec(spec)\n"
        "loader.exec_module(ac)\n"
        f"docs = ac._materialized_documents(pathlib.Path({str(wt)!r}))\n"
        "print('DONE', docs)\n"
    )
    proc = subprocess.run([sys.executable, "-c", script],
                          capture_output=True, text=True, timeout=10)
    assert proc.returncode == 0, proc.stderr
    assert "DONE []" in proc.stdout


def test_a_missing_remote_tracking_main_refuses_the_dispatch(
        agentctl, tmp_path, monkeypatch, runs_root, capsys):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    # A TAG of the same name is what `rev-parse origin/main` would answer with
    # once the branch ref is gone (agent-platform#681, #682).
    _git_ok(s.primary, "tag", "origin/main", s.local_main)
    _git_ok(s.primary, "update-ref", "-d", "refs/remotes/origin/main")
    assert _git_ok(s.primary, "rev-parse", "origin/main") == s.local_main
    before = _primary_claude_bytes(s.primary)
    rc, run_id = agentctl._spawn_dispatch(s.args)
    assert (rc, run_id) == (2, None)
    err = capsys.readouterr().err
    assert "refs/remotes/origin/main does not exist" in err
    assert "git fetch origin" in err
    assert not s.log.exists(), "knowledge-ctx ran despite the refusal"
    assert not (s.root / "worktrees").exists()
    assert _primary_claude_bytes(s.primary) == before


def test_a_tag_named_origin_main_does_not_move_the_base(
        agentctl, tmp_path, monkeypatch, runs_root):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    _git_ok(s.primary, "tag", "origin/main", s.local_main)
    wt, _ = _dispatch_to_the_render(agentctl, s)
    assert _git_ok(wt, "rev-parse", "HEAD") == s.remote_main


def test_a_coder_dispatch_branches_from_origin_main(agentctl, tmp_path, monkeypatch, runs_root):
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="coder")
    wt, call = _dispatch_to_the_render(agentctl, s)
    assert call["argv"][call["argv"].index("--agent") + 1] == "coder"
    # still its own named branch, now cut from origin/main rather than a stale local main
    assert _git_ok(wt, "symbolic-ref", "--short", "HEAD").startswith("agent/coder-")
    assert _git_ok(wt, "rev-parse", "HEAD") == s.remote_main


# --- swift resolve's meta.json fields, through a real dispatch (round-1 reviewer finding) ---
#
# The call-site tests above stop right after the resolve decision (or, for the
# failure case, right after the refusal) and never reach `run_dir`/meta.json at
# all. These drive a real `_spawn_dispatch` to completion via `--dry-run`
# (`_dispatch_to_completion`) so `swift_resolve_exit_code`/`swift_resolve_duration_s`/
# `swift_resolve_skipped` are checked the way `agentctl status` would actually
# read them, not just inferred from the write-site code.

def _stub_activate_profile_no_ps(agentctl, monkeypatch):
    """Real `activate_profile` shells out to `ps` (`_ancestor_pids`, for
    knowledge-ctx's `--exempt-pid`) before it ever reaches knowledge-ctx —
    unrelated to anything these tests check, and this sandbox's own Bash tool
    denies `ps` outright. Same stand-in `test_a_rendered_dispatch_still_
    captures_and_records_its_own_document_set` already uses for the same
    reason."""
    def _fake(worktree, profile, *, dry_run, agent, issue, allow_default, loaded):
        (worktree / ".claude").mkdir(parents=True, exist_ok=True)
        (worktree / ".claude" / ".profile-documents.json").write_text(
            json.dumps({"documents": []}))
        loaded["profile"] = profile
        loaded["profile_documents_current"] = True
        return None
    monkeypatch.setattr(agentctl, "activate_profile", _fake)


def _push_swift_package_onto_origin(tmp_path, s):
    """Commits Package.swift + Package.resolved onto origin's main — on top of
    whatever `_detached_main_setup` already pushed there — and fetches the
    result into `s.primary`. A worktree freshly branched from origin/main
    (what every non-`--pr` dispatch in this module creates) therefore carries
    them as part of its own HEAD, identical to origin/main's by construction;
    no hand-built divergence or stubbing is needed for the matching case."""
    remote = tmp_path / "remote.git"
    clone = tmp_path / "swift-seed"
    _git_ok(tmp_path, "clone", "-q", str(remote), str(clone))
    (clone / "Package.swift").write_text("// swift-tools-version:5.9\n")
    (clone / "Package.resolved").write_text('{"pins": []}\n')
    _git_ok(clone, "add", "-A")
    _git_ok(clone, "commit", "-q", "-m", "add Package.swift")
    _git_ok(clone, "push", "-q", "origin", "main")
    _git_ok(s.primary, "fetch", "-q", "origin")


def test_swift_resolve_exit_code_and_duration_land_in_meta_json(
        agentctl, tmp_path, monkeypatch, runs_root):
    """Reviewer finding, round 1: `swift_resolve_exit_code`/`swift_resolve_duration_s`
    must actually land in a real run's meta.json, not just look correct by
    inspection of the write sites. Fails against a head that writes the
    fields under the wrong key, on the wrong branch, or not at all — this
    reads meta.json back rather than asserting on the `T.update_meta` call."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="coder")
    _push_swift_package_onto_origin(tmp_path, s)
    fake_bin = tmp_path / "bin"
    fake_bin.mkdir()
    marker = tmp_path / "calls.txt"
    _stub_swift_for_spawn(fake_bin, marker)
    monkeypatch.setenv("PATH", f"{fake_bin}:{os.environ['PATH']}")
    _stub_activate_profile_no_ps(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)

    assert rc == 0
    assert marker.exists(), "a coder dispatch whose manifest matches origin/main must resolve"
    meta = json.loads((agentctl.T.run_dir(run_id) / "meta.json").read_text())
    assert meta["swift_resolve_exit_code"] == 0
    assert isinstance(meta["swift_resolve_duration_s"], float)
    assert meta["swift_resolve_duration_s"] >= 0
    assert "swift_resolve_skipped" not in meta


def test_swift_resolve_skipped_reason_lands_in_meta_json_for_a_differing_manifest(
        agentctl, tmp_path, monkeypatch, runs_root):
    """Mirrors the test above for the skip path: the gate's reason must land in
    meta.json as `swift_resolve_skipped`, not only reach the early-exit stderr
    print that `test_spawn_skips_swift_resolve_when_the_manifest_differs_from_
    origin_main` checks (that test stops before `run_dir` even exists)."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="coder")
    _push_swift_package_onto_origin(tmp_path, s)
    fake_bin = tmp_path / "bin"
    fake_bin.mkdir()
    marker = tmp_path / "calls.txt"
    _stub_swift_for_spawn(fake_bin, marker)
    monkeypatch.setenv("PATH", f"{fake_bin}:{os.environ['PATH']}")
    _stub_swift_worktree_match(agentctl, monkeypatch, matches=False,
                         reason="worktree has local changes relative to origin/main")
    _stub_activate_profile_no_ps(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)

    assert rc == 0
    assert not marker.exists(), "a skipped resolve must never invoke swift"
    meta = json.loads((agentctl.T.run_dir(run_id) / "meta.json").read_text())
    assert meta["swift_resolve_skipped"] == "worktree has local changes relative to origin/main"
    assert "swift_resolve_exit_code" not in meta


