def test_docs_merge_merges_pinned_to_the_checked_head_not_dry_run(
        agentctl, monkeypatch, tmp_path, capsys):
    import docs_merge as DM
    calls = []
    _setup_docs(agentctl, monkeypatch, tmp_path)
    monkeypatch.setattr(DM, "merge_pr",
                        lambda number, sha, token, repo, **k: calls.append((number, sha, token, repo))
                        or (True, "merged as " + "f" * 12))
    args = argparse.Namespace(pr=7, repo=DOCS_REPO, dry_run=False)
