def test_a_failover_the_library_cannot_answer_for_is_refused_and_recorded(
        agentctl, tmp_path, monkeypatch):
    """The fail-over respawn is a new dispatch of a different model, so it needs its own
    policy. When the Library does not answer for it, the fail-over is refused and the run
    is finalised with the reason, rather than the respawn running on the floor."""
    import policy_client
    fallback = "deepseek/deepseek-flash"

    def _answer(agent, crew, model):
        if model == fallback:
            raise policy_client.PolicyUnavailable("timed out after 6s")
        return dict(_ROUND6_LIVE_RECORD, model=model)
    monkeypatch.setattr(policy_client, "resolve", _answer)
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    rc, meta, _ = _run_fallback_session(agentctl, tmp_path, monkeypatch, marker=False,
                                        origin="scheduled", floor="deepseek")
    assert rc == 1
    assert "fallback_from" not in meta, "the respawn ran without its policy"
    assert meta["fallback_blocked_to"] == fallback
    reason = meta["fallback_blocked_reason"]
    assert "timed out after" in reason
    assert "the fail-over agent was not started" in reason
    assert "Nothing was dispatched" not in reason, "the first agent ran and died"
    assert "no agent was started" not in reason, "the first agent ran and died"


# --- the posted verdict and PR, recorded in the run (CQ·399) ----------------
# A stamp's verdict and PR must be the ones its run recorded when it posted, and
# the PR must be the one the gate evaluates. The forged stamps below are copies of
# real ones: the copy is what a worker can produce from a PR comment it can read.

def _post_review(agentctl, tmp_path, monkeypatch, *, verdict, pr="7", run_id="run-test"):
    """A real, non-dry `review-post` by `run_id`, with the Library write and the gh
    comment stubbed. Returns (rc, every `gh` command that ran)."""
    body = _review_post_body(tmp_path, "Reviewed.\n")
    import issue_client
    monkeypatch.setattr(issue_client, "post_review_record",
                        lambda fields, **kw: {"status": "ok", "record": {"id": "rec_1"}})
    gh_calls = []

    def fake_run(cmd, **kw):
        if cmd[:1] == ["gh"]:
            gh_calls.append(cmd)
        return type("R", (), {"returncode": 0, "stdout": "https://x/1", "stderr": ""})()
    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    rc = agentctl.main(["review-post", "--pr", pr, "--verdict", verdict,
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/agent-platform", "--reviewed-commit", _SHA,
                        "--run-id", run_id, "--no-auto-ready"])
    return rc, gh_calls


def test_review_post_records_its_verdict_and_pr_in_the_run(agentctl, monkeypatch, tmp_path):
    rd, _wt = _mk_findable_review_run_dir(agentctl, monkeypatch, tmp_path, pr="7")
    rc, gh_calls = _post_review(agentctl, tmp_path, monkeypatch, verdict="REQUEST_CHANGES")
    assert rc == 0 and any(c[:3] == ["gh", "pr", "comment"] for c in gh_calls)
    meta = json.loads((rd / "meta.json").read_text())
    assert meta.get("review_verdict") == "REQUEST_CHANGES"
    assert meta.get("review_pr") == "7"


def test_review_post_refuses_a_different_verdict_from_the_same_run(
        agentctl, monkeypatch, tmp_path, capsys):
    """A second post by the same run, with the other verdict, would replace the
    recorded one and let the earlier genuine stamp's copy-edit pass. It is refused
    before the Library write or the comment, and the record stays as it was."""
    rd, _wt = _mk_findable_review_run_dir(agentctl, monkeypatch, tmp_path, pr="7")
    rc, _ = _post_review(agentctl, tmp_path, monkeypatch, verdict="REQUEST_CHANGES")
    assert rc == 0
    monkeypatch.setattr(agentctl, "_approve_blocked_by_ci", lambda **kw: None)
    rc, gh_calls = _post_review(agentctl, tmp_path, monkeypatch, verdict="APPROVE")
    assert rc == 2 and gh_calls == []
    assert "REQUEST_CHANGES" in capsys.readouterr().err
    meta = json.loads((rd / "meta.json").read_text())
    assert (meta.get("review_verdict"), meta.get("review_pr")) == ("REQUEST_CHANGES", "7")


